def resolve_window_style(config: dict, cfg_agent: dict) -> tuple[str, str | None]:
    """Resolve the supervised Windows launch style.

    Per-agent ``window_style`` wins over the global setting. Invalid values are
    rejected visibly by returning a warning and falling back to Hidden, which is
    the least-clutter default for unattended fleets.
    """
    config = config if isinstance(config, dict) else {}
    cfg_agent = cfg_agent if isinstance(cfg_agent, dict) else {}
    for source_name, src in (("per-agent", cfg_agent), ("global", config)):
        if "window_style" not in src:
            continue
        raw = src.get("window_style")
        if isinstance(raw, str):
            normalized = raw.strip().lower()
            if normalized in _WINDOW_STYLES:
                return _WINDOW_STYLES[normalized], None
        return (
            _WINDOW_STYLE_DEFAULT,
            f"invalid {source_name} window_style={raw!r}; expected hidden|minimized|normal; "
            "defaulting to hidden",
        )
    return _WINDOW_STYLE_DEFAULT, None


def resolve_stuck_after(config: dict, cfg_agent: dict) -> float:
    """The per-agent heartbeat-stale threshold (PURE). An explicit per-agent
    ``stuck_after_seconds`` wins; else a WRAPPED agent uses the per-CLI default
    (:data:`_WRAPPED_STUCK_AFTER_DEFAULTS`); else the global ``stuck_after_seconds``
    (config, then the built-in default). Non-wrapped agents keep the existing
    global behavior."""
    config = config if isinstance(config, dict) else {}
    gt = config.get("stuck_after_seconds")
    global_threshold = float(gt) if isinstance(gt, (int, float)) and not isinstance(
        gt, bool) else float(_DEFAULTS["stuck_after_seconds"])
    # Coerce to dict only when it IS a dict: a `... or {}` rescues only FALSY values,
    # so a TRUTHY non-dict cfg_agent (a corrupt/hand-edited supervisor.json per-agent
    # entry) would slip through and crash cfg_agent.get(...). Fixes the status/doctor
    # regression (via resolve_timing) AND a pre-existing supervise --report crash.
    cfg_agent = cfg_agent if isinstance(cfg_agent, dict) else {}
    v = cfg_agent.get("stuck_after_seconds")
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return float(v)
    if bool(cfg_agent.get("wrapped", False)):
        cli = cfg_agent.get("cli", "claude")
        return float(_WRAPPED_STUCK_AFTER_DEFAULTS.get(cli, global_threshold))
    return global_threshold


def resolve_dead_letter_caps(config: dict, cfg_agent: dict) -> tuple[int, int]:
    """The per-agent dead-letter caps (PURE): (K_poison, K_escalate). A per-agent
    ``dead_letter.{max_attempts,escalate_after_attempts}`` wins; else the global config
    block; else :data:`_DEFAULTS`. ``0`` disables that cap (debug only - the shipped
    default is ON). Mirrors resolve_stuck_after's per-agent->global->default chain."""
    defaults = _DEFAULTS["dead_letter"]
    # Coerce to dict only when it IS a dict (a `... or {}` rescues only FALSY values):
    # a corrupt supervisor.json with a truthy non-dict config / per-agent entry / nested
    # dead_letter block must NOT crash cap resolution (which would take down `wrap --loop`
    # startup and the planner). Same corrupt-config class as resolve_stuck_after.
    config = config if isinstance(config, dict) else {}
    cfg_agent = cfg_agent if isinstance(cfg_agent, dict) else {}
    gcfg = config.get("dead_letter")
    gcfg = gcfg if isinstance(gcfg, dict) else {}
    acfg = cfg_agent.get("dead_letter")
    acfg = acfg if isinstance(acfg, dict) else {}

    def _pick(key: str) -> int:
        for src in (acfg, gcfg):
            v = src.get(key)
            if isinstance(v, int) and not isinstance(v, bool) and v >= 0:
                return v
        return int(defaults[key])

    return _pick("max_attempts"), _pick("escalate_after_attempts")


def resolve_infra_retry_exhaustion(config: dict, cfg_agent: dict,
                                   k_escalate: int) -> dict:
    """Resolve the finite infra-exhaustion ceiling.

    This is intentionally separate from ``resolve_dead_letter_caps``: normal operator
    config cannot set 0/negative to mean "infinite" for prolonged infra retry.
    """
    default_after = int(_DEFAULTS["dead_letter"]["infra_exhaust_after_seconds"])
    safe_k = max(1, int(k_escalate) if isinstance(k_escalate, int) else 20)
    default_min = max(100, 5 * safe_k)
    default_noninfra = 2 * safe_k
    config = config if isinstance(config, dict) else {}
    cfg_agent = cfg_agent if isinstance(cfg_agent, dict) else {}
    gcfg = config.get("dead_letter")
    gcfg = gcfg if isinstance(gcfg, dict) else {}
    acfg = cfg_agent.get("dead_letter")
    acfg = acfg if isinstance(acfg, dict) else {}

    def _positive_number(key: str, default: float) -> float:
        for src in (acfg, gcfg):
            v = src.get(key)
            if isinstance(v, (int, float)) and not isinstance(v, bool) and v > 0:
                return float(v)
        return float(default)

    def _positive_int(key: str, default: int) -> int:
        for src in (acfg, gcfg):
            v = src.get(key)
            if isinstance(v, int) and not isinstance(v, bool) and v > 0:
                return v
        return int(default)

    return {
        "infra_exhaust_after_seconds": _positive_number(
            "infra_exhaust_after_seconds", default_after),
        "infra_exhaust_min_attempts": _positive_int(
            "infra_exhaust_min_attempts", default_min),
        "noninfra_sub_ceiling": _positive_int(
            "noninfra_sub_ceiling", default_noninfra),
    }


def resolve_restart_request_authority(
    store: Store,
    requested_by: str | None,
    *,
    force_protected: bool = False,
    acknowledge_live_protected_kill: bool = False,
) -> dict:
    """Resolve audited authority for ``request-restart``.

    Mirrors the stand-down envelope: a request is authorized only when the explicit
    requester is the configured operator-facing liaison, or the sole lead when no
    liaison is configured. There is no silent default requester.
    """
    if not isinstance(requested_by, str) or not requested_by.strip():
        return {
            "requested_by": requested_by,
            "authorized_by": None,
            "authority_result": "denied",
            "authority_reason": "missing explicit requested_by",
            "force_protected_authorized": False,
            "acknowledge_live_protected_kill_authorized": False,
        }
    liaison = store.operator_facing()
    sole = store.sole_lead()
    if store.loop_exit_relay_authorized(requested_by):
        reason = "operator_facing" if liaison and requested_by == liaison else "sole_lead"
        ack_live = bool(acknowledge_live_protected_kill and liaison and requested_by == liaison)
        return {
            "requested_by": requested_by,
            "authorized_by": requested_by,
            "authority_result": "authorized",
            "authority_reason": reason,
            "force_protected_authorized": bool(force_protected),
            "force_protected_authorized_by": requested_by if force_protected else None,
            "acknowledge_live_protected_kill_authorized": ack_live,
            "acknowledge_live_protected_kill_by": requested_by if ack_live else None,
        }
    return {
        "requested_by": requested_by,
        "authorized_by": None,
        "authority_result": "denied",
        "authority_reason": (
            "operator_facing required" if liaison else
            "sole_lead required" if sole else
            "no operator_facing or sole lead configured"
        ),
        "force_protected_authorized": False,
        "acknowledge_live_protected_kill_authorized": False,
    }


def resolve_health_timing(config: dict, cfg_agent: dict) -> dict:
    """Resolve advisory health freshness bounds.

    Per-agent ``health.{ttl_seconds,heartbeat_skew_seconds}`` wins over global
    ``health``. Legacy flat keys are accepted for operators hand-editing early
    configs. Health is advisory; these bounds only decide whether a health file
    reads as ``unknown``.
    """
    defaults = _DEFAULTS["health"]
    config = config if isinstance(config, dict) else {}
    cfg_agent = cfg_agent if isinstance(cfg_agent, dict) else {}
    g = config.get("health")
    g = g if isinstance(g, dict) else {}
    a = cfg_agent.get("health")
    a = a if isinstance(a, dict) else {}

    def _pick(key: str, flat: str) -> float:
        for src, src_key in ((a, key), (cfg_agent, flat), (g, key), (config, flat)):
            v = src.get(src_key)
            if isinstance(v, (int, float)) and not isinstance(v, bool) and v >= 0:
                return float(v)
        return float(defaults[key])

    return {
        "ttl_seconds": _pick("ttl_seconds", "health_ttl_seconds"),
        "heartbeat_skew_seconds": _pick(
            "heartbeat_skew_seconds", "health_heartbeat_skew_seconds"),
    }


def project_coordination_availability(
    name: str,
    report_agent: dict | None,
    plan_agent: dict | None,
    config_agent: dict | None,
    *,
    retired: bool = False,
) -> dict:
    """Pure, read-only responder availability for coordination warnings.

    This is deliberately narrower than the supervisor action table.  It does
    not grant kill/relaunch authority; it only classifies whether another agent
    can plausibly answer an explicit wait edge.  Missing evidence stays UNKNOWN.
    """
    if retired:
        return {
            "agent": name,
            "state": AVAILABILITY_TERMINAL,
            "subtype": "retired",
            "evidence_code": "retired_identity",
        }
    if not isinstance(report_agent, dict):
        return {
            "agent": name,
            "state": AVAILABILITY_UNKNOWN,
            "subtype": "missing_supervisor_evidence",
            "evidence_code": "report_missing",
        }
    rpt = report_agent if isinstance(report_agent, dict) else {}
    plan = plan_agent if isinstance(plan_agent, dict) else {}
    cfg = config_agent if isinstance(config_agent, dict) else {}
    health = rpt.get("health") if isinstance(rpt.get("health"), dict) else {}
    health_state = health_model.label(health)
    health_reason = health.get("reason_code") if isinstance(
        health.get("reason_code"), str) else None
    plan_state = plan.get("state") if isinstance(plan.get("state"), str) else None

    if plan_state == "LEAD_LOOP_STOOD_DOWN":
        return {
            "agent": name,
            "state": AVAILABILITY_TERMINAL,
            "subtype": "stood_down",
            "evidence_code": "lead_loop_stood_down",
        }
    if health_reason in _UNTRUSTED_TIME_REASONS:
        return {
            "agent": name,
            "state": AVAILABILITY_UNKNOWN,
            "subtype": "malformed_liveness",
            "evidence_code": health_reason,
        }
    if plan_state == "LAUNCHING":
        return {
            "agent": name,
            "state": AVAILABILITY_UNKNOWN,
            "subtype": "launch_grace",
            "evidence_code": "launch_grace",
        }
    if health_state in _EXPLICIT_UNAVAILABLE_HEALTH and health.get("stale") is not True:
        return {
            "agent": name,
            "state": AVAILABILITY_UNAVAILABLE,
            "subtype": "explicit_health_error",
            "evidence_code": health_state,
        }
    heartbeat_evidence = rpt.get("heartbeat_evidence")
    if heartbeat_evidence == HEARTBEAT_EVIDENCE_FUTURE_SKEW:
        return {
            "agent": name,
            "state": AVAILABILITY_UNKNOWN,
            "subtype": "heartbeat_time_untrusted",
            "evidence_code": "heartbeat_future_skew",
        }
    if (
        heartbeat_evidence is not None
        and heartbeat_evidence not in _HEARTBEAT_EVIDENCE_CLASSES
    ):
        return {
            "agent": name,
            "state": AVAILABILITY_UNKNOWN,
            "subtype": "malformed_liveness",
            "evidence_code": "heartbeat_evidence_invalid",
        }
    heartbeat_stale_value = rpt.get("heartbeat_stale")
    if heartbeat_stale_value is not True and heartbeat_stale_value is not False:
        return {
            "agent": name,
            "state": AVAILABILITY_UNKNOWN,
            "subtype": "malformed_liveness",
            "evidence_code": "heartbeat_state_missing",
        }
    heartbeat_stale = heartbeat_stale_value is True
    if not heartbeat_stale:
        if bool(cfg.get("wrapped", False)):
            if plan_state in {"HEALTHY_IDLE", "HEALTHY_WORKING"}:
                return {
                    "agent": name,
                    "state": AVAILABILITY_AVAILABLE,
                    "subtype": "wrapped_runtime_green",
                    "evidence_code": plan_state.lower(),
                }
            if plan_state in {
                "CLI_CHILD_DEAD",
                "CLI_CHILD_STALLED",
                "TURN_FAILED",
            }:
                return {
                    "agent": name,
                    "state": AVAILABILITY_UNAVAILABLE,
                    "subtype": "wrapped_cli_child_not_healthy",
                    "evidence_code": plan_state.lower(),
                }
            return {
                "agent": name,
                "state": AVAILABILITY_UNKNOWN,
                "subtype": "wrapped_cli_child_unresolved",
                "evidence_code": (
                    plan_state.lower() if plan_state else "plan_state_missing"
                ),
            }
        return {
            "agent": name,
            "state": AVAILABILITY_AVAILABLE,
            "subtype": "heartbeat_fresh",
            "evidence_code": "heartbeat_fresh",
        }

    heartbeat_expected = bool(cfg.get("wrapped") or cfg.get("activity_hook"))
    if not heartbeat_expected:
        return {
            "agent": name,
            "state": AVAILABILITY_UNKNOWN,
            "subtype": "heartbeat_not_authoritative",
            "evidence_code": "manual_or_uninstrumented",
        }
    if plan_state in {"ACTIVE_OR_BUSY", "RESTART_COOLDOWN", "RESTART_UNAUTHORIZED"}:
        return {
            "agent": name,
            "state": AVAILABILITY_UNKNOWN,
            "subtype": "supervisor_uncertain",
            "evidence_code": plan_state.lower(),
        }
    return {
        "agent": name,
        "state": AVAILABILITY_UNAVAILABLE,
        "subtype": "heartbeat_stale",
        "evidence_code": "heartbeat_stale_past_threshold",
    }


def _coordination_availability_path(store: Store) -> Path:
    return store.state_dir / _COORDINATION_AVAILABILITY_FILE


def read_coordination_availability_observation(store: Store) -> tuple[dict, list[dict]]:
    """Read the bounded two-poll debounce state, failing quiet on damage."""
    path = _coordination_availability_path(store)
    if not path.exists():
        return {}, []
    try:
        if path.stat().st_size > _COORDINATION_AVAILABILITY_MAX_BYTES:
            raise ValueError("oversized")
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError, json.JSONDecodeError):
        return {}, [{"code": "availability_observation_invalid"}]
    if (
        not isinstance(raw, dict)
        or frozenset(raw) != _COORDINATION_AVAILABILITY_FIELDS
        or raw.get("schema_version") != _COORDINATION_AVAILABILITY_SCHEMA
        or _event_epoch(raw.get("updated_at_epoch")) is None
    ):
        return {}, [{"code": "availability_observation_invalid"}]
    agents = raw.get("agents")
    if not isinstance(agents, dict) or len(agents) > 1024:
        return {}, [{"code": "availability_observation_invalid"}]
    clean: dict[str, dict] = {}
    problems: list[dict] = []
    for name, row in agents.items():
        invalid = (
            not isinstance(name, str)
            or _EVENT_TOKEN_RE.fullmatch(name) is None
            or not isinstance(row, dict)
            or frozenset(row) != _COORDINATION_AVAILABILITY_ROW_FIELDS
        )
        if invalid:
            if len(problems) < _COORDINATION_MAX_DIAGNOSTICS:
                problems.append({"code": "availability_observation_entry_invalid"})
            continue
        state = row.get("state")
        if state not in {
            AVAILABILITY_AVAILABLE,
            AVAILABILITY_UNAVAILABLE,
            AVAILABILITY_TERMINAL,
            AVAILABILITY_UNKNOWN,
        }:
            if len(problems) < _COORDINATION_MAX_DIAGNOSTICS:
                problems.append({"code": "availability_observation_entry_invalid"})
            continue
        consecutive = row.get("consecutive")
        first_epoch = _event_epoch(row.get("first_observed_epoch"))
        last_epoch = row.get("last_observed_epoch")
        if (
            not isinstance(row.get("subtype"), str)
            or _EVENT_TOKEN_RE.fullmatch(row["subtype"]) is None
            or not isinstance(row.get("evidence_code"), str)
            or _EVENT_TOKEN_RE.fullmatch(row["evidence_code"]) is None
            or not isinstance(consecutive, int)
            or isinstance(consecutive, bool)
            or consecutive < 1
            or first_epoch is None
            or not isinstance(last_epoch, (int, float))
            or isinstance(last_epoch, bool)
            or not math.isfinite(float(last_epoch))
            or float(last_epoch) < first_epoch
        ):
            if len(problems) < _COORDINATION_MAX_DIAGNOSTICS:
                problems.append({"code": "availability_observation_entry_invalid"})
            continue
        clean[name] = {
            "state": state,
            "subtype": row["subtype"],
            "evidence_code": row["evidence_code"],
            "consecutive": consecutive,
            "first_observed_epoch": first_epoch,
            "last_observed_epoch": float(last_epoch),
        }
    return clean, problems


def record_coordination_availability_observation(
    store: Store,
    report: dict,
    plan: dict,
    config: dict,
    *,
    now_epoch: float,
) -> None:
    """Best-effort supervisor-cadence debounce bookkeeping.

    Planning output is an input only and is never changed.  Two consecutive
    semantically identical projections are required before a detector may warn.
    """
    try:
        prior, _ = read_coordination_availability_observation(store)
        report_agents = report.get("agents") if isinstance(report.get("agents"), dict) else {}
        plan_agents = plan.get("agents") if isinstance(plan.get("agents"), dict) else {}
        config_agents = config.get("agents") if isinstance(config.get("agents"), dict) else {}
        retired = set(store.retired_agents())
        poll = config.get("poll_seconds", _DEFAULTS["poll_seconds"])
        poll = float(poll) if isinstance(poll, (int, float)) and not isinstance(poll, bool) else 15.0
        max_gap = max(5.0, poll * 3.0)
        rows: dict[str, dict] = {}
        names = set(report_agents) | set(config_agents) | retired
        for name in sorted(names):
            projection = project_coordination_availability(
                name,
                report_agents.get(name),
                plan_agents.get(name),
                config_agents.get(name),
                retired=name in retired,
            )
            old = prior.get(name) if isinstance(prior.get(name), dict) else {}
            same = all(old.get(key) == projection.get(key) for key in (
                "state", "subtype", "evidence_code"))
            last = old.get("last_observed_epoch")
            contiguous = (
                same
                and isinstance(last, (int, float))
                and 0 <= float(now_epoch) - float(last) <= max_gap
            )
            rows[name] = {
                "state": projection["state"],
                "subtype": projection["subtype"],
                "evidence_code": projection["evidence_code"],
                "consecutive": int(old.get("consecutive", 0)) + 1 if contiguous else 1,
                "first_observed_epoch": (
                    old.get("first_observed_epoch") if contiguous else float(now_epoch)
                ),
                "last_observed_epoch": float(now_epoch),
            }
        payload = {
            "schema_version": _COORDINATION_AVAILABILITY_SCHEMA,
            "updated_at_epoch": float(now_epoch),
            "agents": rows,
        }
        with store._config_lock(timeout=0.05, poll=0.01):
            _atomic_write_text(
                _coordination_availability_path(store),
                json.dumps(payload, ensure_ascii=False, sort_keys=True),
            )
    except Exception:
        return


def _restart_request_with_live_authority(store: Store, marker: dict | None) -> dict | None:
    if not isinstance(marker, dict):
        return marker
    out = dict(marker)
    authority = resolve_restart_request_authority(
        store,
        out.get("requested_by"),
        force_protected=bool(out.get("force_protected")),
        acknowledge_live_protected_kill=bool(
            out.get("acknowledge_live_protected_kill")),
    )
    out["authority_still_valid"] = (
        authority.get("authority_result") == "authorized"
        and authority.get("authorized_by") == out.get("requested_by")
    )
    out["force_protected_still_authorized"] = bool(
        authority.get("force_protected_authorized"))
    out["acknowledge_live_protected_kill_still_authorized"] = bool(
        authority.get("acknowledge_live_protected_kill_authorized"))
    out["authority_live_reason"] = authority.get("authority_reason")
    return out


def supervisor_events_path(store: Store) -> Path:
    return store.state_dir / "supervisor-events.jsonl"


def _event_now(now_epoch: float) -> str:
    return datetime.fromtimestamp(now_epoch, timezone.utc).isoformat().replace("+00:00", "Z")


def _event_token(value: object, default: str = "unknown") -> str:
    if isinstance(value, str) and _EVENT_TOKEN_RE.fullmatch(value):
        return value
    return default


def _event_bool(value: object) -> bool:
    return value is True


def _event_nonnegative_int(value: object) -> int:
    if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
        return value
    return 0


def _event_epoch(value: object) -> float | None:
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        epoch = float(value)
        if math.isfinite(epoch):
            return epoch
    return None


def _decision_reason_code(plan: dict) -> str:
    explicit = _event_token(plan.get("reason_code"), "")
    if explicit:
        return explicit.lower()
    health = plan.get("health") if isinstance(plan.get("health"), dict) else {}
    warnings = health.get("warnings") if isinstance(health.get("warnings"), list) else []
    if "advisory-health-conflict" in warnings:
        return "advisory-health-conflict"
    state = _event_token(plan.get("state"), "")
    if state:
        return state.lower()
    return _event_token(plan.get("action"), "unknown").lower()


def _decision_fingerprint(agent: str, plan: dict) -> str:
    parts = [
        _event_token(agent),
        _event_token(plan.get("action")),
        _event_token(plan.get("state")),
        _decision_reason_code(plan),
        "notify" if plan.get("notify") is True else "silent",
        "clear" if isinstance(plan.get("clear_marker"), str) else "keep",
    ]
    return "|".join(parts)


def _stored_decision_fingerprint(event: dict) -> str:
    parts = [
        _event_token(event.get("agent")),
        _event_token(event.get("action")),
        _event_token(event.get("state")),
        _event_token(event.get("reason_code")),
        "notify" if event.get("notify") is True else "silent",
        "clear" if event.get("clear_marker") is True else "keep",
    ]
    return "|".join(parts)


def _sanitize_agent_decision_event(obj: dict) -> dict:
    event: dict[str, object] = {
        "schema_version": 1,
        "kind": "agent_decision",
        "at": _event_token(obj.get("at")),
        "agent": _event_token(obj.get("agent")),
        "action": _event_token(obj.get("action")),
        "state": _event_token(obj.get("state")),
        "reason_code": _event_token(obj.get("reason_code")),
        "notify": _event_bool(obj.get("notify")),
        "clear_marker": _event_bool(obj.get("clear_marker")),
    }
    at_epoch = _event_epoch(obj.get("at_epoch"))
    if at_epoch is not None:
        event["at_epoch"] = at_epoch
    event["fingerprint"] = _stored_decision_fingerprint(event)
    return event


def _sanitize_summary_states(value: object) -> dict[str, int]:
    if not isinstance(value, dict):
        return {}
    states: dict[str, int] = {}
    for raw_state, raw_count in value.items():
        state = _event_token(raw_state)
        states[state] = states.get(state, 0) + _event_nonnegative_int(raw_count)
    return states


def _sanitize_poll_summary_event(obj: dict) -> dict:
    event: dict[str, object] = {
        "schema_version": 1,
        "kind": "poll_summary",
        "at": _event_token(obj.get("at")),
        "planned_agents": _event_nonnegative_int(obj.get("planned_agents")),
        "healthy_idle": _event_nonnegative_int(obj.get("healthy_idle")),
        "states": _sanitize_summary_states(obj.get("states")),
    }
    at_epoch = _event_epoch(obj.get("at_epoch"))
    if at_epoch is not None:
        event["at_epoch"] = at_epoch
    return event


def _sanitize_supervisor_event(obj: dict) -> dict | None:
    kind = _event_token(obj.get("kind"), "")
    if kind == "agent_decision":
        return _sanitize_agent_decision_event(obj)
    if kind == "poll_summary":
        return _sanitize_poll_summary_event(obj)
    return None


def read_supervisor_events(store: Store, *, limit: int | None = None) -> tuple[list[dict], list[str]]:
    """Read the supervisor decision-event ring fail-safe.

    The reader tails a fixed byte budget before JSON parsing, so even an externally
    bloated file cannot make status/supervisor reads scan unbounded history. Rows
    are normalized to the known token-only event schemas before any caller sees or
    uses them, so a pre-existing polluted ring cannot leak free text through reads.
    """
    path = supervisor_events_path(store)
    if not path.exists():
        return [], []
    warnings: list[str] = []
    try:
        with path.open("rb") as f:
            f.seek(0, 2)
            size = f.tell()
            if size > SUPERVISOR_EVENT_TAIL_BYTES:
                f.seek(-SUPERVISOR_EVENT_TAIL_BYTES, 2)
                warnings.append("supervisor_events_tail_truncated")
            else:
                f.seek(0)
            raw = f.read()
    except OSError as exc:
        return [], [f"supervisor_events_unreadable:{type(exc).__name__}"]
    text = raw.decode("utf-8", "replace")
    lines = text.splitlines()
    if warnings and lines:
        lines = lines[1:]  # likely a partial first line after a tail seek
    events: list[dict] = []
    for idx, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            warnings.append(f"supervisor_events_torn:{idx}")
            continue
        if not isinstance(obj, dict):
            warnings.append(f"supervisor_events_malformed:{idx}")
            continue
        event = _sanitize_supervisor_event(obj)
        if event is None:
            warnings.append(f"supervisor_events_malformed:{idx}")
            continue
        if event != obj:
            warnings.append(f"supervisor_events_sanitized:{idx}")
        events.append(event)
    if isinstance(limit, int) and limit >= 0:
        events = events[-limit:] if limit else []
    return events, warnings


def append_supervisor_events(store: Store, events: list[dict], *,
                             cap: int = SUPERVISOR_EVENT_RING_CAP) -> None:
    """Best-effort bounded JSONL append implemented as read/cap/rewrite."""
    if not events:
        return
    clean_events: list[dict] = []
    for event in events:
        if not isinstance(event, dict):
            continue
        clean = _sanitize_supervisor_event(event)
        if clean is not None:
            clean_events.append(clean)
    if not clean_events:
        return
    cap = cap if isinstance(cap, int) and cap > 0 else SUPERVISOR_EVENT_RING_CAP
    try:
        with store._config_lock(timeout=0.05, poll=0.01):
            prior, _ = read_supervisor_events(store)
            kept = [*prior, *clean_events][-cap:]
            path = supervisor_events_path(store)
            path.parent.mkdir(parents=True, exist_ok=True)
            text = "".join(
                json.dumps(e, ensure_ascii=False, sort_keys=True, allow_nan=False) + "\n"
                for e in kept
            )
            _atomic_write_text(path, text)
    except Exception:
        return


def _decision_event(agent: str, plan: dict, *, now_epoch: float) -> dict:
    fingerprint = _decision_fingerprint(agent, plan)
    return {
        "schema_version": 1,
        "kind": "agent_decision",
        "at": _event_now(now_epoch),
        "at_epoch": float(now_epoch),
        "agent": _event_token(agent),
        "action": _event_token(plan.get("action")),
        "state": _event_token(plan.get("state")),
        "reason_code": _decision_reason_code(plan),
        "notify": plan.get("notify") is True,
        "clear_marker": isinstance(plan.get("clear_marker"), str),
        "fingerprint": fingerprint,
    }


def _summary_event(plan: dict, *, now_epoch: float) -> dict:
    agents = plan.get("agents") if isinstance(plan.get("agents"), dict) else {}
    states: dict[str, int] = {}
    healthy = 0
    for p in agents.values():
        if not isinstance(p, dict):
            continue
        state = _event_token(p.get("state"))
        states[state] = states.get(state, 0) + 1
        if state == "HEALTHY_IDLE":
            healthy += 1
    return {
        "schema_version": 1,
        "kind": "poll_summary",
        "at": _event_now(now_epoch),
        "at_epoch": float(now_epoch),
        "planned_agents": len(agents),
        "healthy_idle": healthy,
        "states": states,
    }


def record_supervisor_plan_events(store: Store, plan: dict, *,
                                  now_epoch: float,
                                  cap: int = SUPERVISOR_EVENT_RING_CAP,
                                  summary_interval_seconds: float =
                                  SUPERVISOR_EVENT_SUMMARY_INTERVAL_SECONDS) -> None:
    """Append redacted supervisor decision events once per transition.

    Events contain planner tokens only: action, state, booleans, and bounded
    reason codes. Free-form plan reasons, restart reasons, command lines, and
    config-blocked summaries are deliberately not representable.
    """
    try:
        agents = plan.get("agents") if isinstance(plan.get("agents"), dict) else {}
        prior, _ = read_supervisor_events(store)
        last_fp: dict[str, str] = {}
        last_summary_epoch: float | None = None
        for event in prior:
            if event.get("kind") == "agent_decision":
                if event.get("action") == _LAUNCH_BARRIER_ACTION:
                    continue
                agent = event.get("agent")
                fp = event.get("fingerprint")
                if isinstance(agent, str) and isinstance(fp, str):
                    last_fp[agent] = fp
            elif event.get("kind") == "poll_summary":
                ts = event.get("at_epoch")
                if isinstance(ts, (int, float)):
                    last_summary_epoch = float(ts)
        new_events: list[dict] = []
        for agent in sorted(agents):
            p = agents.get(agent)
            if not isinstance(p, dict):
                continue
            fp = _decision_fingerprint(agent, p)
            if last_fp.get(agent) != fp:
                new_events.append(_decision_event(agent, p, now_epoch=now_epoch))
        if (last_summary_epoch is None
                or now_epoch - last_summary_epoch >= float(summary_interval_seconds)):
            new_events.append(_summary_event(plan, now_epoch=now_epoch))
        append_supervisor_events(store, new_events, cap=cap)
    except Exception:
        return


def record_supervisor_launch_barrier_event(store: Store, agent: str, *,
                                           reason_code: str, now_epoch: float,
                                           cap: int = SUPERVISOR_EVENT_RING_CAP) -> None:
    """Append a deduped post-kill launch-barrier decision event.

    The generated executor records the normal plan first, then this only when a
    fresh post-kill snapshot refuses launch. Dedupe is against the last agent
    decision fingerprint, so a steady barrier does not flood the ring.
    """
    try:
        plan = {
            "action": _LAUNCH_BARRIER_ACTION,
            "state": "LAUNCH_BLOCKED",
            "reason_code": reason_code,
            "notify": True,
        }
        fp = _decision_fingerprint(agent, plan)
        prior, _ = read_supervisor_events(store)
        for event in reversed(prior):
            if event.get("kind") == "agent_decision" and event.get("agent") == _event_token(agent):
                if event.get("action") != _LAUNCH_BARRIER_ACTION:
                    continue
                if event.get("fingerprint") == fp:
                    return
                break
        append_supervisor_events(store, [_decision_event(agent, plan, now_epoch=now_epoch)], cap=cap)
    except Exception:
        return


def _coordination_barrier_path(store: Store, agent: str) -> Path:
    return store.state_dir / _COORDINATION_BARRIER_DIR / f"{validate_agent_name(agent)}.json"


def read_coordination_barrier_observations(store: Store) -> tuple[list[dict], list[dict]]:
    """Read strict manual-restart barrier observations, skipping damaged rows."""
    root = store.state_dir / _COORDINATION_BARRIER_DIR
    if not root.is_dir():
        return [], []
    rows: list[dict] = []
    problems: list[dict] = []
    paths = []
    for index, path in enumerate(root.glob("*.json")):
        if index >= 256:
            problems.append({"code": "restart_barrier_observation_limit_reached"})
            break
        paths.append(path)
    for path in sorted(paths):
        try:
            if path.stat().st_size > _COORDINATION_BARRIER_MAX_BYTES:
                raise ValueError("oversized")
            raw = json.loads(path.read_text(encoding="utf-8"))
            if (
                not isinstance(raw, dict)
                or frozenset(raw) != _COORDINATION_BARRIER_FIELDS
                or raw.get("schema_version") != _COORDINATION_BARRIER_SCHEMA
            ):
                raise ValueError("schema")
            agent = validate_agent_name(raw.get("agent"))
            request_id = raw.get("request_id")
            fingerprint = raw.get("survivor_fingerprint")
            if (
                path.stem != agent
                or not isinstance(request_id, str)
                or _EVENT_TOKEN_RE.fullmatch(request_id) is None
                or not isinstance(fingerprint, str)
                or re.fullmatch(r"[0-9a-f]{64}", fingerprint) is None
                or raw.get("blocked") is not True
                or not isinstance(raw.get("barrier_reason"), str)
                or _EVENT_TOKEN_RE.fullmatch(raw["barrier_reason"]) is None
            ):
                raise ValueError("identity")
            marker_epoch = _event_epoch(raw.get("marker_epoch"))
            first_epoch = _event_epoch(raw.get("first_observed_epoch"))
            last_epoch = _event_epoch(raw.get("last_observed_epoch"))
            consecutive = raw.get("consecutive_blocked_polls")
            if (
                marker_epoch is None
                or first_epoch is None
                or last_epoch is None
                or not isinstance(consecutive, int)
                or isinstance(consecutive, bool)
                or consecutive < 1
                or first_epoch < marker_epoch
                or last_epoch < first_epoch
            ):
                raise ValueError("timing")
            rows.append({
                "schema_version": _COORDINATION_BARRIER_SCHEMA,
                "agent": agent,
                "request_id": request_id,
                "marker_epoch": marker_epoch,
                "barrier_reason": raw["barrier_reason"],
                "survivor_fingerprint": fingerprint,
                "blocked": True,
                "first_observed_epoch": first_epoch,
                "last_observed_epoch": last_epoch,
                "consecutive_blocked_polls": consecutive,
            })
        except (OSError, TypeError, ValueError, json.JSONDecodeError):
            if len(problems) < _COORDINATION_MAX_DIAGNOSTICS:
                problems.append({
                    "code": "restart_barrier_observation_invalid",
                    "path": path.name,
                })
    return rows, problems


def record_supervisor_launch_barrier_observation(
    store: Store,
    agent: str,
    barrier: dict,
    *,
    now_epoch: float,
) -> None:
    """Record or clear the observational two-poll manual-restart barrier state.

    Only a current manual restart marker can create state.  Automatic stale
    recovery has no request id and is intentionally excluded.  A clear barrier
    deletes the observation; the detector independently re-checks the live
    marker id/epoch before projecting anything.
    """
    try:
        path = _coordination_barrier_path(store, agent)
        with store._config_lock(timeout=0.05, poll=0.01):
            if not isinstance(barrier, dict) or barrier.get("blocked") is not True:
                try:
                    path.unlink()
                except FileNotFoundError:
                    pass
                return
            marker = store.read_restart_request(agent)
            if not isinstance(marker, dict) or marker.get("source") != "manual":
                return
            request_id = marker.get("request_id")
            marker_epoch = _event_epoch(marker.get("at_epoch"))
            if (
                not isinstance(request_id, str)
                or _EVENT_TOKEN_RE.fullmatch(request_id) is None
                or marker_epoch is None
            ):
                return
            survivors = []
            raw_survivors = barrier.get("survivors")
            if isinstance(raw_survivors, list):
                for row in raw_survivors[:8]:
                    if not isinstance(row, dict):
                        continue
                    survivors.append({
                        "kind": _event_token(row.get("kind")),
                        "pid": row.get("pid") if isinstance(row.get("pid"), int) else None,
                        "name": _event_token(row.get("name")),
                    })
            survivors.sort(key=lambda row: (row["kind"], row["pid"] or -1, row["name"]))
            reason = _event_token(barrier.get("reason"))
            fingerprint = hashlib.sha256(json.dumps(
                {"reason": reason, "survivors": survivors},
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")).hexdigest()
            prior_rows, _ = read_coordination_barrier_observations(store)
            prior = next((row for row in prior_rows if row.get("agent") == agent), None)
            same = (
                isinstance(prior, dict)
                and prior.get("request_id") == request_id
                and prior.get("marker_epoch") == marker_epoch
                and prior.get("survivor_fingerprint") == fingerprint
                and float(now_epoch) >= float(prior.get("last_observed_epoch", now_epoch))
            )
            payload = {
                "schema_version": _COORDINATION_BARRIER_SCHEMA,
                "agent": agent,
                "request_id": request_id,
                "marker_epoch": marker_epoch,
                "barrier_reason": reason,
                "survivor_fingerprint": fingerprint,
                "blocked": True,
                "first_observed_epoch": (
                    prior.get("first_observed_epoch") if same else float(now_epoch)
                ),
                "last_observed_epoch": float(now_epoch),
                "consecutive_blocked_polls": (
                    int(prior.get("consecutive_blocked_polls", 0)) + 1 if same else 1
                ),
            }
            path.parent.mkdir(parents=True, exist_ok=True)
            _atomic_write_text(path, json.dumps(payload, ensure_ascii=False, sort_keys=True))
    except Exception:
        return


def lead_liveness_from_bus(*, agent: str, role: str | None, operator_facing: str | None,
                           heartbeat_age_seconds: object, heartbeat_stale: object,
                           waiting: object, health_reason_code: object = None,
                           stale_after_seconds: float =
                           LEAD_LIVENESS_STALE_AFTER_SECONDS) -> dict | None:
    """Display-only liveness for interactive leads without wrapper health."""
    _ = role, heartbeat_stale
    if agent != operator_facing or health_reason_code != "health_missing":
        return None
    age = heartbeat_age_seconds
    stale_after = (
        float(stale_after_seconds)
        if isinstance(stale_after_seconds, (int, float)) and stale_after_seconds >= 0
        else LEAD_LIVENESS_STALE_AFTER_SECONDS
    )
    if isinstance(age, (int, float)) and math.isfinite(float(age)) and float(age) <= stale_after:
        return {
            "state": "idle_waiting" if waiting else "active",
            "source": "bus_last_seen",
            "last_seen_seconds": round(float(age), 3),
            "stale_after_seconds": stale_after,
            "advisory": True,
        }
    return {
        "state": "unknown",
        "source": "bus_last_seen",
        "last_seen_seconds": (
            round(float(age), 3)
            if isinstance(age, (int, float)) and math.isfinite(float(age)) else None
        ),
        "stale_after_seconds": stale_after,
        "advisory": True,
    }


def _assessment_health(rpt: dict, lead_liveness: dict | None) -> dict:
    health = rpt.get("health") if isinstance(rpt.get("health"), dict) else {}
    state = health_model.label(health)
    reason = health.get("reason_code") if isinstance(health.get("reason_code"), str) else None
    effective = state
    if (state == health_model.STATE_UNKNOWN and reason == "health_missing"
            and isinstance(lead_liveness, dict)):
        ll_state = lead_liveness.get("state")
        if isinstance(ll_state, str) and ll_state != "unknown":
            effective = ll_state
    return {
        "state": state,
        "effective_state": effective,
        "reason_code": reason,
        "age_seconds": health.get("age_seconds") if isinstance(
            health.get("age_seconds"), (int, float)) else None,
        "warnings": health.get("warnings") if isinstance(health.get("warnings"), list) else [],
        "advisory": True,
    }


def supervisor_agent_assessment(name: str, rpt: dict, plan: dict | None, *,
                                operator_facing: str | None = None,
                                lead_liveness_stale_after_seconds: float =
                                LEAD_LIVENESS_STALE_AFTER_SECONDS) -> dict:
    health = rpt.get("health") if isinstance(rpt.get("health"), dict) else {}
    lead_liveness = lead_liveness_from_bus(
        agent=name,
        role=rpt.get("role") if isinstance(rpt.get("role"), str) else None,
        operator_facing=operator_facing,
        heartbeat_age_seconds=rpt.get("heartbeat_age_seconds"),
        heartbeat_stale=rpt.get("heartbeat_stale"),
        waiting=rpt.get("waiting"),
        health_reason_code=health.get("reason_code"),
        stale_after_seconds=lead_liveness_stale_after_seconds,
    )
    decision = None
    if isinstance(plan, dict):
        decision = {
            "action": plan.get("action"),
            "state": plan.get("state"),
            "reason": plan.get("reason"),
        }
        if isinstance(plan.get("health"), dict):
            decision["health"] = plan["health"]
    rr = rpt.get("restart_request") if isinstance(rpt.get("restart_request"), dict) else None
    hold = rpt.get("config_blocked_hold") if isinstance(
        rpt.get("config_blocked_hold"), dict) else None
    return {
        "name": name,
        "role": rpt.get("role"),
        "protected": bool(rpt.get("protected")),
        "heartbeat_stale": bool(rpt.get("heartbeat_stale")),
        "heartbeat_age_seconds": rpt.get("heartbeat_age_seconds"),
        "stuck_after_seconds": rpt.get("stuck_after_seconds"),
        "health": _assessment_health(rpt, lead_liveness),
        "lead_liveness": lead_liveness,
        "waiting": {
            "present": bool(rpt.get("waiting")),
            "pid": rpt.get("waiting_pid"),
            "pid_alive": bool(rpt.get("waiting_pid_alive")),
            "deadline_epoch": rpt.get("waiting_deadline_epoch"),
        },
        "restart_request": {
            "pending": rr is not None,
            "request_id": rr.get("request_id") if rr else None,
            "requested_by": rr.get("requested_by") if rr else None,
        },
        "config_blocked_hold": {
            "present": hold is not None,
            "summary_code": "config_blocked" if hold is not None else None,
        },
        "session_id": rpt.get("session_id"),
        "lead_loop": rpt.get("lead_loop") if isinstance(rpt.get("lead_loop"), dict) else None,
        "lead_loop_exit": (
            rpt.get("lead_loop_exit") if isinstance(rpt.get("lead_loop_exit"), dict) else None
        ),
        "decision": decision,
    }


def _redacted_observation_value(value: object) -> object:
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, int) and not isinstance(value, bool):
        return value
    if isinstance(value, float):
        return value if math.isfinite(value) else None
    if isinstance(value, str):
        return _event_token(value, "redacted")
    if isinstance(value, list):
        return [_redacted_observation_value(item) for item in value]
    if isinstance(value, dict):
        out: dict[str, object] = {}
        for key, item in value.items():
            safe_key = _event_token(key, "redacted")
            out[safe_key] = _redacted_observation_value(item)
        return out
    return None


def _redacted_restart_request(marker: object) -> dict | None:
    if not isinstance(marker, dict):
        return None
    out: dict[str, object] = {}
    for key in (
        "request_id",
        "requested_by",
        "force_protected",
        "live_ack",
        "authority_live",
        "authority_reason",
        "authority_live_reason",
    ):
        if key in marker:
            out[key] = _redacted_observation_value(marker.get(key))
    return out


def _redacted_report_agent(rpt: dict) -> dict:
    hold = rpt.get("config_blocked_hold") if isinstance(
        rpt.get("config_blocked_hold"), dict) else None
    return {
        "role": _redacted_observation_value(rpt.get("role")),
        "protected": bool(rpt.get("protected")),
        "heartbeat_age_seconds": _redacted_observation_value(rpt.get("heartbeat_age_seconds")),
        "heartbeat_stale": bool(rpt.get("heartbeat_stale")),
        "stuck_after_seconds": _redacted_observation_value(rpt.get("stuck_after_seconds")),
        "health": _redacted_observation_value(rpt.get("health")),
        "waiting": bool(rpt.get("waiting")),
        "waiting_pid": _redacted_observation_value(rpt.get("waiting_pid")),
        "waiting_pid_alive": bool(rpt.get("waiting_pid_alive")),
        "waiting_deadline_epoch": _redacted_observation_value(
            rpt.get("waiting_deadline_epoch")),
        "restart_request": _redacted_restart_request(rpt.get("restart_request")),
        "config_blocked_hold": {
            "present": hold is not None,
            "summary_code": "config_blocked" if hold is not None else None,
        },
        "session_id": _redacted_observation_value(rpt.get("session_id")),
        "lead_loop": _redacted_observation_value(rpt.get("lead_loop")),
        "lead_loop_exit": _redacted_observation_value(rpt.get("lead_loop_exit")),
    }


def _redacted_observation_report(report: dict) -> dict:
    agents = report.get("agents") if isinstance(report.get("agents"), dict) else {}
    return {
        "roster": [
            _event_token(name, "redacted")
            for name in (report.get("roster") if isinstance(report.get("roster"), list) else [])
        ],
        "operator_facing": _redacted_observation_value(report.get("operator_facing")),
        "agents": {
            _event_token(name, "redacted"): _redacted_report_agent(rpt)
            for name, rpt in agents.items()
            if isinstance(rpt, dict)
        },
    }


def _redacted_plan_agent(plan: dict) -> dict:
    out = {
        "action": plan.get("action"),
        "state": plan.get("state"),
        "reason": plan.get("reason"),
    }
    for key in ("notify", "clear_marker", "health"):
        if key in plan:
            out[key] = _redacted_observation_value(plan.get(key))
    return out


def _redacted_observation_plan(plan: dict) -> dict:
    agents = plan.get("agents") if isinstance(plan.get("agents"), dict) else {}
    return {
        "agents": {
            _event_token(name, "redacted"): _redacted_plan_agent(agent_plan)
            for name, agent_plan in agents.items()
            if isinstance(agent_plan, dict)
        }
    }


def build_supervisor_observation(store: Store, *, now_epoch: float,
                                 state: dict | None = None,
                                 supervisor_config: dict | None = None,
                                 snapshot: list[dict] | None = None,
                                 event_limit: int = 20,
                                 lead_liveness_stale_after_seconds: float =
                                 LEAD_LIVENESS_STALE_AFTER_SECONDS) -> dict:
    """Read-only operator view: report + exact planner output + bounded ring tail."""
    config = supervisor_config if isinstance(supervisor_config, dict) else {}
    stuck = config.get("stuck_after_seconds")
    stuck = float(stuck) if isinstance(stuck, (int, float)) else None
    state = state if isinstance(state, dict) else {}
    report = build_report(
        store,
        now_epoch=now_epoch,
        stuck_after_seconds=stuck,
        state=state,
        supervisor_config=config,
    )
    plan = plan_actions(report, state, config, now_epoch=now_epoch, snapshot=snapshot)
    events, event_warnings = read_supervisor_events(store, limit=event_limit)
    agents = []
    rpt_agents = report.get("agents") if isinstance(report.get("agents"), dict) else {}
    plan_agents = plan.get("agents") if isinstance(plan.get("agents"), dict) else {}
    for name in report.get("roster", []):
        rpt = rpt_agents.get(name)
        if not isinstance(rpt, dict):
            continue
        agents.append(supervisor_agent_assessment(
            name, rpt, plan_agents.get(name), operator_facing=report.get("operator_facing"),
            lead_liveness_stale_after_seconds=lead_liveness_stale_after_seconds))
    return {
        "schema_version": 1,
        "root": str(store.root),
        "now_epoch": float(now_epoch),
        "now": _event_now(now_epoch),
        "event_ring": {
            "path": str(supervisor_events_path(store)),
            "cap": SUPERVISOR_EVENT_RING_CAP,
            "events": events,
            "warnings": event_warnings,
        },
        "agents": agents,
        "report": _redacted_observation_report(report),
        "plan": _redacted_observation_plan(plan),
    }

# Per-CLI session-argument templates, as LISTS of literal tokens (so the
# generated PowerShell uses an array-of-literals ArgumentList - single-quoted
# PS literals do NOT expand `$`, so the Codex `$agenttalk-listen` prompt and
# any token survive intact, sidestepping the quote-nesting + $-expansion
# hazards codex flagged). The launch PROMPT is the EXPLICIT listen skill for
# BOTH fresh and resume (a fresh session has no context, so prose won't enter
# listen mode): Claude `/agenttalk.listen`, Codex `$agenttalk-listen`.
# {SESSION_ID} is filled by Python for resume, or by the script (claude only)
# after it mints a uuid. Operator-overridable per agent via
# config["agents"][n]["session"]["fresh"|"resume"] (a token list).
_SESSION_DEFAULTS = {
    "claude": {
        # {PERM_MODE} is filled from claude_permission_mode (default
        # "bypassPermissions"): an UNATTENDED supervised agent must NEVER prompt
        # (no human to answer) and must NOT auto-deny real work. Set on BOTH fresh
        # AND resume - the mode is not persisted across sessions, so a fresh
        # launch with no mode would default to prompting and HANG (codex +
        # claude-code-guide converged ruling, 0.28.1 blocker #2).
        "fresh": ["--session-id", "{SESSION_ID}", "--permission-mode", "{PERM_MODE}",
                  "-p", "/agenttalk.listen"],
        "resume": ["--resume", "{SESSION_ID}", "--permission-mode", "{PERM_MODE}",
                   "--allowedTools", "Bash(agenttalk *)", "-p", "/agenttalk.listen"],
    },
    "codex": {
        # Codex does NOT pin a session id at launch; a fresh launch starts with
        # the listen skill, a relaunch RESUMES the most-recent workspace session
        # (`resume --last`, documented best-effort). The skill is ALWAYS present.
        "fresh": ["-a", "never", "-s", "workspace-write", "$agenttalk-listen"],
        "resume": ["resume", "--last", "-a", "never", "-s", "workspace-write",
                   "$agenttalk-listen"],
    },
}


def _backoff_cfg(config: dict) -> dict:
    b = dict(_DEFAULTS["backoff"])
    raw = config.get("backoff") if isinstance(config.get("backoff"), dict) else {}
    for k in b:
        if isinstance(raw.get(k), (int, float)):
            b[k] = raw[k]
    return b


def session_args(cli: str, mode: str, session_id: str | None,
                 cfg_agent: dict | None = None,
                 perm_mode: str = "bypassPermissions") -> list[str]:
    """The session CLI args for a (cli, mode) launch as a LIST of literal
    tokens. ``mode`` is "fresh" or "resume". A per-agent ``session`` config
    overrides the built-in token lists. ``{SESSION_ID}`` is substituted when
    ``session_id`` is known (resume); ``{PERM_MODE}`` is substituted from
    ``perm_mode`` (Claude's unattended permission mode). Pure + deterministic -
    each token is one argument, so the generated command line is unit-testable
    and quote-safe."""
    cli = cli if cli in _SESSION_DEFAULTS else "claude"
    # Coerce to dict only when it IS a dict (same corrupt-config class as the other
    # per-agent resolvers): a truthy non-dict per-agent supervisor.json entry must not
    # crash launch session-arg resolution on cfg_agent.get(...).
    cfg_agent = cfg_agent if isinstance(cfg_agent, dict) else {}
    key = "fresh" if mode == "fresh" else "resume"
    tokens = _SESSION_DEFAULTS[cli][key]
    over = cfg_agent.get("session")
    if isinstance(over, dict) and isinstance(over.get(key), list):
        tokens = over[key]

    def _sub(t):
        if t == "{PERM_MODE}":
            return perm_mode
        if session_id and t == "{SESSION_ID}":
            return session_id
        return t
    result = [_sub(t) for t in tokens]
    # codex hook-trust (0.31.1): when the codex activity hook is installed
    # (activity_hook=true), the `heartbeat --hook` command's changed HASH
    # re-triggers codex's hook-trust review, which PROMPTS and would strand an
    # unattended non-wrapped codex before its first heartbeat. Inject the
    # documented GLOBAL --dangerously-bypass-hook-trust (prepended, so it sits
    # BEFORE the subcommand) so the supervisor's OWN agenttalk hook runs
    # un-prompted. A wrapped codex never reaches here (launch_mode=wrap returns
    # session_args=[]); a codex without the activity hook has no prompt to bypass;
    # an operator who already added the flag is not double-flagged.
    if (cli == "codex" and cfg_agent.get("activity_hook")
            and "--dangerously-bypass-hook-trust" not in result):
        result = ["--dangerously-bypass-hook-trust", *result]
    return result


def claude_permission_mode(config: dict, cfg_agent: dict) -> str:
    """Resolve Claude's unattended permission mode: per-agent override, else the
    top-level ``claude_permission_mode`` knob, else ``bypassPermissions``."""
    for src in (cfg_agent, config):
        if isinstance(src, dict) and isinstance(src.get("claude_permission_mode"), str):
            return src["claude_permission_mode"]
    return "bypassPermissions"


# --- v0.75.0 runtime ergonomics: per-agent model + reasoning_effort ------------
#
# Per-CLI CLOSED reasoning-effort sets (BUILD-CONFIRMED, 2026-07-13, this session):
#   codex  (codex-cli 0.144.1): the `ReasoningEffortParam` enum surfaced by codex
#          is {none, minimal, low, medium, high, xhigh}; `low|medium|high|xhigh`
#          were LIVE-honored on the default account model (returned OK). We expose
#          the confirmed ergonomic subset below. `none` (disable reasoning) and the
#          undocumented `max` CLI alias are intentionally excluded. NOTE: a specific
#          model may still reject an in-enum value at request time (e.g. this
#          account's model rejects `minimal`) — the allow-list is a launch-time typo
#          guard, not a per-model validator (documented limitation).
#   claude (Claude Code 2.1.207): `--effort {low,medium,high,xhigh,max}` (from
#          `claude --help`; the full wrapped argv accepts it fresh + resume).
_CODEX_EFFORTS = frozenset({"minimal", "low", "medium", "high", "xhigh"})
_CLAUDE_EFFORTS = frozenset({"low", "medium", "high", "xhigh", "max"})
_REASONING_EFFORTS = {"codex": _CODEX_EFFORTS, "claude": _CLAUDE_EFFORTS}


def validate_model(raw: object, *, source: str = "per-agent") -> tuple[str | None, str | None]:
    """Validate a model value (warn + drop, never brick launch). Returns
    ``(value|None, warning|None)``. Absent -> ``(None, None)``. A non-str, empty,
    or LEADING-DASH value (would be parsed as a flag) -> ``(None, warning)``."""
    if raw is None:
        return None, None
    if not isinstance(raw, str) or not raw.strip():
        return None, (f"invalid {source} model={raw!r}; expected a non-empty string; "
                      "ignoring (provider default applies)")
    value = raw.strip()
    if value.startswith("-"):
        return None, (f"invalid {source} model={raw!r}; must not start with '-' "
                      "(would parse as a flag); ignoring")
    return value, None


def validate_reasoning_effort(raw: object, cli: str,
                              *, source: str = "per-agent") -> tuple[str | None, str | None]:
    """Validate a reasoning-effort value against the per-CLI closed set (case-folded).
    Returns ``(value|None, warning|None)``. Absent -> ``(None, None)``. Unknown /
    wrong-CLI / non-str -> ``(None, warning)`` (warn + drop)."""
    if raw is None:
        return None, None
    allowed = _REASONING_EFFORTS.get(cli, frozenset())
    if not isinstance(raw, str) or not raw.strip():
        return None, (f"invalid {source} reasoning_effort={raw!r}; expected a string; ignoring")
    value = raw.strip().casefold()
    if value not in allowed:
        return None, (f"invalid {source} reasoning_effort={raw!r} for cli {cli!r}; "
                      f"expected one of {sorted(allowed)}; ignoring")
    return value, None


def resolve_model(cfg_agent: dict) -> tuple[str | None, str | None]:
    """Resolve the per-agent ``model`` (NO global fallback — v0.75.0 D2). Coerce
    with ``isinstance`` (D-13): a corrupt/non-dict entry reads as unset, never
    raises. Returns ``(value|None, warning|None)``."""
    cfg_agent = cfg_agent if isinstance(cfg_agent, dict) else {}
    return validate_model(cfg_agent.get("model"), source="per-agent")


def resolve_reasoning_effort(cfg_agent: dict, cli: str) -> tuple[str | None, str | None]:
    """Resolve the per-agent ``reasoning_effort`` for ``cli`` (NO global fallback —
    v0.75.0 D2). Coerce with ``isinstance`` (D-13). Returns
    ``(value|None, warning|None)``."""
    cfg_agent = cfg_agent if isinstance(cfg_agent, dict) else {}
    return validate_reasoning_effort(cfg_agent.get("reasoning_effort"), cli, source="per-agent")


def _launch_detail(st: dict, cfg_agent: dict, perm_mode: str = "bypassPermissions") -> dict:
    """Resume/launch fields for a launch action. RESUME once the agent has
    reached readiness in its (isolated, for codex) home before - ``resume_available``
    is the new signal (Codex: ``resume --last``; Claude: ``--resume <pinned id>``).
    ``session_id``/``launched`` are honored for back-compat. ``session_args`` is the
    token LIST the executor splices into ``launch.windows_args`` wherever the
    literal "{SESSION_ARGS}" element appears (array-element splice - each token is
    one argument, nothing needs quoting)."""
    cli = cfg_agent.get("cli", "claude")
    if bool(cfg_agent.get("wrapped", False)):
        # WRAPPED: launched THROUGH `agenttalk wrap --loop` with a FIXED argv (no
        # {SESSION_ARGS} splice point). The wrapper owns session continuity
        # end-to-end - it persists + reloads the codex thread_id / claude
        # session-id across its own turns AND across a supervisor relaunch (a
        # restart re-runs the identical wrap argv and the loop reload-resumes). So
        # there is NO fresh/resume branch and NO session tokens to inject here.
        return {"cli": cli, "launch_mode": "wrap", "session_id": None,
                "resume_mode": "wrap", "session_args": []}
    session_id = st.get("session_id") or None
    # codex review (impl r1 MAJOR): resume must mean "reached readiness once".
    # For codex, drive it ONLY from resume_available - legacy `launched` is set at
    # launch time (before readiness), so honoring it would `resume --last` after a
    # failed first launch (the design says FRESH before first readiness). Claude
    # pins its id, so a known session_id still implies resume there.
    if cli == "codex":
        resume = bool(st.get("resume_available"))
    else:
        resume = bool(st.get("resume_available") or session_id or st.get("launched"))
    mode = "resume" if resume else "fresh"
    return {"cli": cli, "launch_mode": mode, "session_id": session_id,
            "resume_mode": "last" if resume else "fresh",
            "session_args": session_args(cli, mode, session_id, cfg_agent,
                                         perm_mode=perm_mode)}


# ---- process-snapshot interpretation (PURE; testable from synthetic rows) ---
#
# The .ps1 executor captures a Win32_Process snapshot each poll and hands it to
# Python via --snapshot-file. THIS is where it is interpreted: which recorded
# pids are still alive (start-time guarded, to defeat pid-reuse), where the
# long-lived "brain" is, whether the agent's `agenttalk wait` is alive, and the
# managed descendant set for a tree-kill. All pure - no OS calls - so the whole
# liveness/classification path is unit-tested from hand-built snapshots.
#
# A snapshot is a LIST of rows
# {pid, parent_pid, name, command_line, start_time, start_filetime}.
# ``snapshot is None`` means UNAVAILABLE (capture failed) - distinct from an
# empty list (captured, nothing matched). command_line may be missing/empty
# (access-limited): we then degrade to name+ancestry only and NEVER match/kill a
# process by a guessed name (codex discipline note 3).

def _snap_index(snapshot: list[dict] | None) -> dict[int, dict]:
    # Task #150 connector finding 1: last-write-wins on a duplicate pid
    # silently picks ONE of two rows - if the winner happens to be a
    # malformed/unrelated row while the loser was a genuinely live child,
    # every later idx.get(that_pid) call sees the wrong identity with no
    # signal anything was lost, and _snapshot_pid_integrity_error's own
    # "duplicate_pid" detection (a separate, whole-snapshot-level check)
    # never told THIS specific lookup that its answer is unreliable.
    # Excluding a duplicated pid entirely - rather than guessing which row
    # to keep - makes it "not found" for every caller, which is exactly
    # the shape the existing missing_child_row/add_node rejection sites
    # already handle correctly; no caller needs new logic to benefit.
    idx: dict[int, dict] = {}
    seen: set[int] = set()
    excluded: set[int] = set()
    for row in snapshot or []:
        if not isinstance(row, dict):
            continue
        pid = row.get("pid")
        if not isinstance(pid, int) or isinstance(pid, bool):
            continue
        if pid in excluded:
            continue
        if pid in seen:
            excluded.add(pid)
            idx.pop(pid, None)
            continue
        seen.add(pid)
        idx[pid] = row
    return idx


def _snapshot_pid_integrity_error(snapshot: list[dict]) -> str | None:
    """Validate the PID/parent graph before any last-row-wins indexing.

    Snapshot rows are evidence used to prove both ownership and absence.  A
    duplicate PID makes the result depend on row order, while an invalid PID or
    parent can hide an edge.  Either condition must therefore fail closed.
    """
    duplicate_pid = False
    seen: set[int] = set()
    for row in snapshot:
        if not isinstance(row, dict):
            return "invalid_process_row"
        pid = row.get("pid")
        parent_pid = row.get("parent_pid")
        if (
            not isinstance(pid, int)
            or isinstance(pid, bool)
            or pid <= 0
            or not isinstance(parent_pid, int)
            or isinstance(parent_pid, bool)
            or parent_pid < 0
        ):
            return "invalid_process_row"
        if pid in seen:
            duplicate_pid = True
        seen.add(pid)
    return "duplicate_pid" if duplicate_pid else None


def _start_of(row: dict | None):
    return (row or {}).get("start_time")


def _filetime_of(row: dict | None) -> str | None:
    value = (row or {}).get("start_filetime")
    if isinstance(value, str) and re.fullmatch(r"[1-9][0-9]{0,19}", value):
        return value
    return None


def _filetime_start_token(value: object) -> str | None:
    """Render exact Windows creation ticks as a comparable ISO start token."""
    if (
        not isinstance(value, str)
        or re.fullmatch(r"[1-9][0-9]{0,19}", value) is None
    ):
        return None
    try:
        seconds = (int(value) / 10_000_000.0) - 11_644_473_600
        return datetime.fromtimestamp(seconds, timezone.utc).isoformat(
            timespec="microseconds"
        ).replace("+00:00", "Z")
    except (OSError, OverflowError, ValueError):
        return None


def _filetime_identity_matches(row: dict | None, expected: object) -> bool:
    """Check companion FILETIME only when the row uses Windows ISO identity."""
    start_key = _start_order_key(_start_of(row))
    if start_key is not None and start_key[0] != "iso":
        # Linux boot-id/start-ticks is already exact. A stale incidental
        # FILETIME-shaped field must not override the platform identity.
        return True
    if expected is None:
        return True
    return isinstance(expected, str) and _filetime_of(row) == expected


def _has_exact_start_identity(row: dict | None) -> bool:
    """Whether a snapshot row carries its platform's exact start identity."""
    key = _start_order_key(_start_of(row))
    if key is None:
        return False
    # Win32_Process exposes a rounded ISO timestamp, so Windows additionally
    # needs the kernel FILETIME. Linux's boot-id/start-ticks token is already
    # exact and intentionally has no FILETIME companion.
    return key[0] != "iso" or _filetime_of(row) is not None


def _exact_start_order_key_values(
    start: object,
    start_filetime: object,
) -> tuple[str, int | float] | None:
    """Return a platform-exact process-start key when one was captured."""
    key = _start_order_key(start)
    if key is None:
        return None
    if key[0] != "iso":
        # Linux's boot-id/start-ticks token is already exact. Ignore any stale
        # FILETIME-shaped field rather than changing the token's platform.
        return key
    if (
        isinstance(start_filetime, str)
        and re.fullmatch(r"[1-9][0-9]{0,19}", start_filetime)
    ):
        return ("win32-filetime", int(start_filetime))
    return None


def _exact_start_order_key(
    row: dict | None,
) -> tuple[str, int | float] | None:
    """Comparable exact process-start key, never a rounded Windows timestamp."""
    return _exact_start_order_key_values(_start_of(row), _filetime_of(row))


def _iso_epoch(value) -> float | None:
    """Parse an ISO-8601 start-time to epoch seconds.

    PowerShell's ``[datetimeoffset].ToString('o')`` writes seven fractional
    digits. Python 3.10 accepts at most six, so trim only the fractional portion
    before ``datetime.fromisoformat`` and preserve the timezone suffix.
    """
    if not isinstance(value, str):
        return None
    s = value.strip()
    if not s:
        return None
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    if "." in s:
        dot = s.find(".")
        tz_pos = len(s)
        for marker in ("+", "-"):
            pos = s.find(marker, dot + 1)
            if pos != -1:
                tz_pos = pos
                break
        frac = s[dot + 1:tz_pos]
        if len(frac) > 6:
            s = s[:dot + 1] + frac[:6] + s[tz_pos:]
    try:
        return datetime.fromisoformat(s).timestamp()
    except ValueError:
        return None


def _pid_alive_guarded(idx: dict[int, dict], pid, expected_start) -> bool:
    """A recorded pid is alive ONLY if present AND its start-time matches what we
    recorded (a recycled pid with a different start-time is NOT our process)."""
    if not isinstance(pid, int) or pid not in idx:
        return False
    if not isinstance(expected_start, str) or not expected_start:
        return False
    return _start_tokens_match(_start_of(idx[pid]), expected_start)


def _start_tokens_match(observed, expected) -> bool:
    """Compare anti-reuse start tokens without losing exact non-ISO schemes.

    The wrapper's Windows native query emits six fractional digits while CIM
    emits seven. Exact equality remains the first rule; ISO values then receive
    a one-millisecond representation tolerance. Linux/native opaque tokens must
    still compare byte-for-byte.
    """
    if not isinstance(observed, str) or not observed:
        return False
    if not isinstance(expected, str) or not expected:
        return False
    if observed == expected:
        return True
    observed_epoch = _iso_epoch(observed)
    expected_epoch = _iso_epoch(expected)
    if observed_epoch is None or expected_epoch is None:
        return False
    return abs(observed_epoch - expected_epoch) <= 0.001


def _start_order_key(value: object) -> tuple[str, int | float] | None:
    """Comparable process-start key for known snapshot/token schemes."""
    if not isinstance(value, str) or not value.strip() or len(value) > 256:
        return None
    epoch = _iso_epoch(value)
    if epoch is not None:
        return ("iso", epoch)
    match = re.fullmatch(
        r"linux:([0-9a-fA-F-]{32,64}):([0-9]+)",
        value.strip(),
    )
    if match is None:
        return None
    boot_id, ticks = match.groups()
    try:
        return (f"linux:{boot_id.casefold()}", int(ticks))
    except ValueError:
        return None


def _strict_start_order_reason(
    parent_start: object,
    parent_filetime: object,
    child_start: object,
    child_filetime: object,
) -> str | None:
    """Return why a child does not start strictly after its parent."""
    parent_key = _exact_start_order_key_values(parent_start, parent_filetime)
    child_key = _exact_start_order_key_values(child_start, child_filetime)
    if parent_key is None or child_key is None:
        # Rounded chronology remains useful for structural diagnostics when an
        # exact Windows identity could not be captured. Live-tree construction
        # marks that row invalid, while validation permits it only in durable
        # invalid/truncated HOLD evidence; this fallback grants no authority.
        parent_key = _start_order_key(parent_start)
        child_key = _start_order_key(child_start)
    if parent_key is None or child_key is None:
        return "unparseable_start_edge"
    if parent_key[0] != child_key[0]:
        return "incomparable_start_edge"
    if child_key[1] == parent_key[1]:
        return "equal_start_edge"
    if child_key[1] < parent_key[1]:
        return "inverted_start_edge"
    return None


def _strict_owned_child_edge(parent: dict, child: dict) -> str | None:
    """Return a reason code unless ``child`` is a strict live child of ``parent``."""
    if child.get("parent_pid") != parent.get("pid"):
        return "parent_mismatch"
    return _strict_start_order_reason(
        _start_of(parent),
        _filetime_of(parent),
        _start_of(child),
        _filetime_of(child),
    )


def _valid_wrapper_generation(value: object) -> bool:
    return (
        isinstance(value, str)
        and _SAFE_WRAPPER_GENERATION_RE.fullmatch(value) is not None
    )


def _utc_epoch(value: object) -> float | None:
    """Return an epoch only for an explicit UTC timestamp."""
    if not isinstance(value, str) or not value or len(value) > 64:
        return None
    text = value[:-1] + "+00:00" if value.endswith("Z") else value
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if (
        parsed.tzinfo is None
        or parsed.utcoffset() is None
        or parsed.utcoffset().total_seconds() != 0
    ):
        return None
    epoch = parsed.timestamp()
    return epoch if math.isfinite(epoch) else None


def _wrapper_runtime_record_digest(record: dict) -> str:
    """Bind an attended reset to one exact validated runtime observation."""
    public_record = {
        key: value
        for key, value in record.items()
        if not key.startswith("_")
    }
    payload = json.dumps(
        public_record,
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _valid_revoked_wrapper_runtime(
    value: object,
    *,
    agent: str,
    root_key: str | None,
) -> dict | None:
    """Return one strict attended-reset runtime revocation boundary."""
    if (
        not isinstance(value, dict)
        or frozenset(value) != _REVOKED_WRAPPER_RUNTIME_FIELDS
        or not isinstance(value.get("schema_version"), int)
        or isinstance(value.get("schema_version"), bool)
        or value.get("schema_version") != _REVOKED_WRAPPER_RUNTIME_SCHEMA
        or value.get("agent") != agent
        or not isinstance(root_key, str)
        or not root_key
        or value.get("root_key") != root_key
        or not isinstance(value.get("wrapper_pid"), int)
        or isinstance(value.get("wrapper_pid"), bool)
        or value["wrapper_pid"] <= 0
        or _start_order_key(value.get("wrapper_start")) is None
        or not _valid_wrapper_generation(value.get("wrapper_generation"))
        or not _valid_launch_nonce(value.get("launch_nonce"))
        or not isinstance(value.get("runtime_record_digest"), str)
        or re.fullmatch(
            r"[0-9a-f]{64}",
            value["runtime_record_digest"],
        ) is None
        or not isinstance(value.get("hold_source_hash"), str)
        or re.fullmatch(r"[0-9a-f]{64}", value["hold_source_hash"]) is None
        or _utc_epoch(value.get("revoked_at")) is None
    ):
        return None
    return copy.deepcopy(value)


def _runtime_record_is_revoked(record: dict, boundary: dict) -> bool:
    """Match only the exact runtime record retired by an attended reset."""
    return (
        record.get("wrapper_pid") == boundary.get("wrapper_pid")
        and _start_tokens_match(
            record.get("wrapper_start"),
            boundary.get("wrapper_start"),
        )
        and record.get("wrapper_generation")
        == boundary.get("wrapper_generation")
        and _wrapper_runtime_record_digest(record)
        == boundary.get("runtime_record_digest")
    )


def _valid_owned_process_tree(
    value: object,
    *,
    agent: str,
    root_key: str | None,
    wrapper_generation: object | None = None,
    launch_nonce: object | None = None,
) -> dict | None:
    """Return a copied strict tree record, or ``None`` for any schema drift.

    The record is kill-adjacent durable input. Unknown fields, partial rows,
    duplicate identities, and a changed wrapper generation/nonce all invalidate
    carry-forward rather than silently widening authority.
    """
    if not isinstance(value, dict):
        return None
    value_keys = frozenset(value)
    # A v2 record (predates rejected_count) is missing exactly one optional
    # key - still a complete, valid schema for everything it DOES claim; see
    # _OWNED_PROCESS_TREE_OPTIONAL_FIELDS' own comment for why that must not
    # collapse to schema-invalid.
    if value_keys != _OWNED_PROCESS_TREE_FIELDS and value_keys != (
        _OWNED_PROCESS_TREE_FIELDS - _OWNED_PROCESS_TREE_OPTIONAL_FIELDS
    ):
        return None
    status = value.get("status")
    record_generation = value.get("wrapper_generation")
    record_nonce = value.get("launch_nonce")
    if (
        value.get("schema_version") != _OWNED_PROCESS_TREE_SCHEMA
        or value.get("attribution_model") != _OWNED_PROCESS_TREE_MODEL
        or value.get("agent") != agent
        or value.get("root_key") != root_key
        or status not in _OWNED_PROCESS_TREE_STATUSES
        or value.get("limit") != _OWNED_PROCESS_TREE_LIMIT
        or (
            status != "invalid"
            and not _valid_launch_nonce(record_nonce)
        )
        or (
            status == "invalid"
            and record_nonce is not None
            and not _valid_launch_nonce(record_nonce)
        )
    ):
        return None
    if (
        wrapper_generation is not None
        and record_generation is not None
        and record_generation != wrapper_generation
    ):
        return None
    if (
        launch_nonce is not None
        and record_nonce is not None
        and record_nonce != launch_nonce
    ):
        return None
    if not (
        status == "invalid"
        and record_generation is None
    ) and not _valid_wrapper_generation(record_generation):
        return None
    if (
        not isinstance(value.get("refreshed_at"), str)
        or len(value["refreshed_at"]) > 64
        or _utc_epoch(value["refreshed_at"]) is None
    ):
        return None
    counts: list[int] = []
    for field in ("observed_count", "recorded_count", "omitted_count"):
        count = value.get(field)
        if not isinstance(count, int) or isinstance(count, bool) or count < 0:
            return None
        counts.append(count)
    observed_count, recorded_count, omitted_count = counts
    # rejected_count is the one OPTIONAL field (see _OWNED_PROCESS_TREE_
    # OPTIONAL_FIELDS) - absent on a v2 record means UNKNOWN, not zero, so
    # this stores None rather than defaulting it, and every reader (the
    # eligibility check, the status/count cross-check below) must treat
    # None as "cannot be trusted", never as "0 rejections".
    if "rejected_count" in value:
        rejected_count = value.get("rejected_count")
        if (
            not isinstance(rejected_count, int)
            or isinstance(rejected_count, bool)
            or rejected_count < 0
        ):
            return None
    else:
        rejected_count = None
    # Round 3 connector finding 4: complete/absent are the two statuses
    # that grant future launch/teardown authority - a record claiming one
    # of them while also recording a nonzero rejection is internally
    # contradictory (a rejection means the walk excluded a candidate it
    # could not vouch for, which is precisely what "complete" and
    # "absent" both promise did not happen). A corrupted or partially-
    # written record must not read as authoritative just because the
    # count field itself still parses.
    if (
        status in {"complete", "absent"}
        and rejected_count is not None
        and rejected_count != 0
    ):
        return None
    entries = value.get("entries")
    if (
        not isinstance(entries, list)
        or (not entries and value.get("status") != "invalid")
        or len(entries) != recorded_count
        or recorded_count > _OWNED_PROCESS_TREE_LIMIT
        or observed_count != recorded_count + omitted_count
        or value.get("truncated") is not (omitted_count > 0)
    ):
        return None
    reason_code = value.get("reason_code")
    if value.get("status") == "complete":
        if reason_code is not None or omitted_count:
            return None
    elif value.get("status") == "absent":
        if reason_code != "process_tree_absent" or omitted_count:
            return None
    elif (
        not isinstance(reason_code, str)
        or not reason_code
        or len(reason_code) > 256
        or (value.get("status") == "truncated" and not omitted_count)
    ):
        return None
    seen: set[tuple[int, str]] = set()
    seen_pids: set[int] = set()
    entries_by_pid: dict[int, dict] = {}
    for index, entry in enumerate(entries):
        if (
            not isinstance(entry, dict)
            or frozenset(entry) != _OWNED_PROCESS_TREE_ENTRY_FIELDS
        ):
            return None
        pid = entry.get("pid")
        start = entry.get("start")
        start_key = _start_order_key(start)
        start_filetime = entry.get("start_filetime")
        parent_pid = entry.get("parent_pid")
        # Complete/absent trees grant future launch and teardown authority, so
        # Windows entries need exact FILETIME identity. Nullable entries remain
        # readable in invalid/truncated records as durable HOLD diagnostics.
        if (
            not isinstance(pid, int)
            or isinstance(pid, bool)
            or pid <= 0
            or not isinstance(parent_pid, int)
            or isinstance(parent_pid, bool)
            or parent_pid < 0
            or not isinstance(start, str)
            or not start
            or len(start) > 256
            or start_key is None
            or (
                start_filetime is not None
                and (
                    not isinstance(start_filetime, str)
                    or re.fullmatch(r"[1-9][0-9]{0,19}", start_filetime) is None
                )
            )
            or (
                status in {"complete", "absent"}
                and start_key is not None
                and start_key[0] == "iso"
                and start_filetime is None
            )
            or entry.get("role") not in _OWNED_PROCESS_TREE_ROLES
            or not isinstance(entry.get("discovered_at"), str)
            or len(entry["discovered_at"]) > 64
            or _utc_epoch(entry["discovered_at"]) is None
            or (pid, start) in seen
            or pid in seen_pids
        ):
            return None
        role = entry.get("role")
        if index == 0:
            if role != "wrapper":
                return None
        else:
            if role == "wrapper":
                return None
            parent = entries_by_pid.get(parent_pid)
            if parent is None:
                return None
            edge_reason = _strict_start_order_reason(
                parent["start"],
                parent.get("start_filetime"),
                start,
                start_filetime,
            )
            if edge_reason is not None:
                return None
        seen.add((pid, start))
        seen_pids.add(pid)
        entries_by_pid[pid] = entry
    return copy.deepcopy(value)


def _invalid_owned_process_tree_record(
    *,
    agent: str,
    root_key: str,
    wrapper_generation: str | None,
    launch_nonce: str | None,
    now_epoch: float,
    reason_code: str,
) -> dict:
    """Return strict durable HOLD evidence for an unusable prior tree record."""
    if not _valid_wrapper_generation(wrapper_generation):
        wrapper_generation = None
    if not _valid_launch_nonce(launch_nonce):
        launch_nonce = None
    return {
        "schema_version": _OWNED_PROCESS_TREE_SCHEMA,
        "attribution_model": _OWNED_PROCESS_TREE_MODEL,
        "agent": agent,
        "root_key": root_key,
        "status": "invalid",
        "reason_code": reason_code,
        "limit": _OWNED_PROCESS_TREE_LIMIT,
        "observed_count": 0,
        "recorded_count": 0,
        "omitted_count": 0,
        "rejected_count": 0,
        "truncated": False,
        "refreshed_at": _event_now(now_epoch),
        "wrapper_generation": wrapper_generation,
        "launch_nonce": launch_nonce,
        "entries": [],
    }


def _valid_legacy_process_migration_evidence(value: object) -> dict | None:
    fields = frozenset({
        "schema_version",
        "status",
        "limit",
        "observed_count",
        "recorded_count",
        "omitted_count",
        "truncated",
        "malformed_count",
        "source_hash",
        "entries",
    })
    if not isinstance(value, dict) or frozenset(value) != fields:
        return None
    counts = [
        value.get(field)
        for field in (
            "observed_count",
            "recorded_count",
            "omitted_count",
            "malformed_count",
        )
    ]
    if (
        value.get("schema_version") != _LEGACY_PROCESS_EVIDENCE_SCHEMA
        or value.get("status") != "migration_hold"
        or value.get("limit") != _OWNED_PROCESS_TREE_LIMIT
        or any(
            not isinstance(count, int)
            or isinstance(count, bool)
            or count < 0
            for count in counts
        )
        or counts[0] != counts[1] + counts[2]
        or value.get("truncated") is not (counts[2] > 0)
        or counts[3] > counts[2]
        or not isinstance(value.get("source_hash"), str)
        or re.fullmatch(r"[0-9a-f]{64}", value["source_hash"]) is None
    ):
        return None
    entries = value.get("entries")
    if (
        not isinstance(entries, list)
        or len(entries) != counts[1]
        or len(entries) > _OWNED_PROCESS_TREE_LIMIT
    ):
        return None
    for entry in entries:
        if (
            not isinstance(entry, dict)
            or frozenset(entry) != {"pid", "start", "source"}
            or not isinstance(entry.get("pid"), int)
            or isinstance(entry.get("pid"), bool)
            or entry["pid"] <= 0
            or not isinstance(entry.get("start"), str)
            or not entry["start"]
            or len(entry["start"]) > 256
            or any(ord(char) < 32 for char in entry["start"])
            or entry.get("source") not in {
                "wrapper",
                "legacy_brain",
                "managed_pids",
            }
        ):
            return None
    return copy.deepcopy(value)


def _legacy_process_migration_evidence(st: dict) -> dict | None:
    """Bound pre-v2 ownership rows for attended migration diagnostics only."""
    existing = _valid_legacy_process_migration_evidence(
        st.get("legacy_process_evidence")
    )
    if existing is not None:
        return existing
    if st.get("owned_process_tree_pending") is True:
        return None
    raw_managed = st.get("managed_pids")
    migration_shaped = bool(
        st.get("launched")
        or isinstance(st.get("runtime_wrapper_generation"), str)
        or st.get("launcher_pid") is not None
        or st.get("brain_pid") is not None
        or raw_managed not in (None, [])
    )
    if not migration_shaped:
        return None

    raw_candidates: list[tuple[str, object]] = [
        ("wrapper", {
            "pid": st.get("launcher_pid"),
            "start": st.get("launcher_start"),
        }),
        ("legacy_brain", {
            "pid": st.get("brain_pid"),
            "start": st.get("brain_start"),
        }),
    ]
    if isinstance(raw_managed, list):
        raw_candidates.extend(("managed_pids", item) for item in raw_managed)
    elif raw_managed is not None:
        raw_candidates.append(("managed_pids_malformed", raw_managed))

    entries: list[dict] = []
    malformed_count = 0
    observed_count = 0
    for source, item in raw_candidates:
        if source in {"wrapper", "legacy_brain"} and (
            not isinstance(item, dict)
            or item.get("pid") is None
            and item.get("start") is None
        ):
            continue
        observed_count += 1
        pid = item.get("pid") if isinstance(item, dict) else None
        start = item.get("start") if isinstance(item, dict) else None
        if (
            not isinstance(pid, int)
            or isinstance(pid, bool)
            or pid <= 0
            or not isinstance(start, str)
            or not start
            or len(start) > 256
            or any(ord(char) < 32 for char in start)
        ):
            malformed_count += 1
            continue
        if len(entries) < _OWNED_PROCESS_TREE_LIMIT:
            entries.append({
                "pid": pid,
                "start": start,
                "source": source,
            })

    source_payload = {
        "launcher_pid": st.get("launcher_pid"),
        "launcher_start": st.get("launcher_start"),
        "brain_pid": st.get("brain_pid"),
        "brain_start": st.get("brain_start"),
        "managed_pids": raw_managed,
        "launched": st.get("launched"),
        "runtime_wrapper_generation": st.get("runtime_wrapper_generation"),
    }
    try:
        source_bytes = json.dumps(
            source_payload,
            ensure_ascii=False,
            sort_keys=True,
            allow_nan=False,
            default=repr,
        ).encode("utf-8")
    except (TypeError, ValueError):
        source_bytes = repr(source_payload).encode("utf-8", errors="replace")
    omitted_count = observed_count - len(entries)
    return {
        "schema_version": _LEGACY_PROCESS_EVIDENCE_SCHEMA,
        "status": "migration_hold",
        "limit": _OWNED_PROCESS_TREE_LIMIT,
        "observed_count": observed_count,
        "recorded_count": len(entries),
        "omitted_count": omitted_count,
        "truncated": omitted_count > 0,
        "malformed_count": malformed_count,
        "source_hash": hashlib.sha256(source_bytes).hexdigest(),
        "entries": entries,
    }


def _recorded_process_identity_state(
    row: dict | None,
    *,
    expected_start: object,
    expected_filetime: object = None,
) -> str:
    """Classify current evidence as same, different, absent, or ambiguous."""
    if not isinstance(row, dict):
        return "absent"
    observed_start = _start_of(row)
    observed_filetime = _filetime_of(row)
    expected_key = _start_order_key(expected_start)
    if expected_key is not None and expected_key[0] != "iso":
        observed_key = _start_order_key(observed_start)
        if observed_key is None:
            return "ambiguous"
        return "same" if observed_key == expected_key else "different"
    if expected_filetime is not None:
        if observed_filetime is None:
            return "ambiguous"
        if observed_filetime == expected_filetime:
            return "same"
        return "different"
    if _start_tokens_match(observed_start, expected_start):
        return "same"
    if _start_order_key(observed_start) is not None:
        return "different"
    return "ambiguous"


def _unverified_owned_process_tree(
    prior: dict | None,
    snapshot: list[dict] | None,
    *,
    now_epoch: float,
    reason_code: str,
) -> dict | None:
    """Fail closed when current proof cannot safely reuse a prior tree.

    A complete or absent prior remains the durable absence certificate when a
    current snapshot proves every recorded pid/start identity absent or
    replaced. Task #150 connector finding: an INVALID prior is not
    categorically excluded from that same re-derivation - only when its own
    entries are a COMPLETE description of what was found. Whatever made the
    tree invalid in the first place (in the production incident, a single
    UNRELATED row elsewhere in that poll's whole-host snapshot failing
    _snapshot_pid_integrity_error, not anything about this agent's own
    identities) says nothing about whether those SPECIFIC recorded identities
    are still alive - the same evidentiary bar the complete/absent case
    already trusts.

    Round 2 (connector blocker): omitted_count alone is NOT that bar - it
    only counts the size-cap gap between admitted nodes and recorded entries,
    never a candidate branch the walk SAW and explicitly excluded for any
    other reason (an unproven virtual-parent descendant with a live child,
    say). rejected_count (see _OWNED_PROCESS_TREE_FIELDS) is the field that
    actually means "nothing the walk considered was left unaccounted for" -
    both it and omitted_count must be zero, with at least one entry recorded,
    for an invalid prior to qualify. A TRUNCATED prior's entries are
    incomplete by definition (omitted_count > 0) and never qualifies:
    proving the recorded subset gone says nothing about whatever the size cap
    dropped. A prior with no entries at all (schema-drift/generation-adoption
    placeholders built by _invalid_owned_process_tree_record, never a real
    tree walk) has nothing to disprove against and never qualifies either.
    Any prior identity still present, or an unavailable/poisoned CURRENT
    snapshot, remains sticky HOLD evidence exactly as before.
    """
    if prior is None:
        return None
    entries = prior.get("entries")
    entries_are_complete = (
        isinstance(entries, list)
        and bool(entries)
        and prior.get("omitted_count") == 0
        and prior.get("rejected_count") == 0
    )
    eligible_for_rederivation = prior.get("status") in {"complete", "absent"} or (
        prior.get("status") == "invalid" and entries_are_complete
    )
    if not eligible_for_rederivation:
        held = copy.deepcopy(prior)
        if (
            held.get("status") == "invalid"
            and held.get("reason_code")
            == "process_tree_invalid_generation_adoption_pending"
        ):
            held["reason_code"] = reason_code
            held["refreshed_at"] = _event_now(now_epoch)
        return held
    snapshot_error = (
        _snapshot_pid_integrity_error(snapshot)
        if snapshot is not None
        else None
    )
    if snapshot is not None and snapshot_error is None:
        idx = _snap_index(snapshot)
        identity_states = [
            _recorded_process_identity_state(
                idx.get(entry.get("pid")),
                expected_start=entry.get("start"),
                expected_filetime=entry.get("start_filetime"),
            )
            for entry in entries or []
            if isinstance(entry, dict)
        ]
        if identity_states and all(
            state in {"absent", "different"} for state in identity_states
        ):
            absent = copy.deepcopy(prior)
            absent["status"] = "absent"
            absent["reason_code"] = "process_tree_absent"
            absent["refreshed_at"] = _event_now(now_epoch)
            return absent
    held = copy.deepcopy(prior)
    held["status"] = "invalid"
    held["reason_code"] = (
        f"process_tree_invalid_snapshot_{snapshot_error}"
        if snapshot_error is not None
        else reason_code
    )
    held["refreshed_at"] = _event_now(now_epoch)
    return held


def _owned_process_tree(
    snapshot: list[dict],
    *,
    st: dict,
    record: dict,
    wrapper_row: dict,
    brain_row: dict | None,
    agent: str,
    root_key: str,
    now_epoch: float,
) -> tuple[dict, list[dict], str | None]:
    """Derive one bounded, nonce-anchored wrapper-owned tree from a poll.

    The wrapper identity is already triple-bound by the caller. Descendants are
    admitted only by strict parent/start edges; image names may assign a role to
    an admitted row but never establish ownership. After an owned parent exits,
    it may remain as a non-killable structural bridge, but a current child below
    that virtual identity must exactly match a previously complete
    same-generation/nonce tree.
    """
    wrapper_generation = record["wrapper_generation"]
    launch_nonce = st["launcher_nonce"]
    refreshed_at = _event_now(now_epoch)
    raw_prior = st.get("owned_process_tree")
    prior = _valid_owned_process_tree(
        raw_prior,
        agent=agent,
        root_key=root_key,
        wrapper_generation=wrapper_generation,
        launch_nonce=launch_nonce,
    )
    prior_entries = (prior or {}).get("entries", [])
    prior_by_pid = {entry["pid"]: entry for entry in prior_entries}
    if (prior or {}).get("status") == "truncated":
        return copy.deepcopy(prior), [], "prior_tree_hold"
    if (
        (prior or {}).get("status") == "invalid"
        and prior.get("reason_code")
        != "process_tree_invalid_generation_adoption_pending"
    ):
        return copy.deepcopy(prior), [], "prior_tree_hold"
    if (prior or {}).get("status") == "absent":
        held = _unverified_owned_process_tree(
            prior,
            snapshot,
            now_epoch=now_epoch,
            reason_code="process_tree_invalid_absent_identity_reappeared",
        )
        if isinstance(held, dict) and held.get("status") == "invalid":
            return held, [], "prior_absence_identity_reappeared"
    # Only a previously complete tree can bridge an exited parent. Truncated
    # and invalid records remain durable HOLD evidence, not ownership authority.
    prior_authority = prior if (prior or {}).get("status") == "complete" else None
    prior_record_invalid = raw_prior is not None and (
        prior is None
        or (
            prior.get("status") == "invalid"
            and prior.get("reason_code")
            == "process_tree_invalid_prior_record_invalid"
        )
    )

    snapshot_error = _snapshot_pid_integrity_error(snapshot)
    idx = _snap_index(snapshot)
    children = _children_map(idx)

    # pid -> {row, role, depth, live}; exited, previously earned identities may
    # remain as virtual ancestry bridges, but are never emitted as kill targets.
    owned: dict[int, dict] = {}
    # Task #150 connector finding: a WHOLE-SNAPSHOT integrity failure (one
    # unrelated row anywhere on the host - a system process CIM could not
    # resolve a parent for, say - fails _snapshot_pid_integrity_error for
    # EVERY agent polled this cycle) and a per-row admission failure inside
    # add_node's own check below used to both surface as the exact same
    # "process_tree_invalid_invalid_process_row" text, even though one is
    # "something elsewhere on this host is malformed" and the other is
    # "one of THIS agent's own tracked rows is malformed" - different
    # operator situations with different remedies. The "snapshot_" prefix
    # matches _unverified_owned_process_tree's own existing convention for
    # the identical distinction, so this is a naming fix, not a new one.
    invalid_reason = (
        "prior_record_invalid"
        if prior_record_invalid
        else (f"snapshot_{snapshot_error}" if snapshot_error is not None else None)
    )
    # Task #150 connector finding (blocker): see _OWNED_PROCESS_TREE_FIELDS'
    # own comment. mark_rejected is the ONE place a specific candidate branch
    # gets excluded from this tree - every such site below calls it instead
    # of setting invalid_reason directly, so rejected_count can never miss
    # one by construction, the same way add_node is the one place a node
    # gets admitted. A whole-snapshot/prior-record issue (the two branches
    # above, seeded before this point) never calls it - that distinction is
    # exactly what makes the "invalid but re-derivable" case in
    # _unverified_owned_process_tree safe.
    rejected_count = 0

    def mark_rejected(reason: str) -> None:
        nonlocal invalid_reason, rejected_count
        rejected_count += 1
        invalid_reason = invalid_reason or reason

    role_rank = {
        "tool_descendant": 0,
        "detached_gate_runner": 1,
        "cli_brain": 2,
        "cli_launcher": 3,
        "wrapper": 4,
    }

    def add_node(row: dict, *, role: str, depth: int, live: bool) -> bool:
        nonlocal invalid_reason
        pid = row.get("pid")
        start = _start_of(row)
        start_key = _start_order_key(start)
        start_filetime = _filetime_of(row)
        parent_pid = row.get("parent_pid")
        if (
            not isinstance(pid, int)
            or isinstance(pid, bool)
            or pid <= 0
            or not isinstance(parent_pid, int)
            or isinstance(parent_pid, bool)
            or parent_pid < 0
            or not isinstance(start, str)
            or not start
            or start_key is None
        ):
            mark_rejected("invalid_process_row")
            return False
        if not _has_exact_start_identity(row):
            # Windows' CIM timestamp is rounded. It can identify graph edges,
            # but it cannot authorize a destructive action after planning.
            # Any retained Windows row therefore needs the exact kernel
            # FILETIME; childless absent launchers are omitted before reaching
            # add_node rather than persisted as future ownership authority.
            #
            # Task #150 connector finding 3: this used to flag invalid_reason
            # but still ADMIT the node - yet _valid_owned_process_tree
            # independently REFUSES an ISO-style entry missing start_filetime
            # for status complete/absent. A tree carrying this exact entry
            # could reach "absent" under round 2's own eligibility check
            # (rejected_count stayed 0 for this case) and then fail its own
            # schema validation the moment anything re-read it - admitted
            # and refused, disagreeing with each other. mark_rejected makes
            # both sides agree: an entry this imprecise never contributes to
            # a rejected_count of 0, so it can never reach a status the
            # validator would then refuse.
            mark_rejected("exact_start_filetime_unavailable")
        existing = owned.get(pid)
        if existing is not None:
            if (
                not _start_tokens_match(_start_of(existing["row"]), start)
                or _filetime_of(existing["row"]) != start_filetime
                or existing["row"].get("parent_pid") != parent_pid
            ):
                mark_rejected("pid_identity_collision")
                return False
            existing["depth"] = min(int(existing["depth"]), depth)
            if role_rank[role] > role_rank[existing["role"]]:
                existing["role"] = role
            if live and not existing["live"]:
                existing["row"] = row
                existing["live"] = True
            return True
        owned[pid] = {
            "row": row,
            "role": role,
            "depth": depth,
            "live": live,
        }
        return True

    add_node(wrapper_row, role="wrapper", depth=0, live=True)
    wrapper_pid = wrapper_row.get("pid")
    recycled_parent_pids: set[int] = set()

    # Rehydrate exact live identities from the previous complete tree. A live
    # descendant whose intermediate parent exited remains owned only because
    # the exact same-generation/nonce identity and its full prior ancestry were
    # already earned. Missing ancestors are retained as non-killable bridges.
    if prior_authority is not None and prior_entries:
        prior_root = prior_entries[0]
        if (
            prior_root.get("pid") != wrapper_pid
            or not _start_tokens_match(
                prior_root.get("start"),
                _start_of(wrapper_row),
            )
        ):
            mark_rejected("prior_wrapper_mismatch")
            prior_authority = None
        else:
            live_prior: set[int] = set()
            for entry in prior_entries:
                row = idx.get(entry["pid"])
                identity_state = _recorded_process_identity_state(
                    row,
                    expected_start=entry["start"],
                    expected_filetime=entry.get("start_filetime"),
                )
                if (
                    entry["pid"] != wrapper_pid
                    and identity_state == "different"
                    and _has_exact_start_identity(row)
                ):
                    recycled_parent_pids.add(entry["pid"])
                    continue
                if not isinstance(row, dict) or not _start_tokens_match(
                    _start_of(row),
                    entry["start"],
                ):
                    continue
                if row.get("parent_pid") != entry["parent_pid"]:
                    mark_rejected("prior_parent_drift")
                    continue
                if not _filetime_identity_matches(
                    row,
                    entry.get("start_filetime"),
                ):
                    mark_rejected("prior_filetime_drift")
                    continue
                live_prior.add(entry["pid"])
            needed = set(live_prior)
            for entry in reversed(prior_entries):
                if entry["pid"] in needed and entry["parent_pid"] in prior_by_pid:
                    needed.add(entry["parent_pid"])
            prior_depth: dict[int, int] = {}
            for entry in prior_entries:
                pid = entry["pid"]
                parent_pid = entry["parent_pid"]
                depth = 0 if pid == wrapper_pid else prior_depth[parent_pid] + 1
                prior_depth[pid] = depth
                if pid == wrapper_pid or pid not in needed:
                    continue
                is_live = pid in live_prior
                row = idx[pid] if is_live else {
                    "pid": pid,
                    "parent_pid": parent_pid,
                    "name": None,
                    "command_line": None,
                    "start_time": entry["start"],
                    "start_filetime": entry.get("start_filetime"),
                }
                add_node(
                    row,
                    role=entry["role"],
                    depth=depth,
                    live=is_live,
                )
    launcher_pid = record.get("cli_launcher_pid")
    launcher_start = record.get("cli_launcher_start")
    launcher_lifetime = record.get("cli_launcher_lifetime")
    launcher_creation_filetime = (
        launcher_lifetime.get("creation_filetime")
        if isinstance(launcher_lifetime, dict)
        and launcher_lifetime.get("source")
        == runtime_obs.LAUNCHER_LIFETIME_SOURCE
        else None
    )
    launcher_exit_filetime = (
        launcher_lifetime.get("exit_filetime")
        if isinstance(launcher_lifetime, dict)
        else None
    )
    if isinstance(launcher_pid, int) and isinstance(launcher_start, str):
        current_launcher = idx.get(launcher_pid)
        current_launcher_identity = _recorded_process_identity_state(
            current_launcher,
            expected_start=launcher_start,
            expected_filetime=launcher_creation_filetime,
        )
        if current_launcher_identity == "different":
            recycled_parent_pids.add(launcher_pid)
        launcher_live = bool(
            isinstance(current_launcher, dict)
            and current_launcher.get("parent_pid") == wrapper_pid
            and _start_tokens_match(
                _start_of(current_launcher),
                launcher_start,
            )
            and (
                launcher_creation_filetime is None
                or _filetime_of(current_launcher)
                == launcher_creation_filetime
            )
        )
        if launcher_live:
            launcher_row = current_launcher
        else:
            if (
                isinstance(current_launcher, dict)
                and (
                    current_launcher_identity == "same"
                    or (
                        current_launcher_identity == "ambiguous"
                        and _start_tokens_match(
                            _start_of(current_launcher),
                            launcher_start,
                        )
                    )
                )
                and current_launcher.get("parent_pid") != wrapper_pid
            ):
                mark_rejected("launcher_parent_mismatch")
            launcher_row = {
                "pid": launcher_pid,
                "parent_pid": wrapper_pid,
                "name": None,
                "command_line": None,
                "start_time": launcher_start,
                "start_filetime": launcher_creation_filetime,
            }
            prior_launcher = owned.get(launcher_pid)
            if (
                isinstance(prior_launcher, dict)
                and prior_launcher.get("role") == "cli_launcher"
                and _has_exact_start_identity(prior_launcher.get("row"))
            ):
                launcher_row = prior_launcher["row"]
            elif not _has_exact_start_identity(launcher_row):
                if current_launcher_identity == "different":
                    # A recycled PID and its current children are unrelated to
                    # the recorded launcher. They grant neither kill nor HOLD
                    # authority.
                    launcher_row = None
                elif current_launcher is not None:
                    mark_rejected("exact_start_filetime_unavailable")
                    launcher_row = None
                elif children.get(launcher_pid):
                    # Windows retains PPID edges after a parent exits. Without
                    # an exact lifetime/prior certificate those children are
                    # ambiguous.
                    mark_rejected("unproven_virtual_parent_descendant")
                    launcher_row = None
                else:
                    # A childless, absent launcher cannot be killed and its
                    # rounded identity must not be persisted as future
                    # ownership authority.
                    launcher_row = None
        if launcher_pid == wrapper_pid:
            mark_rejected("launcher_equals_wrapper")
        elif launcher_row is not None:
            edge_reason = _strict_owned_child_edge(wrapper_row, launcher_row)
            if edge_reason is not None:
                mark_rejected(edge_reason)
            add_node(
                launcher_row,
                role="cli_launcher",
                depth=1,
                live=launcher_live,
            )

    queue = sorted(owned, key=lambda pid: (owned[pid]["depth"], pid))
    queued = set(queue)
    cursor = 0
    while cursor < len(queue):
        parent_pid = queue[cursor]
        cursor += 1
        parent = owned[parent_pid]
        parent_row = parent["row"]
        for child_pid in sorted(children.get(parent_pid, [])):
            child = idx.get(child_pid)
            if not isinstance(child, dict):
                mark_rejected("missing_child_row")
                continue
            if not parent["live"]:
                prior_parent = prior_by_pid.get(parent_pid)
                prior_child = prior_by_pid.get(child_pid)
                certified_launcher_child = bool(
                    parent_pid == launcher_pid
                    and isinstance(launcher_creation_filetime, str)
                    and isinstance(launcher_exit_filetime, str)
                    and _filetime_of(child) is not None
                    and int(launcher_creation_filetime)
                    < int(_filetime_of(child) or "0")
                    < int(launcher_exit_filetime)
                )
                prior_owned_child = bool(
                    prior_authority is not None
                    and prior_parent is not None
                    and prior_child is not None
                    and _start_tokens_match(
                        _start_of(parent_row),
                        prior_parent["start"],
                    )
                    and prior_child["parent_pid"] == parent_pid
                    and child.get("parent_pid") == parent_pid
                    and _start_tokens_match(
                        _start_of(child),
                        prior_child["start"],
                    )
                    and _filetime_identity_matches(
                        child,
                        prior_child.get("start_filetime"),
                    )
                )
                if (
                    parent_pid in recycled_parent_pids
                    and not certified_launcher_child
                    and not prior_owned_child
                ):
                    # Children of the replacement process are foreign. Retain
                    # only descendants already proven by exact prior identity
                    # or by the exited launcher's exact lifetime bounds.
                    continue
                if not certified_launcher_child and not prior_owned_child:
                    mark_rejected("unproven_virtual_parent_descendant")
                    continue
            edge_reason = _strict_owned_child_edge(parent_row, child)
            if edge_reason is not None:
                mark_rejected(edge_reason)
                continue
            role = (
                "cli_brain"
                if isinstance(brain_row, dict) and child_pid == brain_row.get("pid")
                else "tool_descendant"
            )
            if add_node(
                child,
                role=role,
                depth=int(parent["depth"]) + 1,
                live=True,
            ) and child_pid not in queued:
                queue.append(child_pid)
                queued.add(child_pid)

    if isinstance(brain_row, dict):
        brain_pid = brain_row.get("pid")
        if brain_pid not in owned:
            mark_rejected("brain_outside_owned_tree")
        elif owned[brain_pid]["role"] == "tool_descendant":
            owned[brain_pid]["role"] = "cli_brain"

    # Task #150 connector findings 1, 3, 5 (round 3): three MORE sites lose
    # a candidate without incrementing rejected_count, found by review after
    # round 2 hand-enumerated sixteen invalid_reason sites and missed these
    # - two of which are not invalid_reason sites at all. Hand enumeration
    # is the wrong instrument for a universal claim; replace it with
    # construction. Compute every DESCENDANT (not the roots themselves - a
    # root simply being absent/exited is normal and already handled at its
    # own site, e.g. a childless absent launcher, or a prior descendant that
    # simply exited) of a known root - the wrapper, the declared launcher,
    # the discovered brain, and every PRIOR entry, whether or not
    # prior_authority ended up trusted - reachable via the CURRENT
    # snapshot's raw parent-child edges, regardless of whether admission
    # logic actually walked into it. children.get(pid, ...) still returns a
    # live child whose OWN row names pid as parent even when pid itself is
    # absent or was never visited, so an orphaned intermediate's live child
    # - or a rejected launcher's live child - is still IN this closure. Any
    # such descendant that never made it into "owned" is unaccounted -
    # either a case already flagged above (harmless double count;
    # rejected_count is a gate, not an exact tally) or exactly the silent-
    # loss class hand enumeration cannot bound. Either way it becomes a
    # rejection here, mechanically, rather than by finding a fourth site.
    discovery_roots: set[int] = set()
    if isinstance(wrapper_pid, int) and not isinstance(wrapper_pid, bool):
        discovery_roots.add(wrapper_pid)
    if isinstance(launcher_pid, int) and not isinstance(launcher_pid, bool):
        discovery_roots.add(launcher_pid)
    if isinstance(brain_row, dict):
        _brain_pid = brain_row.get("pid")
        if isinstance(_brain_pid, int) and not isinstance(_brain_pid, bool):
            discovery_roots.add(_brain_pid)
    for _prior_entry in prior_entries:
        _prior_pid = _prior_entry.get("pid") if isinstance(_prior_entry, dict) else None
        if isinstance(_prior_pid, int) and not isinstance(_prior_pid, bool):
            discovery_roots.add(_prior_pid)
    # A root already PROVEN to be a different, recycled process (exact
    # identity mismatch, not merely absent) is not a candidate this agent
    # has any claim to - its current children are a REPLACEMENT process's
    # own descendants, not ours, and the existing recycled_parent_pids
    # check a few lines above already treats them as foreign on purpose
    # (test: test_owned_process_tree_recycled_launcher_ignores_foreign_
    # children / ..._recycled_virtual_parent_ignores_replacement_child).
    # Expanding into a recycled root's children here would flag someone
    # else's process tree as our own unaccounted loss.
    discovered_descendants: set[int] = set()
    frontier = [
        pid
        for root in discovery_roots
        if root not in recycled_parent_pids
        for pid in children.get(root, [])
    ]
    while frontier:
        candidate_pid = frontier.pop()
        if candidate_pid in discovered_descendants:
            continue
        discovered_descendants.add(candidate_pid)
        frontier.extend(children.get(candidate_pid, []))
    for _ in sorted(discovered_descendants - set(owned)):
        mark_rejected("unaccounted_discovery")

    observed_count = len(owned)
    mandatory: set[int] = set()
    if isinstance(wrapper_pid, int):
        mandatory.add(wrapper_pid)
    if isinstance(launcher_pid, int) and launcher_pid in owned:
        mandatory.add(launcher_pid)
    if isinstance(brain_row, dict) and brain_row.get("pid") in owned:
        mandatory.add(brain_row["pid"])

    selected: set[int] = set()
    for pid in sorted(mandatory):
        current = pid
        while current in owned and current not in selected:
            selected.add(current)
            parent_pid = owned[current]["row"].get("parent_pid")
            current = parent_pid if isinstance(parent_pid, int) else -1
    parent_first = sorted(
        owned,
        key=lambda pid: (int(owned[pid]["depth"]), pid),
    )
    if len(selected) > _OWNED_PROCESS_TREE_LIMIT:
        # A mandatory identity plus its ancestor closure must never be sliced.
        mark_rejected("mandatory_tree_exceeds_limit")
        selected = set(parent_first[:_OWNED_PROCESS_TREE_LIMIT])
    else:
        for pid in parent_first:
            if len(selected) >= _OWNED_PROCESS_TREE_LIMIT:
                break
            if pid in selected:
                continue
            parent_pid = owned[pid]["row"].get("parent_pid")
            if pid == wrapper_pid or parent_pid in selected:
                selected.add(pid)

    ordered_pids = [pid for pid in parent_first if pid in selected]
    entries: list[dict] = []
    for pid in ordered_pids:
        node = owned[pid]
        row = node["row"]
        start = _start_of(row)
        prior_entry = prior_by_pid.get(pid)
        discovered_at = (
            prior_entry["discovered_at"]
            if prior_entry is not None
            and _recorded_process_identity_state(
                row,
                expected_start=prior_entry["start"],
                expected_filetime=prior_entry.get("start_filetime"),
            )
            == "same"
            else refreshed_at
        )
        entries.append({
            "pid": pid,
            "start": start,
            "start_filetime": _filetime_of(row),
            "role": node["role"],
            "parent_pid": row["parent_pid"],
            "discovered_at": discovered_at,
        })

    omitted_count = max(0, observed_count - len(entries))
    if invalid_reason is not None:
        status = "invalid"
        reason_code = f"process_tree_invalid_{invalid_reason}"
    elif omitted_count:
        status = "truncated"
        reason_code = "process_tree_truncated"
    else:
        status = "complete"
        reason_code = None
    tree = {
        "schema_version": _OWNED_PROCESS_TREE_SCHEMA,
        "attribution_model": _OWNED_PROCESS_TREE_MODEL,
        "agent": agent,
        "root_key": root_key,
        "status": status,
        "reason_code": reason_code,
        "limit": _OWNED_PROCESS_TREE_LIMIT,
        "observed_count": observed_count,
        "recorded_count": len(entries),
        "omitted_count": omitted_count,
        "rejected_count": rejected_count,
        "truncated": bool(omitted_count),
        "refreshed_at": refreshed_at,
        "wrapper_generation": wrapper_generation,
        "launch_nonce": launch_nonce,
        "entries": entries,
    }
    kill_targets = []
    if status == "complete":
        for pid in ordered_pids:
            node = owned[pid]
            if not node["live"]:
                continue
            target = {
                "pid": pid,
                "start": _start_of(node["row"]),
                "reason": "owned_process_tree",
                "source": "owned_process_tree",
            }
            start_filetime = _filetime_of(node["row"])
            if start_filetime is not None:
                target["start_filetime"] = start_filetime
            kill_targets.append(target)
    return tree, kill_targets, invalid_reason


def _diag() -> dict[str, int]:
    return dict.fromkeys(_DIAGNOSTIC_COUNTERS, 0)


def _bump(counters: dict[str, int], name: str) -> None:
    if name in counters:
        counters[name] = int(counters.get(name, 0)) + 1


def _merge_diag(target: dict[str, int], source: dict[str, int]) -> None:
    for key, value in source.items():
        if isinstance(value, int) and value:
            target[key] = int(target.get(key, 0)) + value


def _root_key(value) -> str | None:
    if not isinstance(value, str):
        try:
            value = str(value)
        except Exception:  # noqa: BLE001 - root normalization is fail-closed
            return None
    value = value.strip()
    if not value:
        return None
    try:
        return str(Path(value).resolve(strict=False)).casefold()
    except (OSError, ValueError):
        return None


def _same_root(candidate: str | None, root_key: str | None) -> bool:
    return bool(candidate and root_key and _root_key(candidate) == root_key)


def _image_stem(row_or_name) -> str:
    name = row_or_name.get("name") if isinstance(row_or_name, dict) else row_or_name
    if not isinstance(name, str):
        return ""
    leaf = name.replace("\\", "/").rsplit("/", 1)[-1]
    if "." in leaf:
        leaf = leaf.rsplit(".", 1)[0]
    return leaf.casefold()


_SHELL_HOSTS = {
    "powershell",
    "pwsh",
    "cmd",
    "windowsterminal",
    "wt",
    "conhost",
    "openconsole",
    "explorer",
}


def _is_shell_host(row: dict | None) -> bool:
    return _image_stem(row or {}) in _SHELL_HOSTS


def _split_command_line(command_line: object) -> list[str] | None:
    if not isinstance(command_line, str) or not command_line.strip():
        return None
    try:
        raw = shlex.split(command_line, posix=False)
    except ValueError:
        return None
    out: list[str] = []
    for token in raw:
        if len(token) >= 2 and token[0] == token[-1] and token[0] in "\"'":
            token = token[1:-1]
        if token:
            out.append(token)
    return out or None


def _token_stem(token: str) -> str:
    return _image_stem(token)


# PR 98 connector, the seam finding: this grammar is implemented TWICE (here
# and in PS_TEMPLATE's Test-AgenttalkAllowedInterpreterPrefixToken), and the
# two implementations must agree - see
# test_python_and_powershell_prefix_allowlists_agree, which drives both
# sides through the same shared table. This constant is the single
# PYTHON-side source of truth the test consumes (not a literal the test
# redefines); the PowerShell side is the single source of truth for its own
# language. Each entry's justification lives on the PowerShell function -
# duplicating the reasoning here would just be a third place to drift.
_ALLOWED_INTERPRETER_PREFIX_FLAGS = frozenset(
    {"-u", "-I", "-S", "-B", "-E", "-P", "-b", "-bb"}
)


def _allowed_interpreter_prefix_token(token: str) -> bool:
    if token in _ALLOWED_INTERPRETER_PREFIX_FLAGS:
        return True
    if len(token) > 2 and (token.startswith("-X") or token.startswith("-W")):
        # -X presite=MODULE - see the PowerShell function's own comment for
        # the survey against every other -X sub-option this project knows.
        if token.startswith("-X") and token[2:].startswith("presite"):
            return False
        # Round 24 connector finding: -W's value grammar is
        # action:message:category:module:lineno, and warnings._getcategory
        # IMPORTS a non-empty, dotted category (module, _, klass =
        # category.rpartition('.'); __import__(module)) before -m agenttalk
        # is ever reached - the same before-main, execution-mode-changing
        # property as -X presite, just reachable through -W's own attached
        # value instead of a sub-option. An empty category (no 3rd field,
        # or an empty one) or a category with no dot never reaches that
        # import branch (empty -> the default Warning class; no dot -> a
        # plain attribute lookup on the builtins module) - refuse only the
        # shape that actually imports.
        if token.startswith("-W"):
            parts = token[2:].split(":")
            if len(parts) > 2 and "." in parts[2]:
                return False
        return True
    return False


def _module_args_from(cfg_agent: object) -> object:
    """Extract the declared launch.module_args_from for one agent's config,
    if any - the single place every attribution/provenance call site pulls
    it from cfg_agent it already has in scope, so a malformed or absent
    launch block degrades to None (the default 0-prefix case) rather than
    raising."""
    launch = cfg_agent.get("launch") if isinstance(cfg_agent, dict) else None
    return launch.get("module_args_from") if isinstance(launch, dict) else None


def _resolve_module_flag_index(
    tokens_after_exe: list[str], module_args_from: object,
) -> int:
    """Python-side mirror of Resolve-AgenttalkModuleFlagIndex: given the
    argv tokens AFTER the interpreter executable and a declared
    module_args_from, return the index that holds '-m' (with 'agenttalk'
    immediately after) if every prefix token before it is on the
    allowlist, or -1 otherwise. A malformed module_args_from fails closed
    (-1) rather than raising, matching the PowerShell side's own
    fail-soft cast.

    Shared by _agenttalk_argv (parses an OBSERVED command line at
    attribution time) and bootstrap_check (validates a DECLARED config
    at load time) so the two callers cannot independently drift from
    what this returns - PR 98 connector, round 9: the validator only
    checked module_args_from's type and range, so an in-range value
    pointing at the WRONG token (e.g. windows_args ['-u', '-Xutf8', '-m',
    'agenttalk'] with module_args_from=1) reported valid while this same
    resolver logic, called at runtime, rejected it - nonce injection,
    bounded logging, and launcher attribution all silently disabled on a
    config the validator called clean."""
    offset = 0
    if module_args_from is not None:
        try:
            offset = int(module_args_from)
        except (TypeError, ValueError):
            return -1
        if offset < 0:
            return -1
    if offset >= len(tokens_after_exe):
        return -1
    for prefix_token in tokens_after_exe[:offset]:
        if not _allowed_interpreter_prefix_token(prefix_token):
            return -1
    if (offset + 1 < len(tokens_after_exe)
            and tokens_after_exe[offset] == "-m"
            and tokens_after_exe[offset + 1] == "agenttalk"):
        return offset
    return -1


def _agenttalk_argv(command_line: object, module_args_from: object = None) -> list[str] | None:
    tokens = _split_command_line(command_line)
    if not tokens:
        return None
    first = _token_stem(tokens[0])
    if first in _SHELL_HOSTS:
        return None
    if first in {"python", "python3", "py"}:
        rel_index = _resolve_module_flag_index(tokens[1:], module_args_from)
        if rel_index < 0:
            return None
        return tokens[1 + rel_index + 2:]
    if first == "agenttalk":
        return tokens[1:]
    return None


def _option_value(tokens: list[str], index: int) -> tuple[str | None, int]:
    token = tokens[index]
    if "=" in token:
        return token.split("=", 1)[1], index + 1
    if index + 1 >= len(tokens):
        return None, len(tokens)
    return tokens[index + 1], index + 2


def _valid_launch_nonce(value: object) -> bool:
    return isinstance(value, str) and bool(_SUPERVISOR_LAUNCH_NONCE_RE.fullmatch(value))


def _has_option_token(tokens: list[str], option: str) -> bool:
    return any(arg == option or arg.startswith(option + "=") for arg in tokens)


def _agenttalk_invocation(command_line: object, root_key: str | None,
                           module_args_from: object = None) -> dict | None:
    argv = _agenttalk_argv(command_line, module_args_from)
    if argv is None:
        return None
    root = None
    sub_i = None
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            return {"root": root, "root_match": _same_root(root, root_key),
                    "subcommand": None, "args": [], "tail": argv[i + 1:]}
        if arg in _AGENTTALK_SUBCOMMANDS:
            sub_i = i
            break
        if arg == "--root" or arg.startswith("--root="):
            root, i = _option_value(argv, i)
            continue
        if arg == _SUPERVISOR_LAUNCH_NONCE_ARG or arg.startswith(
                _SUPERVISOR_LAUNCH_NONCE_ARG + "="):
            _nonce, i = _option_value(argv, i)
            continue
        i += 1
    if sub_i is None:
        return {"root": root, "root_match": _same_root(root, root_key),
                "subcommand": None, "args": [], "tail": []}
    return {
        "root": root,
        "root_match": _same_root(root, root_key),
        "subcommand": argv[sub_i],
        "args": argv[sub_i + 1:],
        "tail": [],
    }


def _parse_supervisor_launch_nonce(
    command_line: object, module_args_from: object = None,
) -> tuple[str | None, str | None]:
    argv = _agenttalk_argv(command_line, module_args_from)
    if argv is None:
        return None, "launcher_wrap_parse_failed"
    nonce = None
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            if _has_option_token(argv[i + 1:], _SUPERVISOR_LAUNCH_NONCE_ARG):
                return None, "launcher_nonce_after_subcommand_or_tail"
            break
        if arg in _AGENTTALK_SUBCOMMANDS:
            if _has_option_token(argv[i + 1:], _SUPERVISOR_LAUNCH_NONCE_ARG):
                return None, "launcher_nonce_after_subcommand_or_tail"
            break
        if arg == _SUPERVISOR_LAUNCH_NONCE_ARG or arg.startswith(
                _SUPERVISOR_LAUNCH_NONCE_ARG + "="):
            value, i_next = _option_value(argv, i)
            if value is None or not _valid_launch_nonce(value):
                return None, "launcher_nonce_malformed"
            if nonce is not None:
                return None, "launcher_nonce_duplicate"
            nonce = value
            i = i_next
            continue
        i += 1
    if nonce is None:
        return None, "launcher_nonce_absent"
    return nonce, None


def parse_supervisor_launch_nonce(
    command_line: object, module_args_from: object = None,
) -> str | None:
    nonce, reason = _parse_supervisor_launch_nonce(command_line, module_args_from)
    return nonce if reason is None else None


def _agent_option(args: list[str], option: str) -> str | None:
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == "--":
            return None
        if arg == option or arg.startswith(option + "="):
            value, _next = _option_value(args, i)
            return value
        i += 1
    return None


def parse_agenttalk_wait_invocation(command_line: object, root_key: str | None,
                                    agent: str, module_args_from: object = None) -> bool:
    inv = _agenttalk_invocation(command_line, root_key, module_args_from)
    if not inv or inv.get("subcommand") != "wait" or not inv.get("root_match"):
        return False
    args = inv.get("args") or []
    if _has_option_token(args, _SUPERVISOR_LAUNCH_NONCE_ARG):
        return False
    return _agent_option(args, "--for") == agent


def parse_agenttalk_wrap_invocation(command_line: object, root_key: str | None,
                                    agent: str, module_args_from: object = None) -> bool:
    inv = _agenttalk_invocation(command_line, root_key, module_args_from)
    if not inv or inv.get("subcommand") != "wrap" or not inv.get("root_match"):
        return False
    args = inv.get("args") or []
    if _has_option_token(args, _SUPERVISOR_LAUNCH_NONCE_ARG):
        return False
    agent_value = _agent_option(args, "--for")
    if agent_value != agent:
        return False
    before_tail = args[:args.index("--")] if "--" in args else args
    return "--loop" in before_tail


def _row_branch_reason(row: dict, root_key: str | None, agent: str,
                        module_args_from: object = None) -> str | None:
    if _is_shell_host(row):
        return "shell_boundary"
    inv = _agenttalk_invocation(row.get("command_line"), root_key, module_args_from)
    if not inv:
        return None
    if inv.get("root") and not inv.get("root_match"):
        return "foreign_root_branch"
    if not inv.get("root_match"):
        return None
    sub = inv.get("subcommand")
    args = inv.get("args") or []
    if sub in {"wait", "wrap"}:
        row_agent = _agent_option(args, "--for")
        if row_agent is not None and row_agent != agent:
            return "same_root_other_agent_branch"
        if sub == "wait" and row_agent == agent:
            return None
        if sub == "wrap" and row_agent == agent and "--loop" in (
                args[:args.index("--")] if "--" in args else args):
            return None
    return "unknown_root_cli"


def _state_launcher_source(st: dict) -> dict | None:
    nonce = st.get("launcher_nonce") if isinstance(st, dict) else None
    pid = st.get("launcher_pid") if isinstance(st, dict) else None
    start = st.get("launcher_start") if isinstance(st, dict) else None
    if (
        st.get("launcher_nonce_injected") is True
        and _valid_launch_nonce(nonce)
        and isinstance(pid, int)
        and isinstance(start, str)
        and start
    ):
        return {"pid": pid, "start": start, "nonce": nonce}
    return None


def _entry_launcher_source(entry: dict) -> dict | None:
    pid = entry.get("source_launcher_pid")
    start = entry.get("source_launcher_start")
    nonce = entry.get("source_launcher_nonce")
    if isinstance(pid, int) and isinstance(start, str) and _valid_launch_nonce(nonce):
        return {"pid": pid, "start": start, "nonce": nonce}
    return None


def _target_launcher_source(target: dict) -> dict | None:
    pid = target.get("source_launcher_pid")
    start = target.get("source_launcher_start")
    nonce = target.get("source_launcher_nonce")
    if isinstance(pid, int) and isinstance(start, str) and _valid_launch_nonce(nonce):
        return {"pid": pid, "start": start, "nonce": nonce}
    return None


def _is_confirmed_launcher(
    idx: dict[int, dict],
    row: dict,
    st: dict,
    root_key: str | None,
    agent: str,
    diagnostics: dict[str, int],
    module_args_from: object = None,
) -> tuple[bool, dict | None]:
    pid = st.get("launcher_pid")
    start = st.get("launcher_start")
    if not _pid_alive_guarded(idx, pid, start):
        return False, None
    branch = _row_branch_reason(row, root_key, agent, module_args_from)
    if branch is not None:
        _bump(diagnostics, "foreign_launcher_suppressed")
        return False, None
    if st.get("launcher_nonce_injected") is not True:
        if (
            st.get("launcher_nonce_injected") is False
            and st.get("launcher_nonce_missing_reason") == "unsupported_launch_argv"
        ):
            _bump(diagnostics, "launcher_nonce_unsupported_argv")
        else:
            _bump(diagnostics, "launcher_nonce_missing_state")
        return False, None
    expected = st.get("launcher_nonce")
    if not _valid_launch_nonce(expected):
        _bump(diagnostics, "launcher_nonce_malformed")
        return False, None
    command_line = row.get("command_line")
    if not isinstance(command_line, str) or not command_line.strip():
        _bump(diagnostics, "launcher_nonce_cmdline_unreadable")
        return False, None
    actual, nonce_reason = _parse_supervisor_launch_nonce(command_line, module_args_from)
    if nonce_reason in {
        "launcher_nonce_malformed",
        "launcher_nonce_duplicate",
        "launcher_nonce_after_subcommand_or_tail",
        "launcher_wrap_parse_failed",
    }:
        _bump(diagnostics, nonce_reason)
        return False, None
    if not parse_agenttalk_wrap_invocation(command_line, root_key, agent, module_args_from):
        _bump(diagnostics, "launcher_wrap_parse_failed")
        return False, None
    if nonce_reason == "launcher_nonce_absent":
        _bump(diagnostics, "launcher_nonce_absent")
        return False, None
    if actual != expected:
        _bump(diagnostics, "launcher_nonce_mismatch")
        return False, None
    return True, {"pid": pid, "start": start, "nonce": expected}


def _record_target(targets: dict[int, dict], row: dict, reason: str,
                   *, seed_descendants: bool = False,
                   launcher_source: dict | None = None) -> None:
    pid = row.get("pid")
    start = _start_of(row)
    if not isinstance(pid, int) or not isinstance(start, str) or not start:
        return
    target = {
        "pid": pid,
        "start": start,
        "reason": reason,
        "source": reason,
        "seed_descendants": bool(seed_descendants),
    }
    start_filetime = _filetime_of(row)
    if start_filetime is not None:
        target["start_filetime"] = start_filetime
    if isinstance(launcher_source, dict):
        target.update({
            "source_launcher_pid": launcher_source.get("pid"),
            "source_launcher_start": launcher_source.get("start"),
            "source_launcher_nonce": launcher_source.get("nonce"),
        })
    targets[pid] = target


def _is_expected_seed_row(row: dict, cfg_agent: dict, agent: str,
                          root_key: str | None) -> bool:
    # row is an arbitrary ancestor/descendant, not a confirmed launcher - a
    # declared module_args_from describes THIS agent's configured launcher
    # only, so it must not be applied here (see _strict_child_edge).
    if parse_agenttalk_wait_invocation(row.get("command_line"), root_key, agent):
        return True
    if parse_agenttalk_wrap_invocation(row.get("command_line"), root_key, agent):
        return True
    name = _image_stem(row)
    cli = cfg_agent.get("cli")
    if isinstance(cli, str) and cli and cli.casefold() in name:
        return True
    pattern = cfg_agent.get("brain_pattern") or _liveness_cfg(cfg_agent).get("brain_pattern")
    return isinstance(pattern, str) and pattern and pattern.casefold() in name


def _new_provenance_entry(row: dict, *, root_key: str | None, agent: str,
                          request_id: str | None, source: str,
                          now_epoch: float, seed_descendants: bool,
                          anchor: dict | None = None,
                          launcher_source: dict | None = None) -> dict | None:
    pid = row.get("pid")
    start = _start_of(row)
    if not isinstance(pid, int) or not isinstance(start, str) or not start:
        return None
    entry = {
        "attribution_model": _ATTRIBUTION_MODEL,
        "root_key": root_key,
        "agent": agent,
        "request_id": request_id,
        "pid": pid,
        "start": start,
        "source": source,
        "captured_at_epoch": now_epoch,
        "last_fresh_attribution_epoch": now_epoch,
        "seed_descendants": bool(seed_descendants),
    }
    if isinstance(anchor, dict):
        entry.update({
            "anchor_pid": anchor.get("pid"),
            "anchor_start": anchor.get("start"),
            "anchor_source": anchor.get("source"),
        })
    if isinstance(launcher_source, dict):
        entry.update({
            "source_launcher_pid": launcher_source.get("pid"),
            "source_launcher_start": launcher_source.get("start"),
            "source_launcher_nonce": launcher_source.get("nonce"),
        })
    return entry


def _prior_valid(entry: dict, *, root_key: str | None, agent: str,
                 request_id: str | None, now_epoch: float,
                 st: dict, diagnostics: dict[str, int]) -> bool:
    required = (
        "attribution_model",
        "root_key",
        "agent",
        "request_id",
        "pid",
        "start",
        "source",
        "captured_at_epoch",
        "last_fresh_attribution_epoch",
    )
    if any(key not in entry for key in required):
        _bump(diagnostics, "prior_field_missing")
        return False
    if entry.get("attribution_model") != _ATTRIBUTION_MODEL:
        _bump(diagnostics, "prior_field_missing")
        return False
    if entry.get("root_key") != root_key or entry.get("agent") != agent:
        _bump(diagnostics, "prior_field_missing")
        return False
    if entry.get("request_id") != request_id:
        _bump(diagnostics, "prior_request_mismatch")
        return False
    if not isinstance(entry.get("pid"), int):
        _bump(diagnostics, "prior_field_missing")
        return False
    if not isinstance(entry.get("start"), str) or not entry.get("start"):
        _bump(diagnostics, "prior_field_missing")
        return False
    last = entry.get("last_fresh_attribution_epoch")
    if not isinstance(last, (int, float)) or isinstance(last, bool):
        _bump(diagnostics, "prior_field_missing")
        return False
    if now_epoch - float(last) > _PROVENANCE_TTL_SECONDS:
        _bump(diagnostics, "prior_ttl_expired")
        return False
    if (
        entry.get("source") in _LAUNCHER_DERIVED_PRIOR_SOURCES
        or "source_launcher_nonce" in entry
        or "source_launcher_pid" in entry
        or "source_launcher_start" in entry
    ):
        entry_source = _entry_launcher_source(entry)
        state_source = _state_launcher_source(st)
        if entry_source is None:
            _bump(diagnostics, "prior_field_missing")
            return False
        if state_source is None:
            if (
                st.get("launcher_nonce_injected") is False
                and st.get("launcher_nonce_missing_reason") == "unsupported_launch_argv"
            ):
                _bump(diagnostics, "launcher_nonce_unsupported_argv")
            else:
                _bump(diagnostics, "launcher_nonce_missing_state")
            return False
        if entry_source != state_source:
            _bump(diagnostics, "launcher_nonce_mismatch")
            return False
    return True


def _usable_priors(raw: object, *, root_key: str | None, agent: str,
                   request_id: str | None, now_epoch: float,
                   st: dict, diagnostics: dict[str, int]) -> tuple[list[dict], list[dict]]:
    if raw is None:
        return [], []
    if not isinstance(raw, list):
        _bump(diagnostics, "torn_provenance_read")
        return [], []
    valid: list[dict] = []
    legacy: list[dict] = []
    for item in raw:
        if not isinstance(item, dict):
            _bump(diagnostics, "torn_provenance_read")
            continue
        if item.get("attribution_model") == _ATTRIBUTION_MODEL:
            if _prior_valid(item, root_key=root_key, agent=agent,
                            request_id=request_id, now_epoch=now_epoch,
                            st=st, diagnostics=diagnostics):
                valid.append(item)
        else:
            legacy.append(item)
    return valid, legacy


def _children_map(idx: dict[int, dict]) -> dict[int, list[int]]:
    kids: dict[int, list[int]] = {}
    for pid, row in idx.items():
        ppid = row.get("parent_pid")
        if isinstance(ppid, int):
            kids.setdefault(ppid, []).append(pid)
    return kids


def _strict_child_edge(parent: dict, child: dict, *,
                       root_key: str | None, agent: str,
                       diagnostics: dict[str, int]) -> bool:
    if child.get("parent_pid") != parent.get("pid"):
        return False
    # child is an arbitrary descendant, never the confirmed launcher itself -
    # it made no declaration of its own, so it is parsed by its own argv
    # shape (module_args_from=None), not this agent's declared prefix.
    branch = _row_branch_reason(child, root_key, agent)
    if branch is not None:
        _bump(diagnostics, branch)
        return False
    parent_epoch = _iso_epoch(_start_of(parent))
    child_epoch = _iso_epoch(_start_of(child))
    if parent_epoch is None or child_epoch is None:
        _bump(diagnostics, "unparseable_start_edge")
        return False
    if child_epoch == parent_epoch:
        _bump(diagnostics, "equal_start_edge")
        return False
    if child_epoch < parent_epoch:
        _bump(diagnostics, "inverted_start_edge")
        return False
    return True


def _root_wait_brain(idx: dict[int, dict], wait_row: dict, cfg_agent: dict,
                     root_key: str | None, agent: str,
                     diagnostics: dict[str, int]) -> dict | None:
    # Walks arbitrary ancestor rows - none of them is the confirmed
    # launcher, so no declared module_args_from applies to any of them.
    child = wait_row
    best = None
    seen: set[int] = set()
    while True:
        ppid = child.get("parent_pid")
        parent = idx.get(ppid) if isinstance(ppid, int) else None
        if not isinstance(parent, dict):
            return best
        pid = parent.get("pid")
        if not isinstance(pid, int) or pid in seen:
            return best
        seen.add(pid)
        branch = _row_branch_reason(parent, root_key, agent)
        if branch is not None:
            _bump(diagnostics, branch)
            return best
        parent_epoch = _iso_epoch(_start_of(parent))
        child_epoch = _iso_epoch(_start_of(child))
        if parent_epoch is None or child_epoch is None:
            _bump(diagnostics, "unparseable_start_edge")
            return best
        if parent_epoch == child_epoch:
            _bump(diagnostics, "equal_start_edge")
            return best
        if parent_epoch > child_epoch:
            _bump(diagnostics, "inverted_start_edge")
            return best
        if _is_expected_seed_row(parent, cfg_agent, agent, root_key):
            best = parent
        child = parent


def _attribution(
    snapshot: list[dict] | None,
    st: dict,
    cfg_agent: dict,
    agent: str,
    *,
    root_key: str | None,
    request_id: str | None,
    now_epoch: float,
) -> dict:
    diagnostics = _diag()
    module_args_from = _module_args_from(cfg_agent)
    prior_raw = st.get("managed_pids") if isinstance(st, dict) else None
    valid_priors, legacy_priors = _usable_priors(
        prior_raw,
        root_key=root_key,
        agent=agent,
        request_id=request_id,
        now_epoch=now_epoch,
        st=st,
        diagnostics=diagnostics,
    )
    if snapshot is None:
        _bump(diagnostics, "snapshot_unavailable_no_descendants")
        for _legacy in legacy_priors:
            _bump(diagnostics, "legacy_unverifiable_dropped")
        targets = []
        for entry in valid_priors:
            targets.append({
                "pid": entry["pid"],
                "start": entry["start"],
                "reason": "provenanced_prior",
                "source": "provenanced_prior",
                "seed_descendants": False,
            })
        return {
            "snapshot_available": False,
            "targets": targets,
            "managed_pids": valid_priors,
            "diagnostics": diagnostics,
            "brain_pid": st.get("brain_pid"),
            "brain_start": st.get("brain_start"),
            "wait_alive": False,
            "discovered_brain": False,
        }

    idx = _snap_index(snapshot)
    kids = _children_map(idx)
    targets_by_pid: dict[int, dict] = {}
    seed_pids: set[int] = set()
    seed_launcher_sources: dict[int, dict] = {}
    launcher_pid = st.get("launcher_pid")
    launcher_start = st.get("launcher_start")
    launcher_row = idx.get(launcher_pid) if isinstance(launcher_pid, int) else None
    launcher_mismatch = (
        isinstance(launcher_pid, int)
        and isinstance(launcher_row, dict)
        and isinstance(launcher_start, str)
        and launcher_start
        and _start_of(launcher_row) != launcher_start
    )
    confirmed_launcher = False
    launcher_source = None
    if launcher_mismatch:
        _bump(diagnostics, "pid_reuse_suppressed")
    if isinstance(launcher_row, dict):
        confirmed_launcher, launcher_source = _is_confirmed_launcher(
            idx, launcher_row, st, root_key, agent, diagnostics, module_args_from)
    if confirmed_launcher:
        confirmed_launcher = True
        _record_target(targets_by_pid, launcher_row, "confirmed_launcher",
                       seed_descendants=True, launcher_source=launcher_source)
        seed_pids.add(launcher_pid)
        if isinstance(launcher_pid, int) and launcher_source is not None:
            seed_launcher_sources[launcher_pid] = launcher_source

    own_wait_rows: list[dict] = []
    for row in idx.values():
        pid = row.get("pid")
        if not isinstance(pid, int):
            continue
        if isinstance(launcher_pid, int) and pid == launcher_pid:
            continue
        # row is an arbitrary snapshot entry, not the confirmed launcher -
        # parse it by its own argv shape, not this agent's declared prefix.
        branch = _row_branch_reason(row, root_key, agent)
        if branch is not None:
            _bump(diagnostics, branch)
            continue
        if parse_agenttalk_wrap_invocation(row.get("command_line"), root_key, agent):
            _record_target(targets_by_pid, row, "own_wrapper", seed_descendants=True)
            seed_pids.add(pid)
        elif parse_agenttalk_wait_invocation(row.get("command_line"), root_key, agent):
            _record_target(targets_by_pid, row, "own_wait", seed_descendants=False)
            own_wait_rows.append(row)

    brain_row = None
    for wait_row in own_wait_rows:
        cand = _root_wait_brain(idx, wait_row, cfg_agent, root_key, agent, diagnostics)
        if cand is None:
            continue
        if brain_row is None:
            brain_row = cand
        else:
            cand_epoch = _iso_epoch(_start_of(cand)) or float("-inf")
            brain_epoch = _iso_epoch(_start_of(brain_row)) or float("-inf")
            if cand_epoch < brain_epoch:
                brain_row = cand
    if brain_row is not None:
        _record_target(targets_by_pid, brain_row, "root_wait_brain",
                       seed_descendants=True)
        if isinstance(brain_row.get("pid"), int):
            seed_pids.add(brain_row["pid"])

    for entry in valid_priors:
        if entry.get("pid") == launcher_pid:
            continue
        row = idx.get(entry.get("pid"))
        if not isinstance(row, dict) or _start_of(row) != entry.get("start"):
            continue
        if entry["pid"] in targets_by_pid:
            continue
        reason = str(entry.get("source") or "provenanced_prior")
        _record_target(
            targets_by_pid,
            row,
            reason,
            seed_descendants=bool(entry.get("seed_descendants")),
            launcher_source=_entry_launcher_source(entry),
        )
        if entry["pid"] in targets_by_pid:
            targets_by_pid[entry["pid"]]["prior_only"] = True
        if entry.get("seed_descendants") and isinstance(entry.get("pid"), int):
            seed_pids.add(entry["pid"])
            prior_source = _entry_launcher_source(entry)
            if prior_source is not None:
                seed_launcher_sources[entry["pid"]] = prior_source

    queue = list(seed_pids)
    visited_seed: set[int] = set()
    while queue:
        parent_pid = queue.pop(0)
        if parent_pid in visited_seed:
            continue
        visited_seed.add(parent_pid)
        parent = idx.get(parent_pid)
        if not isinstance(parent, dict):
            continue
        for child_pid in kids.get(parent_pid, []):
            if child_pid in targets_by_pid:
                continue
            child = idx.get(child_pid)
            if not isinstance(child, dict):
                continue
            if not _strict_child_edge(parent, child, root_key=root_key,
                                      agent=agent, diagnostics=diagnostics):
                continue
            child_launcher_source = seed_launcher_sources.get(parent_pid)
            _record_target(targets_by_pid, child, "live_chain_descendant",
                           seed_descendants=True,
                           launcher_source=child_launcher_source)
            if child_launcher_source is not None:
                seed_launcher_sources[child_pid] = child_launcher_source
            queue.append(child_pid)

    fresh_pids = set(targets_by_pid)
    managed_by_pid: dict[int, dict] = {}
    for target in targets_by_pid.values():
        if target.get("prior_only"):
            continue
        row = idx.get(target["pid"])
        if not isinstance(row, dict):
            continue
        if target["reason"] == "confirmed_launcher":
            continue
        source = (
            "first_confirmed_child_provenance"
            if target["reason"] in {"own_wrapper", "own_wait", "root_wait_brain", "live_chain_descendant"}
            else target["reason"]
        )
        entry = _new_provenance_entry(
            row,
            root_key=root_key,
            agent=agent,
            request_id=request_id,
            source=source,
            now_epoch=now_epoch,
            seed_descendants=bool(target.get("seed_descendants")),
            anchor={
                "pid": launcher_pid,
                "start": launcher_start,
                "source": "confirmed_launcher",
            },
            launcher_source=_target_launcher_source(target),
        )
        if entry is not None:
            entry["fresh_reason"] = target["reason"]
            managed_by_pid[entry["pid"]] = entry

    for entry in valid_priors:
        if entry.get("pid") == launcher_pid:
            continue
        if entry["pid"] in managed_by_pid:
            continue
        row = idx.get(entry["pid"])
        if isinstance(row, dict) and _start_of(row) == entry["start"]:
            managed_by_pid[entry["pid"]] = entry

    for legacy in legacy_priors:
        pid = legacy.get("pid")
        start = legacy.get("start")
        row = idx.get(pid) if isinstance(pid, int) else None
        if (
            isinstance(row, dict)
            and isinstance(start, str)
            and start
            and _start_of(row) == start
            and pid in fresh_pids
        ):
            entry = _new_provenance_entry(
                row,
                root_key=root_key,
                agent=agent,
                request_id=request_id,
                source="legacy_rederived",
                now_epoch=now_epoch,
                seed_descendants=bool(targets_by_pid.get(pid, {}).get("seed_descendants")),
                anchor={
                    "pid": launcher_pid,
                    "start": launcher_start,
                    "source": "legacy",
                },
                launcher_source=_target_launcher_source(targets_by_pid.get(pid, {})),
            )
            if entry is not None:
                managed_by_pid[pid] = entry
                if pid in targets_by_pid:
                    targets_by_pid[pid]["reason"] = "legacy_rederived"
                    targets_by_pid[pid]["source"] = "legacy_rederived"
            continue
        _bump(diagnostics, "legacy_unverifiable_dropped")

    wait_alive = any(t["reason"] == "own_wait" for t in targets_by_pid.values())
    return {
        "snapshot_available": True,
        "targets": list(targets_by_pid.values()),
        "managed_pids": list(managed_by_pid.values()),
        "diagnostics": diagnostics,
        "brain_pid": brain_row.get("pid") if isinstance(brain_row, dict) else st.get("brain_pid"),
        "brain_start": _start_of(brain_row) if isinstance(brain_row, dict) else st.get("brain_start"),
        "wait_alive": wait_alive,
        "discovered_brain": brain_row is not None,
    }


def _agent_state_entry(state: dict, agent: str) -> dict:
    agents = state.get("agents") if isinstance(state.get("agents"), dict) else {}
    entry = agents.get(agent) if isinstance(agents, dict) else None
    return entry if isinstance(entry, dict) else {}


def _prior_wrapper_may_be_alive(st: dict) -> bool:
    if isinstance(st.get("launcher_pid"), int):
        return True
    if isinstance(st.get("pid"), int):
        return True
    managed = st.get("managed_pids")
    if isinstance(managed, list) and any(isinstance(item, dict) for item in managed):
        return True
    tree = st.get("owned_process_tree")
    if isinstance(tree, dict) and bool(tree.get("entries")):
        return True
    return bool(st.get("launching"))


def evaluate_launch_barrier(
    snapshot: list[dict] | None,
    state: dict,
    config: dict,
    agent: str,
    *,
    root_key: str | None = None,
    request_id: str | None = None,
) -> dict:
    """Post-kill one-live-wrapper barrier for the generated executor.

    This is intentionally stricter than planner liveness: after a relaunch
    decision has killed its targets, a fresh snapshot must prove no same-root
    same-agent wrapper or wait process survived before Start-Process runs.
    """
    root_key = root_key or _root_key(config.get("root") or config.get("root_key") or "")
    if request_id is None:
        st = _agent_state_entry(state, agent)
    else:
        eph_root = (
            state.get("ephemeral_reviewers")
            if isinstance(state, dict)
            else None
        )
        active = eph_root.get("active") if isinstance(eph_root, dict) else None
        candidate = active.get(request_id) if isinstance(active, dict) else None
        st = candidate if isinstance(candidate, dict) else {}
    if snapshot is None:
        blocked = request_id is not None or _prior_wrapper_may_be_alive(st)
        return {
            "allow_launch": not blocked,
            "blocked": blocked,
            "reason": "snapshot_unavailable_prior_maybe_alive" if blocked else "no_prior_process",
            "snapshot_available": False,
            "survivor_count": 0,
            "survivors": [],
        }

    snapshot_error = _snapshot_pid_integrity_error(snapshot)
    if snapshot_error is not None:
        return {
            "allow_launch": False,
            "blocked": True,
            "reason": f"snapshot_{snapshot_error}",
            "snapshot_available": True,
            "survivor_count": 0,
            "survivors": [],
        }

    survivors: list[dict] = []
    survivor_keys: set[tuple[object, object]] = set()
    survivor_count = 0

    def add_survivor(item: dict) -> None:
        nonlocal survivor_count
        key = (item.get("kind"), item.get("pid"))
        if key in survivor_keys:
            return
        survivor_keys.add(key)
        survivor_count += 1
        if len(survivors) < 8:
            survivors.append(item)
    raw_tree = st.get("owned_process_tree")
    tree = None
    if raw_tree is not None:
        tree = _valid_owned_process_tree(
            raw_tree,
            agent=agent,
            root_key=root_key,
            wrapper_generation=(
                st.get("runtime_wrapper_generation")
                if isinstance(st.get("runtime_wrapper_generation"), str)
                else None
            ),
            launch_nonce=(
                st.get("launcher_nonce")
                if _valid_launch_nonce(st.get("launcher_nonce"))
                else None
            ),
        )
        if tree is None or tree.get("status") not in {"complete", "absent"}:
            return {
                "allow_launch": False,
                "blocked": True,
                "reason": "owned_process_tree_unavailable",
                "snapshot_available": True,
                "survivor_count": 0,
                "survivors": [],
            }
    elif request_id is not None:
        return {
            "allow_launch": False,
            "blocked": True,
            "reason": "owned_process_tree_unavailable",
            "snapshot_available": True,
            "survivor_count": 0,
            "survivors": [],
        }
    idx = _snap_index(snapshot)
    tree_judged_state_launcher = False
    if isinstance(tree, dict):
        tree_entries = tree.get("entries", [])
        closure_seed_pids: set[int] = set()
        recycled_parent_rows: dict[int, dict] = {}
        for entry_index, entry in enumerate(tree_entries):
            row = idx.get(entry.get("pid"))
            identity_state = _recorded_process_identity_state(
                row,
                expected_start=entry.get("start"),
                expected_filetime=entry.get("start_filetime"),
            )
            pid = entry.get("pid")
            if (
                entry_index == 0
                and entry.get("role") == "wrapper"
                and pid == st.get("launcher_pid")
                and _start_tokens_match(
                    entry.get("start"),
                    st.get("launcher_start"),
                )
            ):
                tree_judged_state_launcher = True
            if (
                identity_state != "different"
                and isinstance(pid, int)
                and not isinstance(pid, bool)
            ):
                # An absent recorded parent remains a conservative closure
                # root: on Windows it may have exited after spawning a child.
                # A definitively different exact identity is a recycled PID,
                # however, and grants no ownership of its current children.
                closure_seed_pids.add(pid)
            elif (
                identity_state == "different"
                and isinstance(pid, int)
                and not isinstance(pid, bool)
                and isinstance(row, dict)
            ):
                recycled_parent_rows[pid] = row
            if identity_state in {"absent", "different"}:
                continue
            add_survivor({
                "kind": (
                    "owned_process"
                    if identity_state == "same"
                    else "owned_process_identity_ambiguous"
                ),
                "pid": entry["pid"],
                "name": _event_token(
                    row.get("name") if isinstance(row, dict) else None,
                    "unknown",
                ),
            })
        # Planning and Stop-Tree are separated by process scheduling. A
        # recorded parent can spawn after the plan, then exit during teardown,
        # leaving a child that was never a kill target. Treat every current
        # descendant edge rooted at a recorded PID as survivor evidence. This
        # graph relation only blocks launch; it never authorizes killing.
        recorded_pids = closure_seed_pids
        closure_seen = set(recorded_pids)
        frontier = list(recorded_pids)
        children = _children_map(idx)
        # A recorded parent may spawn an unplanned child, exit, and have its
        # PID recycled before this barrier snapshot. The replacement PID is
        # not an ownership root, but a child whose exact start strictly
        # predates it belongs to the old side of the edge. Exact equal/newer
        # children belong to the replacement; missing/incomparable exact
        # evidence remains conservative because this barrier never kills.
        for parent_pid, replacement in recycled_parent_rows.items():
            replacement_key = _exact_start_order_key(replacement)
            for pid in children.get(parent_pid, []):
                row = idx[pid]
                child_key = _exact_start_order_key(row)
                if (
                    replacement_key is not None
                    and child_key is not None
                    and child_key[0] == replacement_key[0]
                    and child_key[1] >= replacement_key[1]
                ):
                    continue
                if pid in closure_seen:
                    continue
                closure_seen.add(pid)
                frontier.append(pid)
                add_survivor({
                    "kind": "owned_descendant_edge",
                    "pid": pid,
                    "name": _event_token(row.get("name"), "unknown"),
                })
        while frontier:
            parent_pid = frontier.pop()
            for pid in children.get(parent_pid, []):
                if pid in closure_seen:
                    continue
                closure_seen.add(pid)
                frontier.append(pid)
                row = idx[pid]
                add_survivor({
                    "kind": "owned_descendant_edge",
                    "pid": pid,
                    "name": _event_token(row.get("name"), "unknown"),
                })
    for row in snapshot:
        if not isinstance(row, dict):
            continue
        kind = None
        if (
            row.get("pid") == st.get("launcher_pid")
            and not tree_judged_state_launcher
            and (
                _recorded_process_identity_state(
                    row,
                    expected_start=st.get("launcher_start"),
                )
                in {"same", "ambiguous"}
            )
        ):
            # Blocking a second launch needs no command-line authority. The
            # exact state pid/start identity is sufficient to prove that the
            # prior launcher still exists, even when its command line is
            # unreadable. This never authorizes killing that process.
            kind = "state_launcher"
        # row is an arbitrary post-kill survivor, not a confirmed launcher -
        # parsed by its own argv shape, not this agent's declared prefix.
        elif parse_agenttalk_wrap_invocation(row.get("command_line"), root_key, agent):
            kind = "own_wrapper"
        elif parse_agenttalk_wait_invocation(row.get("command_line"), root_key, agent):
            kind = "own_wait"
        if kind is None:
            continue
        item = {
            "kind": kind,
            "pid": row.get("pid") if isinstance(row.get("pid"), int) else None,
            "name": _event_token(row.get("name"), "unknown"),
        }
        add_survivor(item)

    blocked = survivor_count > 0
    reason = "clear"
    if blocked:
        reason = (
            "owned_process_survived"
            if any(s.get("kind") == "owned_process" for s in survivors)
            else (
                "owned_process_identity_ambiguous"
                if any(
                    s.get("kind") == "owned_process_identity_ambiguous"
                    for s in survivors
                )
                else (
                    "owned_descendant_edge_survived"
                    if any(
                        s.get("kind") == "owned_descendant_edge"
                        for s in survivors
                    )
                    else (
                        "state_launcher_survived"
                        if any(
                            s.get("kind") == "state_launcher"
                            for s in survivors
                        )
                        else (
                            "same_agent_wrapper_survived"
                            if any(
                                s.get("kind") == "own_wrapper"
                                for s in survivors
                            )
                            else "same_agent_wait_survived"
                        )
                    )
                )
            )
        )
    return {
        "allow_launch": not blocked,
        "blocked": blocked,
        "reason": reason,
        "snapshot_available": True,
        "survivor_count": survivor_count,
        "survivors": survivors,
    }


def capture_launch_child_provenance(
    pre_snapshot: list[dict] | None,
    post_snapshot: list[dict] | None,
    *,
    launcher_pid: int | None,
    launcher_start: str | None,
    cfg_agent: dict,
    agent: str,
    root_key: str | None,
    request_id: str | None,
    now_epoch: float,
    launcher_nonce: str | None = None,
    launcher_nonce_injected: bool = False,
) -> tuple[list[dict], dict[str, int]]:
    diagnostics = _diag()
    if not isinstance(launcher_pid, int):
        return [], diagnostics
    launcher_epoch = _iso_epoch(launcher_start)
    if launcher_epoch is None or not isinstance(post_snapshot, list):
        return [], diagnostics
    launcher_source = None
    if launcher_nonce_injected and _valid_launch_nonce(launcher_nonce):
        launcher_source = {
            "pid": launcher_pid,
            "start": launcher_start,
            "nonce": launcher_nonce,
        }
    baseline: set[tuple[int, str]] = set()
    for row in pre_snapshot or []:
        if not isinstance(row, dict):
            continue
        pid = row.get("pid")
        start = _start_of(row)
        if isinstance(pid, int) and isinstance(start, str):
            baseline.add((pid, start))
    out: list[dict] = []
    for row in post_snapshot:
        if not isinstance(row, dict) or row.get("parent_pid") != launcher_pid:
            continue
        pid = row.get("pid")
        start = _start_of(row)
        if not isinstance(pid, int) or not isinstance(start, str) or not start:
            _bump(diagnostics, "unparseable_start_edge")
            continue
        if (pid, start) in baseline:
            continue
        child_epoch = _iso_epoch(start)
        if child_epoch is None:
            _bump(diagnostics, "unparseable_start_edge")
            continue
        if child_epoch < launcher_epoch:
            _bump(diagnostics, "inverted_start_edge")
            continue
        # row is a child of the confirmed launcher, but its OWN argv shape
        # was never declared - the launcher's declared prefix describes the
        # launcher, not its children, so it does not apply here either.
        branch = _row_branch_reason(row, root_key, agent)
        if branch is not None:
            _bump(diagnostics, branch)
            continue
        seed = _is_expected_seed_row(row, cfg_agent, agent, root_key)
        entry = _new_provenance_entry(
            row,
            root_key=root_key,
            agent=agent,
            request_id=request_id,
            source="launch_child_provenance",
            now_epoch=now_epoch,
            seed_descendants=seed,
            anchor={
                "pid": launcher_pid,
                "start": launcher_start,
                "source": "confirmed_launcher",
            },
            launcher_source=launcher_source,
        )
        if entry is not None:
            out.append(entry)
    return out, diagnostics


def _wait_row_for(idx: dict[int, dict], agent: str) -> dict | None:
    """The agent's `agenttalk wait --for <agent>` process row, matched by command
    line (degrades to None when command lines are unavailable - we never guess)."""
    for row in idx.values():
        inv = _agenttalk_invocation(row.get("command_line"), None)
        if not inv or inv.get("subcommand") != "wait":
            continue
        args = inv.get("args") or []
        if _has_option_token(args, _SUPERVISOR_LAUNCH_NONCE_ARG):
            continue
        if _agent_option(args, "--for") == agent:
            return row
    return None


def _depth_to_launcher(idx: dict[int, dict], row: dict, launcher_pid: int) -> int | None:
    """Number of parent hops from ``row`` up to a node that is (or is a direct
    child of) ``launcher_pid`` - climbing WITHIN the snapshot. Works even when the
    launcher ROW itself has exited (a forking launcher), because we match on the
    recorded ``parent_pid`` reaching ``launcher_pid``, not on the launcher row
    being present. None if the chain never reaches the launcher."""
    cur, depth, seen = row, 0, set()
    while isinstance(cur, dict):
        cpid = cur.get("pid")
        if cpid in seen:
            return None
        seen.add(cpid)
        if cpid == launcher_pid:
            return depth
        if cur.get("parent_pid") == launcher_pid:
            return depth
        ppid = cur.get("parent_pid")
        nxt = idx.get(ppid) if isinstance(ppid, int) else None
        if nxt is None:
            return None
        cur, depth = nxt, depth + 1
    return None


def _discover_brain(idx: dict[int, dict], agent: str, launcher_pid,
                    brain_pattern: str, launch_epoch: float | None = None,
                    allow_launcher_self: bool = False, *,
                    launcher_start: str | None = None,
                    require_launcher_bound: bool = False,
                    turn_generation: int | None = None) -> dict | None:
    """Find the long-lived brain process - NEVER the forking LAUNCHER (test #4).

    ``allow_launcher_self`` FALSE (codex): the launcher (codex.exe) spawns the real
    TUI then EXITS, so the launcher row must be EXCLUDED from every strategy - else
    we pin the launcher, it dies after handoff, and grace expiry false-kills a
    healthy agent. TRUE (claude / non-forking): the launcher IS the brain.

    THREE signals, in order:
    1. up from the agent's live ``wait`` process to the HIGHEST ELIGIBLE
       brain-named ancestor (the TUI ABOVE command-runner/wait but BELOW the
       launcher; needs command lines; survives launcher exit). This is a
       legacy/manual discovery aid only, never wrapped-turn authority;
    2. name + ancestry to the RECORDED ``launcher_pid`` - an eligible brain-named
       row whose parent chain reaches the launcher, preferring the one CLOSEST to
       the launcher (the TUI is its direct child = depth 0; codex-command-runner.exe
       also matches the 'codex' substring but is depth 1, so it never wins),
       tie-broken by in-the-wait-chain, then started-after-launch, then
       deterministic (start, pid). Null-command-line safe.
    3. the degenerate non-forking case (ONLY when allow_launcher_self): the
       launcher row itself matches the name (claude.exe is its own brain).

    Wrapped callers set ``require_launcher_bound`` and provide the launcher
    identity from one validated runtime turn. Then only comparable start evidence
    plus ancestry to that locator (or the exact live launcher-self identity) can
    authorize green health; an unrelated/prior wait tree remains unknown.
    Returns the brain row or None."""
    if require_launcher_bound and (
        not isinstance(turn_generation, int)
        or isinstance(turn_generation, bool)
        or turn_generation <= 0
    ):
        return None
    pat = (brain_pattern or "").lower()

    def _name_matches(row):
        return pat and pat in (row.get("name") or "").lower()

    def _is_launcher(row):
        return isinstance(launcher_pid, int) and row.get("pid") == launcher_pid

    def _eligible(row):
        # a brain candidate must match the pattern AND, for a forking CLI, must
        # NOT be the launcher itself.
        return _name_matches(row) and (allow_launcher_self or not _is_launcher(row))

    launch_key = _start_order_key(launcher_start)
    if (
        launch_key is None
        and isinstance(launch_epoch, (int, float))
        and not isinstance(launch_epoch, bool)
        and math.isfinite(float(launch_epoch))
    ):
        launch_key = ("iso", float(launch_epoch))

    def _started_after_launch(row) -> bool:
        if launch_key is None:
            return not require_launcher_bound
        candidate_key = _start_order_key(_start_of(row))
        if candidate_key is None or candidate_key[0] != launch_key[0]:
            return not require_launcher_bound
        slack = 0.001 if launch_key[0] == "iso" else 0.0
        return float(candidate_key[1]) >= float(launch_key[1]) - slack

    # pids on the wait-ancestor chain (strategy-1 climb + strategy-2 tie-break).
    wait = _wait_row_for(idx, agent)
    wait_chain: set = set()
    if wait is not None:
        cur, seen = wait, set()
        while isinstance(cur, dict):
            cpid = cur.get("pid")
            if cpid in seen:
                break
            seen.add(cpid)
            wait_chain.add(cpid)
            ppid = cur.get("parent_pid")
            cur = idx.get(ppid) if isinstance(ppid, int) else None

    # (1) up from the wait process to the highest ELIGIBLE brain-named ancestor.
    if wait is not None and not require_launcher_bound:
        best, seen, cur = None, set(), wait
        while isinstance(cur, dict):
            cpid = cur.get("pid")
            if cpid in seen:
                break
            seen.add(cpid)
            if _eligible(cur):
                best = cur  # keep climbing - the TOPMOST eligible (the TUI), not the launcher
            ppid = cur.get("parent_pid")
            cur = idx.get(ppid) if isinstance(ppid, int) else None
        if best is not None:
            return best
    # (2) name + ancestry to the recorded launcher (null-command-line safe).
    if isinstance(launcher_pid, int):
        cands = []
        for row in idx.values():
            if not _eligible(row) or not _started_after_launch(row):
                continue
            d = _depth_to_launcher(idx, row, launcher_pid)
            if d is None:
                continue
            se = _iso_epoch(_start_of(row))
            cands.append((d,                                       # closest to launcher
                          0 if row.get("pid") in wait_chain else 1,  # prefer the wait chain
                          se if se is not None else float("inf"),    # earliest started
                          row.get("pid") if isinstance(row.get("pid"), int) else 1 << 62,
                          row))
        if cands:
            cands.sort(key=lambda c: c[:4])
            return cands[0][4]
    # (3) degenerate non-forking: the launcher row itself is the brain.
    if allow_launcher_self and isinstance(launcher_pid, int) and launcher_pid in idx:
        launcher_row = idx[launcher_pid]
        identity_bound = (
            not require_launcher_bound
            or _start_tokens_match(_start_of(launcher_row), launcher_start)
        )
        if identity_bound and _name_matches(launcher_row):
            return launcher_row
    return None


def _launcher_managed_set(idx: dict[int, dict], launcher_pid, agent: str,
                          now_epoch: float, *,
                          launch_epoch: float | None = None,
                          prior: list[dict] | None = None) -> list[dict]:
    """Best-effort restart kill set for an independently authorized recovery.

    The process snapshot supplies scoped cleanup targets, not authority by
    itself. On Windows, children keep the creator
    ``ParentProcessId`` after the launcher exits, so rows whose parent chain
    reaches the recorded launcher are the best scoped target set for Codex's
    TUI/runner/wait tree. Prior start-matching rows are carried forward so a
    later snapshot with null command lines can still reap known children.
    """
    out: dict[int, dict] = {}

    def _started_after_launch(row) -> bool:
        if launch_epoch is None:
            return True
        se = _iso_epoch(_start_of(row))
        return se is None or se >= float(launch_epoch) - 5.0

    def add(row: dict | None, kind: str) -> None:
        if not isinstance(row, dict):
            return
        pid = row.get("pid")
        if not isinstance(pid, int):
            return
        out[pid] = {"pid": pid, "start": _start_of(row),
                    "kind": kind, "last_seen": now_epoch}

    if isinstance(launcher_pid, int):
        for row in idx.values():
            if row.get("pid") == launcher_pid:
                continue  # launcher itself is killed separately with launcher_start
            if (_depth_to_launcher(idx, row, launcher_pid) is not None
                    and _started_after_launch(row)):
                add(row, "launcher-tree")

    wait = _wait_row_for(idx, agent)
    if wait is not None:
        add(wait, "wait")

    for m in (prior or []):
        pid = m.get("pid")
        if not isinstance(pid, int) or pid in out:
            continue
        if _pid_alive_guarded(idx, pid, m.get("start")):
            out[pid] = {"pid": pid, "start": m.get("start"),
                        "kind": m.get("kind", "runner"), "last_seen": now_epoch}
    return list(out.values())


def _liveness(snapshot: list[dict] | None, st: dict, cfg_agent: dict,
              agent: str, now_epoch: float, *,
              root_key: str | None = None,
              request_id: str | None = None,
              runtime_view: dict | None = None) -> dict:
    """Derive process-discovery facts for one agent (PURE).

    Returns ``snapshot_available`` (False when capture failed), ``brain_pid`` /
    ``brain_start`` (recorded, or freshly DISCOVERED this tick), ``brain_alive``,
    ``wait_alive``, ``managed_pids`` (refreshed), and ``discovered_brain``.
    These fields seed next-state and scoped kill targets. Manual agents retain
    heartbeat authority; wrapped agents combine a strict runtime observation
    with independently discovered wrapper/CLI process identity."""
    lcfg = _liveness_cfg(cfg_agent)
    if bool(lcfg.get("wrapped", False)):
        return _wrapped_liveness(
            snapshot,
            st,
            cfg_agent,
            agent,
            now_epoch,
            runtime_view,
            root_key=root_key,
        )
    attr = _attribution(
        snapshot,
        st,
        cfg_agent,
        agent,
        root_key=root_key,
        request_id=request_id,
        now_epoch=now_epoch,
    )
    if snapshot is None:
        return {"snapshot_available": False, "brain_pid": attr.get("brain_pid"),
                "brain_start": attr.get("brain_start"), "brain_alive": False,
                "wait_alive": False, "managed_pids": attr.get("managed_pids") or [],
                "kill_targets": attr.get("targets") or [],
                "diagnostics": attr.get("diagnostics") or _diag(),
                "discovered_brain": False}
    idx = _snap_index(snapshot)
    allow_launcher_self = bool(lcfg.get("allow_launcher_self", False))
    launcher_pid = st.get("launcher_pid")
    brain_pid = st.get("brain_pid")
    brain_start = st.get("brain_start")
    # STALE-STATE REPAIR (test #4): a stored brain_pid == the LAUNCHER on a
    # forking CLI is a BAD pin (an older buggy discovery). Treat it as dead and
    # re-discover, so next_state records the real TUI instead of preserving the
    # bad launcher pin.
    bad_launcher_pin = (not allow_launcher_self and brain_pid is not None
                        and brain_pid == launcher_pid)
    brain_alive = (not bad_launcher_pin
                   and _pid_alive_guarded(idx, brain_pid, brain_start))
    discovered = False
    if not brain_alive:
        cand = _discover_brain(idx, agent, launcher_pid,
                               cfg_agent.get("brain_pattern")
                               or lcfg.get("brain_pattern", ""),
                               launch_epoch=st.get("last_launch_epoch"),
                               allow_launcher_self=allow_launcher_self)
        if cand is not None:
            brain_pid, brain_start = cand.get("pid"), _start_of(cand)
            brain_alive, discovered = True, True
        elif bad_launcher_pin:
            # repaired-away the bad pin but found no real brain -> not alive,
            # and clear the stale launcher pin from the reported brain_pid.
            brain_pid, brain_start = None, None
    managed = attr.get("managed_pids") or []
    wait_alive = bool(attr.get("wait_alive")) or _wait_row_for(idx, agent) is not None
    return {"snapshot_available": True, "brain_pid": brain_pid,
            "brain_start": brain_start, "brain_alive": brain_alive,
            "wait_alive": wait_alive, "managed_pids": managed,
            "kill_targets": attr.get("targets") or [],
            "diagnostics": attr.get("diagnostics") or _diag(),
            "discovered_brain": discovered}


def _wrapped_liveness(
    snapshot: list[dict] | None,
    st: dict,
    cfg_agent: dict,
    agent: str,
    now_epoch: float,
    runtime_view: dict | None,
    *,
    root_key: str | None,
) -> dict:
    """Bind one strict runtime observation to one nonce-owned process tree."""
    diagnostics = _diag()
    prior_tree = None
    raw_prior = None
    legacy_evidence = _legacy_process_migration_evidence(st)
    prior_generation = st.get("runtime_wrapper_generation")
    has_revoked_runtime = "revoked_wrapper_runtime" in st
    raw_revoked_runtime = st.get("revoked_wrapper_runtime")
    revoked_runtime = (
        _valid_revoked_wrapper_runtime(
            raw_revoked_runtime,
            agent=agent,
            root_key=root_key,
        )
        if has_revoked_runtime
        else None
    )
    if isinstance(root_key, str):
        raw_prior = st.get("owned_process_tree")
        prior_tree = _valid_owned_process_tree(
            raw_prior,
            agent=agent,
            root_key=root_key,
            wrapper_generation=(
                prior_generation if isinstance(prior_generation, str) else None
            ),
            launch_nonce=(
                st.get("launcher_nonce")
                if _valid_launch_nonce(st.get("launcher_nonce"))
                else None
            ),
        )
        # Any malformed persisted tree is ambiguous: an envelope mismatch can
        # be corruption of the current authority, not proof that the record is
        # stale. Only record_launch or the explicit generation-adoption branch
        # below may clear it.
        prior_record_invalid = (
            raw_prior is not None
            and prior_tree is None
        )
        if prior_record_invalid:
            prior_tree = _invalid_owned_process_tree_record(
                agent=agent,
                root_key=root_key,
                wrapper_generation=(
                    prior_generation
                    if isinstance(prior_generation, str)
                    else None
                ),
                launch_nonce=(
                    st.get("launcher_nonce")
                    if _valid_launch_nonce(st.get("launcher_nonce"))
                    else None
                ),
                now_epoch=now_epoch,
                reason_code="process_tree_invalid_prior_record_invalid",
            )
        if (
            raw_prior is None
            and legacy_evidence is not None
        ):
            # The pre-v2 channel can contain exact owned identities, but lacks
            # the bounded parent graph and generation binding needed for safe
            # automatic teardown. Never silently discard that upgrade evidence:
            # an attended new launch generation is the migration boundary.
            prior_tree = _invalid_owned_process_tree_record(
                agent=agent,
                root_key=root_key,
                wrapper_generation=(
                    prior_generation
                    if _valid_wrapper_generation(prior_generation)
                    else None
                ),
                launch_nonce=(
                    st.get("launcher_nonce")
                    if _valid_launch_nonce(st.get("launcher_nonce"))
                    else None
                ),
                now_epoch=now_epoch,
                reason_code="process_tree_invalid_legacy_managed_pids",
            )
    base = {
        "snapshot_available": snapshot is not None,
        "brain_pid": None,
        "brain_start": None,
        "brain_alive": False,
        "wait_alive": False,
        # Legacy rows are never teardown authority. The separately bounded
        # migration object remains operator evidence until a new generation
        # earns a strict tree.
        "managed_pids": [],
        "legacy_process_evidence": copy.deepcopy(legacy_evidence),
        "owned_process_tree_pending": st.get("owned_process_tree_pending") is True,
        "owned_process_tree": prior_tree,
        "owned_process_tree_error": None,
        "owned_process_tree_refreshed": False,
        "kill_targets": [],
        "diagnostics": diagnostics,
        "discovered_brain": False,
        "runtime_status": runtime_obs.STATUS_ABSENT,
        "runtime_error": "missing",
        "runtime_record": None,
        "runtime_updated_age_seconds": None,
        "runtime_progress_age_seconds": None,
        "wrapper_state": "unknown",
        "child_state": "unknown",
        "child_reason": "runtime_missing",
    }
    verified_wrapper_generation: str | None = None

    if has_revoked_runtime and revoked_runtime is None:
        # This marker is the atomic attended-reset boundary that makes an old
        # runtime file non-authoritative. Schema drift must therefore HOLD
        # rather than silently deleting the boundary and reviving stale state.
        base["owned_process_tree"] = _invalid_owned_process_tree_record(
            agent=agent,
            root_key=root_key if isinstance(root_key, str) else "",
            wrapper_generation=None,
            launch_nonce=None,
            now_epoch=now_epoch,
            reason_code="process_tree_invalid_runtime_revocation_record",
        )
        base["owned_process_tree_error"] = (
            "process_tree_invalid_runtime_revocation_record"
        )
        base["child_reason"] = (
            "process_tree_invalid_runtime_revocation_record"
        )
        return base

    def _unverified_owned_process_may_exist() -> bool:
        """Conservatively detect ownership-shaped live evidence without a tree."""
        identities: list[tuple[int, object]] = []
        for pid_key, start_key in (
            ("launcher_pid", "launcher_start"),
            ("pid", "launcher_start"),
        ):
            pid = st.get(pid_key)
            if isinstance(pid, int) and not isinstance(pid, bool) and pid > 0:
                identities.append((pid, st.get(start_key)))
        current_record = base.get("runtime_record")
        if isinstance(current_record, dict):
            for pid_key, start_key in (
                ("wrapper_pid", "wrapper_start"),
                ("cli_launcher_pid", "cli_launcher_start"),
            ):
                pid = current_record.get(pid_key)
                if isinstance(pid, int) and not isinstance(pid, bool) and pid > 0:
                    identities.append((pid, current_record.get(start_key)))
        if snapshot is None:
            return bool(identities)
        roots = {pid for pid, _start in identities}
        for pid, start in identities:
            row = _snap_index(snapshot).get(pid)
            if isinstance(row, dict) and _start_tokens_match(_start_of(row), start):
                return True
        # A launcher may already have exited and left a reparenting race. A
        # direct or transitive edge below any recorded wrapper/launcher PID is
        # sufficient ambiguity to HOLD, but never to kill.
        frontier = set(roots)
        remaining = [row for row in snapshot if isinstance(row, dict)]
        while frontier:
            next_frontier: set[int] = set()
            for row in remaining:
                pid = row.get("pid")
                if (
                    row.get("parent_pid") in frontier
                    and isinstance(pid, int)
                    and not isinstance(pid, bool)
                    and pid > 0
                ):
                    return True
            frontier = next_frontier
        return False

    def _current_proof_failed(
        child_reason: str,
        *,
        hold_reason: str,
    ) -> dict:
        prior_for_check = base.get("owned_process_tree")
        tree = _unverified_owned_process_tree(
            prior_for_check,
            snapshot,
            now_epoch=now_epoch,
            reason_code=hold_reason,
        )
        # Task #150 connector finding 4: this used to re-check
        # prior_for_check.get("status") against {"complete", "absent"} -
        # duplicating _unverified_owned_process_tree's OWN eligibility gate
        # with a copy that drifted the moment that gate widened to admit an
        # invalid-but-complete prior too. tree.get("status") == "absent" is
        # already the complete, self-contained signal: it is the ONLY value
        # _unverified_owned_process_tree ever returns for "absent", and it
        # already re-checked eligibility internally - a second, independent
        # copy of that check here can only go stale, not add safety.
        if isinstance(tree, dict) and tree.get("status") == "absent" and snapshot is not None:
            base["owned_process_tree_refreshed"] = True
        adopted_tree_missing = bool(
            prior_for_check is None
            and isinstance(prior_generation, str)
            and prior_generation == verified_wrapper_generation
        )
        if (
            tree is None
            and (
                adopted_tree_missing
                or _unverified_owned_process_may_exist()
            )
            and isinstance(root_key, str)
        ):
            tree = _invalid_owned_process_tree_record(
                agent=agent,
                root_key=root_key,
                wrapper_generation=(
                    verified_wrapper_generation
                    or (
                        prior_generation
                        if isinstance(prior_generation, str)
                        else None
                    )
                ),
                launch_nonce=(
                    st.get("launcher_nonce")
                    if _valid_launch_nonce(st.get("launcher_nonce"))
                    else None
                ),
                now_epoch=now_epoch,
                reason_code=hold_reason,
            )
        base["owned_process_tree"] = tree
        if isinstance(tree, dict) and tree.get("status") in {
            "truncated",
            "invalid",
        }:
            base["owned_process_tree_error"] = tree.get("reason_code")
            base["child_reason"] = tree.get("reason_code") or child_reason
        else:
            base["child_reason"] = child_reason
        return base

    view = runtime_view if isinstance(runtime_view, dict) else {}
    status = (
        view.get("status")
        if isinstance(runtime_view, dict)
        else runtime_obs.STATUS_ABSENT
    )
    if status not in {
        runtime_obs.STATUS_VALID,
        runtime_obs.STATUS_ABSENT,
        runtime_obs.STATUS_INVALID,
    }:
        status = runtime_obs.STATUS_INVALID
    base["runtime_status"] = status
    base["runtime_error"] = view.get("error")
    if status != runtime_obs.STATUS_VALID:
        return _current_proof_failed(
            f"runtime_{status}",
            hold_reason=f"process_tree_invalid_runtime_{status}",
        )

    record = view.get("record")
    if not isinstance(record, dict):
        base["runtime_status"] = runtime_obs.STATUS_INVALID
        base["runtime_error"] = "record_missing"
        return _current_proof_failed(
            "runtime_invalid",
            hold_reason="process_tree_invalid_runtime_record_missing",
        )
    try:
        normalized = runtime_obs.validate_record(
            record,
            expected_agent=agent,
            now_epoch=now_epoch,
        )
    except runtime_obs.RuntimeRecordError:
        base["runtime_status"] = runtime_obs.STATUS_INVALID
        base["runtime_error"] = "record_invalid"
        return _current_proof_failed(
            "runtime_invalid",
            hold_reason="process_tree_invalid_runtime_record_invalid",
        )
    updated_epoch = normalized.pop("_updated_epoch")
    progress_epoch = normalized.pop("_last_progress_epoch")
    record = normalized
    if (
        revoked_runtime is not None
        and _runtime_record_is_revoked(record, revoked_runtime)
    ):
        # The reset and this marker were committed in the same supervisor-state
        # write after a human proved every recorded identity gone. The runtime
        # file is intentionally left in place so reset is cross-file atomic;
        # only its exact digest/identity/generation is treated as retired. A
        # genuinely new or changed record follows the normal adoption path.
        base["runtime_status"] = runtime_obs.STATUS_ABSENT
        base["runtime_error"] = "attended_reset_revoked"
        return _current_proof_failed(
            "runtime_generation_revoked_by_attended_reset",
            hold_reason=(
                "process_tree_invalid_runtime_revoked_replacement_unverified"
            ),
        )
    verified_wrapper_generation = record.get("wrapper_generation")
    base["runtime_record"] = record
    base["runtime_updated_age_seconds"] = max(0.0, now_epoch - updated_epoch)
    base["runtime_progress_age_seconds"] = (
        None if progress_epoch is None else max(0.0, now_epoch - progress_epoch)
    )

    if not isinstance(root_key, str) or not root_key:
        return _current_proof_failed(
            "root_identity_unavailable",
            hold_reason="process_tree_invalid_root_identity_unavailable",
        )
    wrapper_generation = record.get("wrapper_generation")
    if wrapper_generation != st.get("runtime_wrapper_generation"):
        # A new wrapper generation supersedes any prior tree, but adoption is a
        # fail-closed poll rather than a relaunch-authority gap. The next poll
        # may replace this one specific transition marker only after it binds
        # the live wrapper and derives a complete current tree.
        base["owned_process_tree"] = _invalid_owned_process_tree_record(
            agent=agent,
            root_key=root_key,
            wrapper_generation=wrapper_generation,
            launch_nonce=(
                st.get("launcher_nonce")
                if _valid_launch_nonce(st.get("launcher_nonce"))
                else None
            ),
            now_epoch=now_epoch,
            reason_code="process_tree_invalid_generation_adoption_pending",
        )
        base["owned_process_tree_error"] = (
            "process_tree_invalid_generation_adoption_pending"
        )
        base["child_reason"] = "wrapper_generation_mismatch"
        return base
    if snapshot is None:
        return _current_proof_failed(
            "snapshot_unavailable",
            hold_reason="process_tree_invalid_snapshot_unavailable",
        )
    idx = _snap_index(snapshot)
    wrapper_pid = record.get("wrapper_pid")
    wrapper_start = record.get("wrapper_start")
    if (
        wrapper_pid != st.get("launcher_pid")
        or not _start_tokens_match(wrapper_start, st.get("launcher_start"))
    ):
        return _current_proof_failed(
            "wrapper_state_mismatch",
            hold_reason="process_tree_invalid_wrapper_state_mismatch",
        )
    wrapper_row = idx.get(wrapper_pid)
    if wrapper_row is None:
        base["wrapper_state"] = "dead"
        return _current_proof_failed(
            "wrapper_absent",
            hold_reason=(
                "process_tree_invalid_wrapper_absent_live_descendant"
            ),
        )
    if not _pid_alive_guarded(idx, wrapper_pid, wrapper_start):
        return _current_proof_failed(
            "wrapper_identity_ambiguous",
            hold_reason="process_tree_invalid_wrapper_identity_ambiguous",
        )
    wrapper_attributed, _launcher_source = _is_confirmed_launcher(
        idx,
        wrapper_row,
        st,
        root_key,
        agent,
        diagnostics,
        _module_args_from(cfg_agent),
    )
    if not wrapper_attributed:
        return _current_proof_failed(
            "wrapper_attribution_ambiguous",
            hold_reason="process_tree_invalid_wrapper_attribution_ambiguous",
        )
    base["wrapper_state"] = "alive"

    phase = record.get("phase")
    candidate = None
    launcher_pid = record.get("cli_launcher_pid")
    launcher_start = record.get("cli_launcher_start")
    launcher_lifetime = record.get("cli_launcher_lifetime")
    ownership_record = record
    if (
        launcher_start is None
        and isinstance(launcher_lifetime, dict)
        and launcher_lifetime.get("source")
        == runtime_obs.LAUNCHER_LIFETIME_SOURCE
    ):
        launcher_start = _filetime_start_token(
            launcher_lifetime.get("creation_filetime")
        )
        if launcher_start is not None:
            # The retained handle is stronger than the racy secondary PID
            # lookup. Normalize only this planner copy; the runtime evidence
            # remains an exact creation/exit certificate.
            ownership_record = {**record, "cli_launcher_start": launcher_start}
    if phase == runtime_obs.PHASE_ACTIVE and (
        not isinstance(launcher_pid, int)
        or not isinstance(launcher_start, str)
    ):
        return _current_proof_failed(
            "launcher_identity_unavailable",
            hold_reason="process_tree_invalid_launcher_identity_unavailable",
        )
    lcfg = _liveness_cfg(cfg_agent)
    brain_pattern = cfg_agent.get("brain_pattern") or lcfg.get("brain_pattern", "")
    if phase == runtime_obs.PHASE_ACTIVE:
        candidate = _discover_brain(
            idx,
            agent,
            launcher_pid,
            brain_pattern,
            allow_launcher_self=bool(lcfg.get("allow_launcher_self", False)),
            launcher_start=launcher_start,
            require_launcher_bound=True,
            turn_generation=record.get("turn_generation"),
        )
    tree, kill_targets, tree_error = _owned_process_tree(
        snapshot,
        st=st,
        record=ownership_record,
        wrapper_row=wrapper_row,
        brain_row=candidate,
        agent=agent,
        root_key=root_key,
        now_epoch=now_epoch,
    )
    base["owned_process_tree"] = tree
    base["owned_process_tree_error"] = tree_error
    base["owned_process_tree_refreshed"] = True
    if tree.get("status") == "complete":
        base["legacy_process_evidence"] = None
        base["owned_process_tree_pending"] = False
    base["kill_targets"] = kill_targets
    if tree.get("status") == "invalid":
        base["child_reason"] = tree.get("reason_code") or "process_tree_invalid"
        return base

    if phase == runtime_obs.PHASE_IDLE:
        base["child_state"] = "not_required"
        base["child_reason"] = "idle"
        return base
    if phase == runtime_obs.PHASE_STARTING:
        base["child_state"] = "starting"
        base["child_reason"] = "spawn_pending"
        return base
    if phase == runtime_obs.PHASE_TERMINAL:
        base["child_state"] = "terminal"
        base["child_reason"] = "turn_terminal"
        return base
    if phase != runtime_obs.PHASE_ACTIVE:
        base["child_reason"] = "phase_unknown"
        return base

    if candidate is not None:
        candidate_pid = candidate.get("pid")
        candidate_start = _start_of(candidate)
        base["brain_pid"] = candidate_pid
        base["brain_start"] = candidate_start
        base["brain_alive"] = True
        base["discovered_brain"] = True
        base["child_state"] = "alive"
        base["child_reason"] = "brain_discovered"
        return base

    pattern = str(brain_pattern or "").casefold()
    if pattern and any(
        pattern in str(row.get("name") or "").casefold()
        for row in idx.values()
    ):
        base["child_reason"] = "brain_ancestry_ambiguous"
        return base
    base["child_state"] = "dead"
    base["child_reason"] = "brain_absent"
    return base


def _liveness_cfg(cfg_agent: dict) -> dict:
    """Per-agent liveness config merged over the per-CLI defaults."""
    cli = cfg_agent.get("cli", "claude")
    base = dict(_LIVENESS_DEFAULTS.get(cli, _LIVENESS_DEFAULTS["claude"]))
    for k in ("requires_brain_pid", "brain_pattern", "codex_home_isolation",
              "windows_sandbox", "allow_launcher_self", "wrapped"):
        if k in cfg_agent:
            base[k] = cfg_agent[k]
    return base


def build_report(store: Store, *, now_epoch: float,
                 stuck_after_seconds: float | None = None,
                 suspect_after_seconds: float | None = None,
                 state: dict | None = None,
                 supervisor_config: dict | None = None) -> dict:
    """Point-in-time bus-side liveness snapshot. Read-only.

    ``protected`` is ``operator_facing`` UNION every active ``role=lead`` agent
    (fail-closed - see ``Store.protected_agents``). ``heartbeat_stale`` is True
    when there is no heartbeat or it is older than the stuck threshold
    (``stuck_after_seconds``; ``suspect_after_seconds`` accepted as a back-compat
    alias). The launched-PID liveness is NOT here - only the supervisor knows it
    - but when its ``state`` is passed, the recorded ``session_id`` (and pid) is
    merged for an operator-facing view (session_id is supervisor-local, not a
    bus fact, so it is opt-in via state).

    ``supervisor_config`` (the supervisor.json) is opt-in: when passed, each
    agent's ``heartbeat_stale`` is computed against its PER-AGENT/PER-CLI threshold
    (:func:`resolve_stuck_after`), so the operator-facing report MATCHES the
    planner's per-CLI decision (a wrapped Codex is not shown stale at the global
    threshold while the planner correctly holds to its 2400s default). Without
    it the single global threshold applies (legacy behavior). The resolved
    per-agent threshold is reported as ``stuck_after_seconds`` on each agent
    entry. The additive
    ``heartbeat_evidence`` field preserves missing/observed/future-skew evidence
    for read-only coordination warnings; planning continues to consume the
    unchanged age and stale fields.
    """
    threshold = stuck_after_seconds
    if threshold is None:
        threshold = suspect_after_seconds
    if threshold is None:
        threshold = float(_DEFAULTS["stuck_after_seconds"])
    cfg = store.load_config()
    roster = cfg.get("agents", []) or []
    roles = cfg.get("roles") or {}
    protected = store.protected_agents()
    sup_cfg = supervisor_config if isinstance(supervisor_config, dict) else None
    sup_agents = (sup_cfg.get("agents") if sup_cfg and isinstance(
        sup_cfg.get("agents"), dict) else {})
    state_agents = (state or {}).get("agents") if isinstance(state, dict) else None
    state_agents = state_agents if isinstance(state_agents, dict) else {}
    agents: dict[str, dict] = {}
    for a in roster:
        # per-agent/per-CLI threshold when the supervisor config is supplied
        # (report parity with the planner); else the single global threshold.
        threshold_a = (resolve_stuck_after(sup_cfg, sup_agents.get(a) or {})
                       if sup_cfg is not None else float(threshold))
        health_timing = resolve_health_timing(sup_cfg or {}, sup_agents.get(a) or {})
        hb = store.read_heartbeat(a)
        hb_age = authoritative_heartbeat_age_seconds(
            hb,
            now_epoch=now_epoch,
            heartbeat_skew_seconds=health_timing["heartbeat_skew_seconds"],
        )
        heartbeat_evidence = (
            HEARTBEAT_EVIDENCE_MISSING
            if hb is None
            else (
                HEARTBEAT_EVIDENCE_FUTURE_SKEW
                if hb_age is None
                else HEARTBEAT_EVIDENCE_OBSERVED
            )
        )
        stale = hb_age is None or hb_age > threshold_a
        health = store.read_health(
            a,
            now_epoch=now_epoch,
            heartbeat=hb,
            ttl_seconds=health_timing["ttl_seconds"],
            heartbeat_skew_seconds=health_timing["heartbeat_skew_seconds"],
        )
        marker = store.read_waiting(a)
        w_pid = marker.get("pid") if isinstance(marker, dict) else None
        w_pid = w_pid if isinstance(w_pid, int) else None
        st = state_agents.get(a) if isinstance(state_agents.get(a), dict) else {}
        agents[a] = {
            "role": roles.get(a) if isinstance(roles.get(a), str) else None,
            "protected": a in protected,
            "heartbeat_age_seconds": hb_age,
            "heartbeat_stale": stale,
            "heartbeat_evidence": heartbeat_evidence,
            "stuck_after_seconds": threshold_a,
            "health": health,
            "waiting": marker is not None,
            "waiting_pid": w_pid,
            "waiting_pid_alive": bool(w_pid is not None and _process_alive(w_pid)),
            "waiting_deadline_epoch": (marker.get("deadline_epoch")
                                       if isinstance(marker, dict) else None),
            "restart_request": _restart_request_with_live_authority(
                store, store.read_restart_request(a)),
            "config_blocked_hold": store.read_config_blocked_hold(a),
            "session_id": st.get("session_id"),  # supervisor-local; None unless state passed
        }
        sup_agent = sup_agents.get(a) if isinstance(sup_agents.get(a), dict) else {}
        if bool(sup_agent.get("wrapped", False)):
            agents[a]["wrapper_runtime"] = runtime_obs.read_runtime(
                store.state_dir,
                a,
                now_epoch=now_epoch,
            )
        # Managed lead-loop visibility (lead-loop Slice 1; additive, read-only).
        # Present only when the agent is managed OR a lease file exists. The planner
        # acts on the EXIT marker (WP2) - this surfaces the armed/lease state so the
        # report shows a down managed controller.
        if store.is_managed_lead_loop(a) or store.read_lead_loop_lease(a) is not None:
            # Use the SAME per-agent threshold the report uses for the top-level
            # heartbeat_stale (threshold_a), so the nested lead_loop view never skews
            # from it - a wrapped agent's armed/stealable must agree with the
            # supervisor's stuck threshold, not the 120s store default (WP1 contract).
            agents[a]["lead_loop"] = store.lead_loop_state(
                a, now=now_epoch, heartbeat_stale_after=threshold_a)
        # The controller's EXIT marker (WP2): how a managed lead-loop controller last
        # exited - the planner uses it to NOT relaunch a deliberate stand-down / a
        # blocked acquire (vs a crash, which relaunches). Additive; present only when
        # a marker exists.
        _ll_exit = store.read_lead_loop_exit(a)
        if isinstance(_ll_exit, dict):
            agents[a]["lead_loop_exit"] = _ll_exit
    launch_requests = store.list_launch_requests()
    eph_report: dict[str, dict] = {"active": {}, "orphan_agents": []}
    eph_state = (state or {}).get("ephemeral_reviewers") if isinstance(state, dict) else None
    active_eph = eph_state.get("active") if isinstance(eph_state, dict) else None
    active_eph = active_eph if isinstance(active_eph, dict) else {}
    msgs = None
    for rid, entry in active_eph.items():
        if not isinstance(entry, dict):
            continue
        agent = entry.get("agent")
        requester = entry.get("requested_by")
        completion = {"status": eph.COMPLETION_NONE, "terminal": False,
                      "hold": True, "reason": "no typed review-result"}
        if isinstance(agent, str) and isinstance(requester, str):
            try:
                if msgs is None:
                    msgs = store.valid_messages()
                completion = eph.classify_review_result(
                    msgs, request_id=str(rid), agent=agent, requester=requester)
            except (ValueError, OSError, FileNotFoundError) as e:
                completion = {"status": eph.COMPLETION_MALFORMED, "terminal": False,
                              "hold": True, "reason": f"could not scan evidence: {e}"}
        eph_report["active"][rid] = {
            "request_id": rid,
            "agent": agent,
            "requested_by": requester,
            "phase": entry.get("phase"),
            "deadline_epoch": entry.get("deadline_epoch"),
            "launcher_pid": entry.get("launcher_pid"),
            "launcher_start": entry.get("launcher_start"),
            "wrapper_runtime": (
                runtime_obs.read_runtime(
                    store.state_dir,
                    agent,
                    now_epoch=now_epoch,
                )
                if isinstance(agent, str)
                else {
                    "status": runtime_obs.STATUS_ABSENT,
                    "record": None,
                    "error": "agent_missing",
                }
            ),
            "completion": completion,
        }
    known_temp = {
        entry.get("agent") for entry in active_eph.values()
        if isinstance(entry, dict) and isinstance(entry.get("agent"), str)
    }
    eph_report["orphan_agents"] = [
        a for a in roster if isinstance(a, str) and a.startswith("adversary-")
        and a not in known_temp
    ]
    return {
        "schema_version": 1,
        "root_key": _root_key(str(store.root.resolve())),
        "now_epoch": now_epoch,
        "now": datetime.fromtimestamp(now_epoch, timezone.utc).isoformat().replace(
            "+00:00", "Z"),
        "kill_switch_active": (store.dir / "supervisor.kill").exists(),
        "roster": list(roster),
        "operator_facing": store.operator_facing(),
        "sole_lead": store.sole_lead(),
        "stuck_after_seconds": threshold,
        "agents": agents,
        "launch_requests": launch_requests,
        "ephemeral_reviewers": eph_report,
    }


_BOOTSTRAP_SUPPORTED_CLIS = {"claude", "codex"}
_BOOTSTRAP_PLACEHOLDER_TOKENS = (
    "REPLACE",
    "REPLACE_WITH_PROJECT_DIR",
    "AGENT_NAME",
    "{AGENT}",
    "<CWD>",
)


def _bootstrap_add(checks: list[dict], check_id: str, status: str, detail: str,
                   *, agent: str | None = None, suggestion: str | None = None,
                   facts: dict | None = None) -> None:
    row = {"id": check_id, "status": status, "detail": detail}
    if agent is not None:
        row["agent"] = agent
    if suggestion:
        row["suggestion"] = suggestion
    if facts:
        row["facts"] = facts
    checks.append(row)


def _bootstrap_has_placeholder(value: object) -> bool:
    if isinstance(value, str):
        upper = value.upper()
        return any(token in upper for token in _BOOTSTRAP_PLACEHOLDER_TOKENS)
    if isinstance(value, list):
        return any(_bootstrap_has_placeholder(item) for item in value)
    if isinstance(value, dict):
        return any(_bootstrap_has_placeholder(item) for item in value.values())
    return False


def _bootstrap_arg_value(args: list, flag: str) -> str | None:
    for i, item in enumerate(args):
        if item == flag and i + 1 < len(args) and isinstance(args[i + 1], str):
            return args[i + 1]
        if isinstance(item, str) and item.startswith(flag + "="):
            return item[len(flag) + 1:]
    return None


def _bootstrap_flag_before(args: list, flag: str, before: str) -> bool:
    try:
        cut = args.index(before)
    except ValueError:
        cut = len(args)
    head = args[:cut]
    return flag in head or any(
        isinstance(item, str) and item.startswith(flag + "=") for item in head
    )


def _bootstrap_launch_tail(args: list) -> list:
    try:
        cut = args.index("--")
    except ValueError:
        return []
    return args[cut + 1:]


def bootstrap_check(store: Store, *, now_epoch: float,
                    supervisor_config: dict | None = None,
                    state: dict | None = None) -> dict:
    """Read-only readiness check for turning a roster into a live team.

    The check is intentionally CLI-neutral: Claude and Codex are both accepted
    managed CLIs, and the wrapper invariants are the same for either one. It
    answers the field-test question "is this identity merely in the roster, or
    is it a configured, fresh, supervised agent that the lead can assign work
    to?"
    """
    cfg = store.load_config()
    roster = [a for a in (cfg.get("agents") or []) if isinstance(a, str)]
    roles = cfg.get("roles") if isinstance(cfg.get("roles"), dict) else {}
    supervisor_config = supervisor_config if isinstance(supervisor_config, dict) else {}
    cfg_agents = (
        supervisor_config.get("agents")
        if isinstance(supervisor_config.get("agents"), dict) else {}
    )
    cfg_agent_names = set(cfg_agents)
    checks: list[dict] = []

    if roster:
        _bootstrap_add(checks, "roster_present", "ok",
                       f"roster has {len(roster)} agent(s)")
    else:
        _bootstrap_add(checks, "roster_missing", "error",
                       "no roster identities are configured",
                       suggestion="run agenttalk init or agenttalk roster add")

    liaison = store.operator_facing()
    if liaison is None:
        _bootstrap_add(
            checks, "operator_facing_missing", "error",
            "no live operator-facing liaison is configured",
            suggestion="run agenttalk roster set-operator-facing <lead-agent>",
        )
    else:
        _bootstrap_add(checks, "operator_facing_present", "ok",
                       f"operator-facing liaison is {liaison}", agent=liaison)

    if cfg_agents:
        _bootstrap_add(checks, "supervisor_agents_present", "ok",
                       f"supervisor.json has {len(cfg_agents)} configured agent(s)")
    else:
        _bootstrap_add(
            checks, "supervisor_agents_missing", "error",
            "supervisor.json has no configured agents",
            suggestion="run agenttalk supervise --init and fill the agents block",
        )

    report = build_report(
        store, now_epoch=now_epoch, state=state if isinstance(state, dict) else None,
        supervisor_config=supervisor_config,
    )
    report_agents = report.get("agents") if isinstance(report.get("agents"), dict) else {}

    for name in sorted(cfg_agents):
        raw_agent = cfg_agents.get(name)
        cfg_agent = raw_agent if isinstance(raw_agent, dict) else None
        if name not in roster:
            _bootstrap_add(
                checks, "supervisor_agent_not_in_roster", "error",
                "supervisor has an agent that is not in the roster",
                agent=name,
                suggestion="add it with agenttalk roster add, or remove it from supervisor.json",
            )
        if cfg_agent is None:
            _bootstrap_add(
                checks, "supervisor_agent_config_invalid", "error",
                "supervisor agent entry is not a JSON object",
                agent=name,
                suggestion="replace this entry with a normal supervisor agent block",
            )
            continue

        cli_name = cfg_agent.get("cli")
        if not isinstance(cli_name, str) or cli_name not in _BOOTSTRAP_SUPPORTED_CLIS:
            _bootstrap_add(
                checks, "supervisor_agent_cli_unsupported", "error",
                f"cli must be one of {sorted(_BOOTSTRAP_SUPPORTED_CLIS)}",
                agent=name,
                facts={"cli": cli_name},
                suggestion="set cli to claude or codex",
            )
        else:
            _bootstrap_add(checks, "supervisor_agent_cli_supported", "ok",
                           f"{cli_name} agent configured", agent=name,
                           facts={"cli": cli_name})

        backend_profile = cfg_agent.get("backend_profile")
        if backend_profile is not None:
            if backend_profile != "ovh-qwen":
                _bootstrap_add(
                    checks,
                    "supervisor_backend_profile_unsupported",
                    "error",
                    "backend_profile must be ovh-qwen when present",
                    agent=name,
                )
            else:
                trust_class = cfg_agent.get("trust_class")
                roster_trust = (cfg.get("trust_classes") or {}).get(name)
                errors = []
                if cli_name != "claude":
                    errors.append("cli must be claude")
                if cfg_agent.get("wrapped") is not True:
                    errors.append("wrapped must be true")
                if cfg_agent.get("model") != "Qwen3.5-397B-A17B":
                    errors.append("model must be Qwen3.5-397B-A17B")
                if trust_class != "external-worker" or roster_trust != "external-worker":
                    errors.append("supervisor and roster trust_class must be external-worker")
                if cfg_agent.get("env"):
                    errors.append("literal per-agent env is forbidden")
                profile_launch = cfg_agent.get("launch")
                profile_args = (
                    profile_launch.get("windows_args")
                    if isinstance(profile_launch, dict)
                    else None
                )
                if isinstance(profile_args, list) and "--lead-loop" in profile_args:
                    errors.append(
                        "lead-loop is unsupported because cadence has no immutable budget scope"
                    )
                ambient = [
                    key for key in ("OVH_KEY", "ANTHROPIC_API_KEY") if os.environ.get(key)
                ]
                if ambient:
                    errors.append("supervisor ambient provider keys must be absent")
                _bootstrap_add(
                    checks,
                    "supervisor_ovh_qwen_profile",
                    "error" if errors else "ok",
                    "; ".join(errors) if errors else "ovh-qwen profile is constrained",
                    agent=name,
                    facts={"backend_profile": backend_profile, "trust_class": trust_class},
                )

        if cfg_agent.get("auto_restart") is True:
            _bootstrap_add(checks, "supervisor_agent_restart_enabled", "ok",
                           "auto_restart is enabled", agent=name)
        else:
            _bootstrap_add(
                checks, "supervisor_agent_restart_disabled", "warn",
                "auto_restart is not enabled; the supervisor will not relaunch this agent",
                agent=name,
                suggestion="set auto_restart=true for unattended team members",
            )

        wrapped = bool(cfg_agent.get("wrapped"))
        if wrapped:
            _bootstrap_add(checks, "supervisor_agent_wrapped", "ok",
                           "wrapped agent configured", agent=name)
        else:
            _bootstrap_add(
                checks, "supervisor_agent_not_wrapped", "warn",
                "agent is not wrapped; manual-listen supervision is best-effort",
                agent=name,
                suggestion="prefer agenttalk wrap --loop for unattended Claude or Codex agents",
            )

        launch = cfg_agent.get("launch")
        launch = launch if isinstance(launch, dict) else None
        if launch is None:
            _bootstrap_add(
                checks, "supervisor_agent_launch_missing", "error",
                "launch block is missing or invalid",
                agent=name,
                suggestion="fill launch.windows_file and launch.windows_args",
            )
        else:
            windows_file = launch.get("windows_file")
            windows_args = launch.get("windows_args")
            if not isinstance(windows_file, str) or not windows_file.strip():
                _bootstrap_add(
                    checks, "supervisor_agent_launch_file_missing", "error",
                    "launch.windows_file is missing",
                    agent=name,
                    suggestion="set it to python.exe for wrapped agents or the real CLI exe for manual agents",
                )
            elif _bootstrap_has_placeholder(windows_file):
                _bootstrap_add(
                    checks, "supervisor_agent_launch_file_placeholder", "error",
                    "launch.windows_file still contains scaffold placeholder text",
                    agent=name,
                    suggestion="replace it with a real executable path",
                )
            else:
                _bootstrap_add(checks, "supervisor_agent_launch_file_set", "ok",
                               "launch.windows_file is set", agent=name)

            if not isinstance(windows_args, list):
                _bootstrap_add(
                    checks, "supervisor_agent_launch_args_invalid", "error",
                    "launch.windows_args must be a JSON array",
                    agent=name,
                    suggestion="replace windows_args with an array of literal argument tokens",
                )
            elif _bootstrap_has_placeholder(windows_args):
                _bootstrap_add(
                    checks, "supervisor_agent_launch_args_placeholder", "error",
                    "launch.windows_args still contains scaffold placeholder text",
                    agent=name,
                    suggestion="replace the placeholder wrapper or CLI arguments",
                )
            else:
                _bootstrap_add(checks, "supervisor_agent_launch_args_set", "ok",
                               "launch.windows_args is filled", agent=name)

            # Round 16 connector finding: making the resolver delegation run
            # unconditionally (round 14) also made it run for launches that
            # are not Python at all - a manual archetype's claude.exe/
            # codex.exe direct launch, or an agenttalk.exe entry-point
            # launch - where windows_args never contains '-m'/'agenttalk'
            # and the whole question of a module boundary is meaningless.
            # windows_file's stem, not wrapped=true/false, is what actually
            # decides whether the runtime resolver's own logic ever runs
            # for this agent (_agenttalk_argv gates on exactly this set) -
            # so this check must be gated on the SAME set, not removed
            # back to "only when module_args_from is present" (that would
            # reopen round 14's absent-prefix gap for genuinely Python
            # launches). "pythonw" is deliberately NOT in this set: the
            # runtime does not recognize it either (see _agenttalk_argv),
            # so a pythonw-launched wrapped agent already gets no
            # attribution regardless of module_args_from - a real, separate
            # gap, not something this validator can paper over by silently
            # accepting it here.
            if _token_stem(windows_file) in {"python", "python3", "py"}:
                module_args_from = launch.get("module_args_from")
                module_args_from_type_or_range_error = False
                if module_args_from is not None:
                    if not isinstance(module_args_from, int) or isinstance(module_args_from, bool):
                        _bootstrap_add(
                            checks, "supervisor_agent_launch_module_args_from_invalid", "error",
                            "launch.module_args_from must be an integer",
                            agent=name,
                            facts={"module_args_from": module_args_from},
                            suggestion="set module_args_from to the index of '-m' in windows_args, "
                                       "or remove it",
                        )
                        module_args_from_type_or_range_error = True
                    elif isinstance(windows_args, list) and not (
                        0 <= module_args_from < len(windows_args)
                    ):
                        _bootstrap_add(
                            checks, "supervisor_agent_launch_module_args_from_out_of_range", "error",
                            "launch.module_args_from is out of range for windows_args",
                            agent=name,
                            facts={"module_args_from": module_args_from,
                                   "windows_args_len": len(windows_args)},
                            suggestion="point module_args_from at the index of '-m' in windows_args",
                        )
                        module_args_from_type_or_range_error = True
                # In-range is necessary but not sufficient (PR 98 connector,
                # round 9): the validator must accept exactly what the
                # runtime resolver accepts, no more - an in-range
                # module_args_from pointing at the wrong token, or a
                # declared prefix containing a token outside the supported
                # interpreter-flag allowlist, launches fine (the Python
                # invocation still runs) while nonce injection, bounded
                # logging, and launcher attribution are all silently
                # disabled. Round 14: that includes module_args_from being
                # ABSENT while windows_args carries an undeclared prefix
                # (e.g. ["-u", "-m", "agenttalk", ...]) - the resolver
                # defaults an absent field to offset 0 exactly like this
                # call does, so skipping the check whenever the field is
                # merely unset let that exact shape report clean. Run
                # unconditionally (any type/range error above already
                # fully explains the config; no need to also run this).
                # Delegate to the SAME resolver the runtime uses instead of
                # reimplementing this judgment a third time.
                if not module_args_from_type_or_range_error and isinstance(windows_args, list):
                    if _resolve_module_flag_index(
                        [str(token) for token in windows_args], module_args_from,
                    ) < 0:
                        _bootstrap_add(
                            checks, "supervisor_agent_launch_module_args_from_wrong_token",
                            "error",
                            (
                                "launch.module_args_from is in range but does not point at "
                                "'-m' 'agenttalk', or its declared prefix contains a token "
                                "outside the supported interpreter-flag set"
                                if module_args_from is not None else
                                "launch.module_args_from is not set and windows_args does "
                                "not start with '-m' 'agenttalk' - the runtime resolver "
                                "defaults an absent declaration to offset 0 and will reject "
                                "this exact invocation the same way"
                            ),
                            agent=name,
                            facts={"module_args_from": module_args_from,
                                   "windows_args": windows_args},
                            suggestion="point module_args_from at the index of '-m' in "
                                       "windows_args, and declare only supported "
                                       "interpreter flags before it (see "
                                       "docs/supervisor-tutorial.md)",
                        )
                    else:
                        _bootstrap_add(
                            checks, "supervisor_agent_launch_module_args_from_valid", "ok",
                            (
                                "launch.module_args_from is a valid index"
                                if module_args_from is not None else
                                "windows_args resolves as the plain, undeclared "
                                "'-m' 'agenttalk' form"
                            ),
                            agent=name,
                        )

            if wrapped and isinstance(windows_args, list):
                if "wrap" not in windows_args:
                    _bootstrap_add(
                        checks, "supervisor_wrapped_missing_wrap", "error",
                        "wrapped=true but launch args do not call agenttalk wrap",
                        agent=name,
                    )
                if not _bootstrap_flag_before(windows_args, "--root", "wrap"):
                    _bootstrap_add(
                        checks, "supervisor_wrapped_missing_root", "error",
                        "wrapped launch does not include an explicit --root before wrap",
                        agent=name,
                        suggestion="add --root {ROOT} before wrap in windows_args",
                    )
                if "--loop" not in windows_args:
                    _bootstrap_add(
                        checks, "supervisor_wrapped_missing_loop", "error",
                        "wrapped launch is missing --loop",
                        agent=name,
                    )
                if "--" not in windows_args:
                    _bootstrap_add(
                        checks, "supervisor_wrapped_missing_cli_tail", "error",
                        "wrapped launch is missing the -- separator and real CLI tail",
                        agent=name,
                    )
                arg_for = _bootstrap_arg_value(windows_args, "--for")
                if arg_for != name:
                    _bootstrap_add(
                        checks, "supervisor_wrapped_for_mismatch", "error",
                        "wrapped --for does not match the supervisor agent name",
                        agent=name,
                        facts={"wrapped_for": arg_for},
                        suggestion=f"set --for {name}",
                    )
                arg_cli = _bootstrap_arg_value(windows_args, "--cli")
                if isinstance(cli_name, str) and arg_cli != cli_name:
                    _bootstrap_add(
                        checks, "supervisor_wrapped_cli_mismatch", "error",
                        "wrapped --cli does not match the supervisor agent cli",
                        agent=name,
                        facts={"wrapped_cli": arg_cli, "cli": cli_name},
                        suggestion=f"set --cli {cli_name}",
                    )
                tail = _bootstrap_launch_tail(windows_args)
                if not tail:
                    _bootstrap_add(
                        checks, "supervisor_wrapped_cli_tail_empty", "error",
                        "wrapped launch has no real CLI command after --",
                        agent=name,
                    )
                elif _bootstrap_has_placeholder(tail[0]):
                    _bootstrap_add(
                        checks, "supervisor_wrapped_cli_tail_placeholder", "error",
                        "wrapped launch real CLI tail still contains placeholder text",
                        agent=name,
                        suggestion="replace the tail after -- with the real claude.exe or codex.exe command",
                    )

        rpt = report_agents.get(name) if isinstance(report_agents.get(name), dict) else None
        if rpt is None:
            continue
        if bool(rpt.get("heartbeat_stale")):
            _bootstrap_add(
                checks, "supervisor_agent_not_fresh", "error",
                "managed agent has no fresh heartbeat",
                agent=name,
                facts={"heartbeat_age_seconds": rpt.get("heartbeat_age_seconds")},
                suggestion="start the supervisor and wait for this agent to reach HEALTHY_IDLE",
            )
        else:
            _bootstrap_add(
                checks, "supervisor_agent_fresh", "ok",
                "managed agent has a fresh heartbeat",
                agent=name,
                facts={"heartbeat_age_seconds": rpt.get("heartbeat_age_seconds")},
            )

    for name in roster:
        if name in cfg_agent_names:
            continue
        rpt = report_agents.get(name) if isinstance(report_agents.get(name), dict) else None
        fresh = bool(rpt is not None and not rpt.get("heartbeat_stale"))
        if name == liaison:
            if fresh:
                _bootstrap_add(checks, "operator_facing_fresh", "ok",
                               "operator-facing liaison has a fresh heartbeat", agent=name)
            else:
                _bootstrap_add(
                    checks, "operator_facing_not_fresh", "warn",
                    "operator-facing liaison is not supervisor-managed and has no fresh heartbeat",
                    agent=name,
                    suggestion="run a liaison heartbeat/listen hook, or manage the lead-loop separately",
                )
            continue
        role = roles.get(name) if isinstance(roles.get(name), str) else None
        if fresh:
            _bootstrap_add(checks, "manual_roster_agent_fresh", "ok",
                           "roster identity is not supervised but has a fresh heartbeat",
                           agent=name, facts={"role": role})
        else:
            _bootstrap_add(
                checks, "roster_identity_not_live", "warn",
                "roster identity is not supervisor-managed and has no fresh heartbeat",
                agent=name,
                facts={"role": role},
                suggestion="supervise it, retire it, or deliberately ignore it before assigning work",
            )

    summary = {
        "ok": sum(1 for c in checks if c.get("status") == "ok"),
        "warn": sum(1 for c in checks if c.get("status") == "warn"),
        "error": sum(1 for c in checks if c.get("status") == "error"),
    }
    verdict = "error" if summary["error"] else "warn" if summary["warn"] else "ok"
    return {
        "schema_version": 1,
        "root_key": _root_key(str(store.root.resolve())),
        "now_epoch": now_epoch,
        "now": datetime.fromtimestamp(now_epoch, timezone.utc).isoformat().replace(
            "+00:00", "Z"),
        "verdict": verdict,
        "summary": summary,
        "checks": checks,
        "supported_clis": sorted(_BOOTSTRAP_SUPPORTED_CLIS),
    }


def _health_brief(view: dict | None) -> dict:
    state = health_model.label(view)
    age = view.get("age_seconds") if isinstance(view, dict) else None
    warnings = view.get("warnings") if isinstance(view, dict) else []
    return {
        "state": state,
        "age_seconds": age if isinstance(age, (int, float)) else None,
        "warnings": warnings if isinstance(warnings, list) else [],
        "advisory": True,
    }


def _plan_one(name: str, rpt: dict, st: dict, config: dict, cfg_agent: dict,
              liveness: dict, *, now_epoch: float) -> dict:
    """Decide ONE agent's action + next state. PURE - no I/O, no clock.

    Manual agents retain heartbeat authority. Wrapped agents require a strict
    runtime observation plus the snapshot-derived CLI child state; ambiguous
    child evidence is neither green nor automatic kill authority.
    """
    backoff = _backoff_cfg(config)
    base, cap = float(backoff["base_seconds"]), float(backoff["cap_seconds"])
    reset_after = float(backoff["reset_after_seconds"])
    suspect_interval = float(config.get(
        "suspect_warn_interval_seconds", _DEFAULTS["suspect_warn_interval_seconds"]))
    grace_seconds = float(config.get("launch_grace_seconds", _DEFAULTS["launch_grace_seconds"]))
    max_readiness_retries = int(config.get(
        "max_readiness_retries", _DEFAULTS["max_readiness_retries"]))
    raw_restart_cooldown = config.get(
        "restart_cooldown_seconds", _DEFAULTS["restart_cooldown_seconds"])
    restart_cooldown = (
        float(raw_restart_cooldown)
        if isinstance(raw_restart_cooldown, (int, float)) and not isinstance(raw_restart_cooldown, bool)
        else float(_DEFAULTS["restart_cooldown_seconds"])
    )
    restart_cooldown = min(60.0, max(30.0, restart_cooldown))
    activity_hook = bool(cfg_agent.get("activity_hook", False))
    _lcfg = _liveness_cfg(cfg_agent)
    # A wrapped agent has two independent observations: wrapper heartbeat/runtime
    # phase and process-snapshot CLI brain state. A stale idle wrapper retains the
    # existing recovery path. During a turn, real adapter progress and a live brain
    # are required; a synthetic work-heartbeat is never progress.
    wrapped = bool(_lcfg.get("wrapped", False))
    cli_name = cfg_agent.get("cli", "claude")
    stuck_after = resolve_stuck_after(config, cfg_agent)
    # GUARDRAIL (Codex ruling): for a wrapped CODEX, restart-on-stale below the
    # min threshold is too aggressive (item-level stream => likely false-kill
    # mid-reasoning). REFUSE restart authority (degrade to warn-only) + warn,
    # unless the operator explicitly opts in. We never silently coerce the value.
    # This grants kill authority, so JSON truthiness is not an opt-in.
    allow_low_stuck_after = cfg_agent.get("allow_low_stuck_after") is True
    unsafe_low_codex = (wrapped and cli_name == "codex"
                        and stuck_after < _WRAPPED_CODEX_MIN_STUCK_AFTER
                        and not allow_low_stuck_after)
    # TIMING-INVARIANT GUARD (v0.47.0): a wrapped codex with the per-turn watchdog
    # EFFECTIVELY LIVE must have stuck_after ABOVE the watchdog deadline + margin, else the
    # supervisor would kill + relaunch the wrapper into the same wedge BEFORE the watchdog
    # fires. REFUSE restart-on-stale (warn-only) when it would preempt, unless
    # allow_low_stuck_after. CRITICAL: gate this on the SHARED watchdog_effectively_live
    # predicate (the same one cmd_wrap uses) - if the watchdog is effectively DISABLED
    # (sub-floor turn_elapsed without opt-in), the supervisor KEEPS its normal
    # recover-on-stale authority, so the agent is never left with neither.
    from agenttalk.wrapper import turn_watchdog as _twd
    _wd_cfg = _twd.resolve_turn_watchdog(
        config, cfg_agent, default_enabled=(wrapped and cli_name == "codex"))
    watchdog_live = _twd.watchdog_effectively_live(_wd_cfg)
    watchdog_turn_elapsed = _wd_cfg.turn_elapsed_seconds
    progress_stall_floor, progress_stall_floor_error = (
        _resolved_progress_stall_floor(
            config,
            cfg_agent,
            watchdog_turn_elapsed,
        )
    )
    watchdog_preempted = (wrapped and cli_name == "codex" and watchdog_live
                          and stuck_after <= watchdog_turn_elapsed + _WATCHDOG_STUCK_AFTER_MARGIN
                          and not allow_low_stuck_after)
    from agenttalk.wrapper import work_heartbeat as _whb
    _work_hb_problem = None
    if wrapped and cli_name == "claude":
        _whb_cfg = _whb.resolve_work_heartbeat(
            config, cfg_agent, cli=cli_name, mode=_whb.MODE_LOOP)
        _work_hb_problems = list(_whb_cfg.config_errors)
        _work_hb_violation = _whb.interval_violation(
            _whb_cfg, stuck_after_seconds=stuck_after)
        if _work_hb_violation:
            _work_hb_problems.append(_work_hb_violation)
        if not _whb_cfg.enabled:
            _work_hb_problem = "work heartbeat ticker disabled"
        elif _work_hb_problems:
            _work_hb_problem = "; ".join(_work_hb_problems)
    can_confirm_stuck = ((activity_hook or wrapped)
                         and not unsafe_low_codex and not watchdog_preempted
                         and _work_hb_problem is None)
    # the EFFECTIVE isolation flag (per-CLI default merged) - emitted in the plan
    # so the executor seeds CODEX_HOME exactly when the planner assumed it, even
    # if the raw config omits the field (codex impl-review MAJOR).
    codex_home_isolation = bool(_lcfg.get("codex_home_isolation", False))
    windows_sandbox = _lcfg.get("windows_sandbox", "unelevated")  # UAC fix (codex)
    perm_mode = claude_permission_mode(config, cfg_agent)  # Claude unattended mode
    window_style, window_style_warning = resolve_window_style(config, cfg_agent)

    protected = bool(rpt.get("protected"))
    # build_report computes heartbeat_stale per-agent when it is given the
    # supervisor_config (cmd_supervise passes it), but a legacy/global report (no
    # supervisor_config) uses the single global threshold. The planner is the
    # safety authority, so for a WRAPPED agent it ALWAYS re-derives staleness from
    # the reported age against its per-CLI threshold (a codex must tolerate a long
    # silent reasoning gap) - harmless when the report already matched, and the
    # backstop when a global report file is supplied. Non-wrapped agents keep the
    # report's decision unchanged. A wrapped agent that never heartbeated (age
    # None) keeps the report's stale=True.
    hb_stale = bool(rpt.get("heartbeat_stale"))
    if wrapped:
        hb_age = rpt.get("heartbeat_age_seconds")
        if isinstance(hb_age, (int, float)):
            hb_stale = float(hb_age) > stuck_after
    health = rpt.get("health") if isinstance(rpt.get("health"), dict) else {}
    if hb_stale and health_model.label(health) == health_model.STATE_WORKING_SILENT:
        health = dict(health)
        warnings = health.get("warnings") if isinstance(health.get("warnings"), list) else []
        if "advisory-health-conflict" not in warnings:
            health["warnings"] = [*warnings, "advisory-health-conflict"]
    marker = rpt.get("restart_request") or None
    consumed = list(st.get("consumed_rids", []))
    fails = int(st.get("consecutive_fails", 0))
    readiness_fails = int(st.get("readiness_fails", 0))
    backoff_next = float(st.get("backoff_next_epoch", 0.0) or 0.0)
    healthy_since = st.get("healthy_since")
    last_warn = float(st.get("last_warn_epoch", 0.0) or 0.0)

    brain_pid = liveness.get("brain_pid")
    brain_start = liveness.get("brain_start")
    managed = liveness.get("managed_pids") or []
    owned_tree = (
        liveness.get("owned_process_tree")
        if isinstance(liveness.get("owned_process_tree"), dict)
        else None
    )
    attributed_targets = liveness.get("kill_targets") or []
    diagnostics = liveness.get("diagnostics") or _diag()

    launching = bool(st.get("launching", False))
    grace_until = float(st.get("launch_grace_until", 0.0) or 0.0)
    readiness_seen = bool(st.get("readiness_seen", False))
    resume_available = bool(st.get("resume_available", False))

    # Manual agents retain heartbeat-only readiness. Wrapped readiness is earned
    # only by a green row in the total child-health table below.
    if not wrapped and not hb_stale and not readiness_seen:
        readiness_seen, launching, resume_available = True, False, True
        readiness_fails = 0   # readiness REACHED -> clear the give-up counter
    in_grace = launching and (not readiness_seen) and now_epoch < grace_until

    runtime_record = (
        liveness.get("runtime_record")
        if isinstance(liveness.get("runtime_record"), dict)
        else None
    )
    runtime_valid = (
        liveness.get("runtime_status") == runtime_obs.STATUS_VALID
        and runtime_record is not None
    )
    runtime_wrapper_generation = (
        runtime_record.get("wrapper_generation") if runtime_valid else None
    )
    runtime_turn_generation = (
        runtime_record.get("turn_generation") if runtime_valid else None
    )
    runtime_phase = runtime_record.get("phase") if runtime_valid else None
    runtime_sequence = (
        runtime_record.get("progress_sequence") if runtime_valid else None
    )
    prior_wrapper_generation = st.get("runtime_wrapper_generation")
    prior_turn_generation = st.get("runtime_turn_generation")
    same_runtime_turn = bool(
        runtime_valid
        and runtime_wrapper_generation == prior_wrapper_generation
        and runtime_turn_generation == prior_turn_generation
    )
    prior_sequence = st.get("runtime_progress_sequence")
    sequence_regressed = bool(
        same_runtime_turn and st.get("runtime_sequence_regressed", False)
    )
    progress_seen_epoch = st.get("runtime_progress_seen_epoch")
    if not isinstance(progress_seen_epoch, (int, float)) or not math.isfinite(
        float(progress_seen_epoch)
    ):
        progress_seen_epoch = now_epoch
    if runtime_valid:
        if not same_runtime_turn:
            initial_progress_age = liveness.get("runtime_progress_age_seconds")
            progress_seen_epoch = (
                now_epoch - float(initial_progress_age)
                if isinstance(initial_progress_age, (int, float))
                and not isinstance(initial_progress_age, bool)
                and math.isfinite(float(initial_progress_age))
                and float(initial_progress_age) >= 0
                else now_epoch
            )
            sequence_regressed = False
        elif (
            isinstance(runtime_sequence, int)
            and isinstance(prior_sequence, int)
            and runtime_sequence < prior_sequence
        ):
            sequence_regressed = True
        elif (
            isinstance(runtime_sequence, int)
            and isinstance(prior_sequence, int)
            and runtime_sequence > prior_sequence
        ):
            progress_seen_epoch = now_epoch
    else:
        # An unreadable observation is indivisibly UNKNOWN. Preserve the last
        # complete high-water mark so a torn read cannot erase evidence and
        # launder a lower sequence on the next valid read. Confirmation polls
        # are still reset below, so UNKNOWN itself never advances kill authority.
        sequence_regressed = st.get("runtime_sequence_regressed") is True

    if runtime_valid:
        next_wrapper_generation = runtime_wrapper_generation
        next_turn_generation = runtime_turn_generation
        next_runtime_phase = runtime_phase
        next_runtime_sequence = (
            max(prior_sequence, runtime_sequence)
            if sequence_regressed
            and isinstance(prior_sequence, int)
            and isinstance(runtime_sequence, int)
            else runtime_sequence
        )
    else:
        next_wrapper_generation = prior_wrapper_generation
        next_turn_generation = prior_turn_generation
        next_runtime_phase = st.get("runtime_phase")
        next_runtime_sequence = prior_sequence

    # Carry forward supervisor-owned fields. The raw process snapshot is never
    # persisted; wrapped agents store only the bounded strict projection earned
    # above.
    nxt = {
        "consecutive_fails": fails, "backoff_next_epoch": backoff_next,
        "healthy_since": healthy_since, "consumed_rids": consumed,
        "last_warn_epoch": last_warn,
        "launcher_pid": st.get("launcher_pid"), "launcher_start": st.get("launcher_start"),
        "launcher_nonce": st.get("launcher_nonce"),
        "launcher_nonce_injected": st.get("launcher_nonce_injected"),
        "launcher_nonce_source": st.get("launcher_nonce_source"),
        "launcher_nonce_missing_reason": st.get("launcher_nonce_missing_reason"),
        "brain_pid": brain_pid, "brain_start": brain_start, "managed_pids": managed,
        "launching": launching, "launch_grace_until": grace_until,
        "readiness_seen": readiness_seen, "resume_available": resume_available,
        "readiness_fails": readiness_fails,
        "last_launch_epoch": st.get("last_launch_epoch"),
        "session_id": st.get("session_id"), "launched": bool(st.get("launched", False)),
        "runtime_wrapper_generation": next_wrapper_generation,
        "runtime_turn_generation": next_turn_generation,
        "runtime_phase": next_runtime_phase,
        "runtime_progress_sequence": next_runtime_sequence,
        "runtime_progress_seen_epoch": progress_seen_epoch,
        "runtime_sequence_regressed": sequence_regressed,
        "runtime_dead_polls": 0,
        "runtime_stall_polls": 0,
    }
    if "revoked_wrapper_runtime" in st:
        # Keep the fixed-size revocation boundary across reset, relaunch
        # reservation, and the window before the new wrapper publishes its
        # first strict runtime record.
        nxt["revoked_wrapper_runtime"] = copy.deepcopy(
            st.get("revoked_wrapper_runtime")
        )
    if owned_tree is not None:
        nxt["owned_process_tree"] = copy.deepcopy(owned_tree)
    legacy_process_evidence = liveness.get("legacy_process_evidence")
    if isinstance(legacy_process_evidence, dict):
        nxt["legacy_process_evidence"] = copy.deepcopy(
            legacy_process_evidence
        )
    if liveness.get("owned_process_tree_pending") is True:
        nxt["owned_process_tree_pending"] = True

    def _relaunch_state() -> None:
        nf = fails + 1
        nxt["consecutive_fails"] = nf
        nxt["backoff_next_epoch"] = now_epoch + min(cap, base * (2 ** (nf - 1)))
        nxt["healthy_since"] = None
        # a relaunch starts a fresh grace; readiness must be re-earned and the
        # stale brain pid is cleared (re-discovered after relaunch).
        nxt["readiness_seen"] = False
        nxt["launching"] = True
        nxt["launch_grace_until"] = now_epoch + grace_seconds
        nxt["brain_pid"] = None
        nxt["brain_start"] = None
        nxt["managed_pids"] = []
        nxt["runtime_dead_polls"] = 0
        nxt["runtime_stall_polls"] = 0

    def _barrier_backoff_state() -> dict:
        hold = copy.deepcopy(nxt)
        nf = fails + 1
        hold["consecutive_fails"] = nf
        hold["backoff_next_epoch"] = now_epoch + min(cap, base * (2 ** (nf - 1)))
        hold["healthy_since"] = None
        return hold

    def _targets(include_launcher: bool) -> list[dict]:
        # EVERY kill target carries its start-time so the executor can refuse to
        # kill a recycled pid (codex discipline note 2).
        out: list[dict] = []
        for target in attributed_targets:
            if not isinstance(target, dict):
                continue
            if not include_launcher and target.get("reason") == "confirmed_launcher":
                continue
            if isinstance(target.get("pid"), int) and isinstance(target.get("start"), str) and target.get("start"):
                item = {
                    "pid": target["pid"],
                    "start": target["start"],
                    "reason": target.get("reason") or target.get("source") or "live_chain",
                    "source": target.get("source") or target.get("reason") or "live_chain",
                }
                start_filetime = target.get("start_filetime")
                if isinstance(start_filetime, str) and start_filetime:
                    item["start_filetime"] = start_filetime
                out.append(item)
        return out

    def _result(action, *, state, kill_first=False, kill_orphans=False,
                kill_targets=None, clear_marker=None, bypass_backoff=False,
                notify=False, discover_brain=False, reason="",
                barrier_state=None):
        if wrapped and (
            state.startswith("CLI_CHILD_")
            or state in {"TURN_FAILED", "WRAPPER_MISSING", "STUCK_OR_DEAD"}
        ):
            nxt["healthy_since"] = None
        res = {"agent": name, "action": action, "state": state,
               "clear_marker": clear_marker, "kill_first": bool(kill_first),
               "kill_orphans": bool(kill_orphans), "kill_targets": kill_targets or [],
               "bypass_backoff": bool(bypass_backoff), "notify": bool(notify),
               "discover_brain": bool(discover_brain),
               "codex_home_isolation": codex_home_isolation,
               "windows_sandbox": windows_sandbox, "perm_mode": perm_mode,
               "window_style": window_style,
               "window_style_warning": window_style_warning,
               "reason": reason, "cli": None, "launch_mode": None,
               "resume_mode": None, "session_id": None, "session_args": None,
               "health": _health_brief(health),
               "diagnostics": {k: v for k, v in diagnostics.items() if v},
               "next_state": nxt}
        if action in (RELAUNCH, STUCK_RECOVER):
            res.update(_launch_detail({**st, "resume_available": resume_available},
                                      cfg_agent, perm_mode=perm_mode))
            if isinstance(barrier_state, dict):
                res["barrier_state"] = barrier_state
        return res

    def _healthy(state: str, reason: str) -> dict:
        nxt["runtime_dead_polls"] = 0
        nxt["runtime_stall_polls"] = 0
        if wrapped:
            nxt["readiness_seen"] = True
            nxt["launching"] = False
            nxt["resume_available"] = True
            nxt["readiness_fails"] = 0
        if healthy_since is None:
            nxt["healthy_since"] = now_epoch
        elif fails and (now_epoch - float(healthy_since)) >= reset_after:
            nxt["consecutive_fails"], nxt["backoff_next_epoch"] = 0, 0.0
        return _result(NONE, state=state, reason=reason)

    # A partial wrapped tree is evidence, never teardown authority. This check
    # precedes even an authorized restart marker: Stop-Tree cannot safely reap
    # an omitted branch, and consuming the marker would hide the operator's
    # still-unfulfilled request. The durable state projection feeds the global
    # Attention queue until an attended ownership reset/new generation replaces
    # it. Only the explicit generation-adoption marker may complete next poll.
    tree_status = owned_tree.get("status") if owned_tree is not None else None
    if wrapped and tree_status in {"truncated", "invalid"}:
        observed = owned_tree.get("observed_count")
        limit = owned_tree.get("limit")
        notify = now_epoch - last_warn >= suspect_interval
        if notify:
            nxt["last_warn_epoch"] = now_epoch
        # Task #150: name the remedy. A held state that does not tell the
        # operator how to leave it is a defect on its own - especially since
        # the obvious guess (kill the wrapper, expecting the supervisor to
        # see it absent and relaunch) makes this WORSE, not better: a
        # wrapper this is still holding for is exempt from this HOLD the
        # moment it is independently confirmed absent (see
        # _unverified_owned_process_tree); a wrapper that is still present,
        # or whose absence this record cannot yet prove on its own, needs
        # the attended reset.
        #
        # Round 2 (connector findings 2 and 3): the FIRST version of this
        # remedy named --reset-process-tree-ownership unconditionally and
        # was wrong twice over. (a) --acknowledge-owned-processes-stopped's
        # own contract already covers "any identities omitted by a
        # truncated record" - the message must not narrow that to only the
        # NAMED ones. (b) --reset-process-tree-ownership requires the tree
        # evidence to carry a real wrapper_generation/launch_nonce that
        # agrees with a CURRENT, valid runtime record - true for a tree
        # _owned_process_tree itself walked (non-empty entries), but an
        # entryless placeholder (_invalid_owned_process_tree_record - schema
        # drift, a revoked runtime, legacy migration evidence) usually has
        # no such nonce to agree with, so the command fails for precisely
        # the case that names it. Naming a remedy that cannot work is worse
        # than naming none, so the entryless case gets an honest "no
        # verified one-line fix" message instead of a command that would
        # frustrate the operator a second time.
        #
        # Round 3 (connector finding 6, the same wrong direction again): a
        # REJECTED candidate is precisely what this record's own entries
        # never named either, same as a truncated record's omitted ones -
        # but the reset command's own identity list is built from entries
        # alone, so it has no way to know about a rejected candidate at
        # all. The flag's own text only mentions omitted identities; a
        # nonzero rejected_count needs the same warning stated explicitly,
        # not folded silently into "every process this record could name".
        has_entries = bool(owned_tree.get("entries"))
        rejected_count = owned_tree.get("rejected_count")
        if has_entries:
            rejected_clause = (
                f" This record also excluded {rejected_count} candidate(s) "
                "the walk could not admit (rejected_count) - the reset "
                "command's own identity list does not include them, so "
                "confirming those specifically gone is on you, not the "
                "command."
                if isinstance(rejected_count, int) and rejected_count > 0
                else ""
            )
            remedy = (
                "recovery: if every process this record could name is "
                "confirmed gone - including any omitted by a truncated "
                "record, which is exactly what --acknowledge-owned-"
                "processes-stopped attests to -"
                f"{rejected_clause} run `agenttalk supervise "
                "--reset-process-tree-ownership` (see --help for the "
                "required --acknowledge-* flags); do NOT kill the wrapper "
                "expecting an automatic relaunch - that is only safe once "
                "this record already reflects the wrapper as absent"
            )
        else:
            remedy = (
                "recovery: this record has no observed process identities "
                "to reset against, so --reset-process-tree-ownership will "
                "refuse it; a new wrapper generation replaces this record "
                "automatically once adopted - if it does not clear on its "
                "own, this needs operator investigation of "
                f"{owned_tree.get('reason_code')}, not a scripted remedy"
            )
        if tree_status == "truncated":
            tree_state = "PROCESS_TREE_TRUNCATED"
            tree_reason = (
                f"owned process tree observed {observed} identities over cap "
                f"{limit}; HOLDING automatic teardown because a partial kill "
                f"could strand descendants; {remedy}"
            )
        else:
            tree_state = "PROCESS_TREE_INVALID"
            tree_reason = (
                "owned process tree failed strict parent/start validation "
                f"({owned_tree.get('reason_code')}); HOLDING automatic teardown "
                f"because a partial kill could strand descendants; {remedy}"
            )
        return _result(
            WARN_ONLY,
            state=tree_state,
            notify=notify,
            reason=tree_reason,
        )

    # 0) Manual restart-request marker (highest priority).
    if isinstance(marker, dict) and isinstance(marker.get("request_id"), str):
        rid = marker["request_id"]
        auth_ok = (
            marker.get("authority_result") == "authorized"
            and isinstance(marker.get("requested_by"), str)
            and isinstance(marker.get("authorized_by"), str)
            and marker.get("authorized_by") == marker.get("requested_by")
            and marker.get("authority_still_valid", True) is True
        )
        if not auth_ok:
            nxt["last_warn_epoch"] = now_epoch
            return _result(REFUSE_PROTECTED, state="RESTART_UNAUTHORIZED",
                           notify=True,
                           reason="restart-request has no valid authorization marker")
        force_authorized = (
            marker.get("force_protected_authorized") is True
            and isinstance(marker.get("force_protected_authorized_by"), str)
            and marker.get("force_protected_still_authorized", True) is True
        )
        if protected and not force_authorized:
            nxt["last_warn_epoch"] = now_epoch
            return _result(REFUSE_PROTECTED, state="REFUSE_PROTECTED",
                           notify=True, reason="restart of a protected agent requires "
                                               "authorized --force-protected")
        if rid not in consumed:
            live_kill_ack = (
                marker.get("acknowledge_live_protected_kill_authorized") is True
                and marker.get("acknowledge_live_protected_kill_still_authorized", True) is True
            )
            if protected and not hb_stale and not live_kill_ack:
                nxt["last_warn_epoch"] = now_epoch
                return _result(REFUSE_PROTECTED, state="LIVE_PROTECTED_REFUSED",
                               notify=True,
                               reason="protected agent has a fresh heartbeat; repeat the "
                                      "operator-facing request with "
                                      "--acknowledge-live-protected-kill")
            last_launch = st.get("last_launch_epoch")
            if isinstance(last_launch, (int, float)) and now_epoch - float(last_launch) < restart_cooldown:
                return _result(BACKOFF_WAIT, state="RESTART_COOLDOWN",
                               reason=f"manual restart-request {rid} cooling down "
                                      f"until {float(last_launch) + restart_cooldown:.0f} "
                                      f"(requested_by={marker.get('requested_by')})")
            barrier_state = copy.deepcopy(nxt)
            nxt["consumed_rids"] = [*consumed, rid]
            kt = _targets(include_launcher=True)
            _relaunch_state()
            nxt["readiness_fails"] = 0   # operator restart CLEARS a readiness give-up
            nxt["restart_request_state"] = "applied_pending_readiness"
            nxt["pending_restart_request_id"] = rid
            nxt["restart_requested_by"] = marker.get("requested_by")
            nxt["restart_authorized_by"] = marker.get("authorized_by")
            nxt["restart_authority_result"] = marker.get("authority_result")
            nxt["restart_authority_reason"] = marker.get("authority_reason")
            return _result(RELAUNCH, state="MANUAL_RESTART",
                           kill_first=bool(kt), kill_targets=kt, bypass_backoff=True,
                           reason=f"manual restart-request {rid}",
                           barrier_state=barrier_state)
        runtime_idle_ready = (
            not wrapped
            or (
                runtime_valid
                and runtime_phase == runtime_obs.PHASE_IDLE
                and liveness.get("wrapper_state") == "alive"
            )
        )
        if not hb_stale and readiness_seen and runtime_idle_ready:
            nxt["restart_request_state"] = "readiness_seen"
            return _result(CLEAR_MARKER, state="HEALTHY_IDLE", clear_marker=rid,
                           reason=f"restart {rid} reached readiness; clearing marker")
        # consumed but still stale -> relaunch failed; fall through (no re-bypass).

    child_recovery_reason: str | None = None
    child_recovery_state: str | None = None
    if wrapped:
        remediation = (
            "agenttalk supervise --refresh-scripts; "
            f"agenttalk request-restart --for {name}"
        )
        if not runtime_valid:
            return _result(
                NONE,
                state="CLI_CHILD_UNKNOWN",
                reason=(
                    "wrapper runtime observation is missing or invalid; "
                    f"run `{remediation}`"
                ),
            )
        if sequence_regressed:
            return _result(
                NONE,
                state="CLI_CHILD_UNKNOWN",
                reason=(
                    "same-turn wrapper runtime progress_sequence regressed; "
                    "refusing green or recovery authority"
                ),
            )
        wrapper_state = liveness.get("wrapper_state")
        wrapper_dead = wrapper_state == "dead"
        if wrapper_dead:
            if not hb_stale:
                return _result(
                    NONE,
                    state="WRAPPER_MISSING",
                    reason=(
                        "validated wrapper is absent, but its heartbeat is "
                        "still inside the stale threshold"
                    ),
                )
            child_recovery_state = "STUCK_OR_DEAD"
            child_recovery_reason = (
                "managed wrapper is absent from an available process snapshot"
            )
            nxt["healthy_since"] = None
        elif wrapper_state != "alive":
            return _result(
                NONE,
                state="CLI_CHILD_UNKNOWN",
                reason=(
                    "wrapper runtime could not be bound to the live managed wrapper "
                    f"({liveness.get('child_reason')}); run `{remediation}`"
                ),
            )

        updated_age = liveness.get("runtime_updated_age_seconds")
        updated_age_valid = bool(
            isinstance(updated_age, (int, float))
            and not isinstance(updated_age, bool)
            and math.isfinite(float(updated_age))
            and float(updated_age) >= 0
        )
        # The sequence is monotonic across turns. Only a timestamp written by a
        # real adapter event in this turn proves that handoff completed.
        handoff_complete = isinstance(
            runtime_record.get("last_progress_at"), str
        )
        child_in_grace = bool(
            not handoff_complete
            and (
                in_grace
                or (
                    updated_age_valid
                    and float(updated_age) <= _CLI_CHILD_SPAWN_GRACE_SECONDS
                )
            )
        )
        if wrapper_dead:
            # Positive wrapper-death evidence bypasses child classification and
            # enters the existing stale-wrapper recovery table below.
            pass
        elif runtime_phase == runtime_obs.PHASE_IDLE:
            if wrapper_state == "alive" and not hb_stale:
                return _healthy("HEALTHY_IDLE", "validated wrapper idle")
            # A validated idle record with a stale wrapper heartbeat uses the
            # existing wrapper recovery table below.
        elif runtime_phase == runtime_obs.PHASE_STARTING:
            if child_in_grace:
                return _result(
                    NONE,
                    state="CLI_CHILD_STARTING",
                    reason="CLI spawn is inside the bounded handoff grace",
                )
            return _result(
                NONE,
                state="CLI_CHILD_UNKNOWN",
                reason="CLI remained in starting phase beyond spawn grace",
            )
        elif runtime_phase == runtime_obs.PHASE_TERMINAL:
            outcome = runtime_record.get("last_outcome")
            if not hb_stale:
                if outcome in {
                    runtime_obs.OUTCOME_FAILED,
                    runtime_obs.OUTCOME_DEAD_LETTER,
                }:
                    return _result(
                        NONE,
                        state="TURN_FAILED",
                        reason=f"wrapper recorded terminal outcome {outcome}",
                    )
                progress_age = liveness.get("runtime_progress_age_seconds")
                progress_recent = bool(
                    isinstance(progress_age, (int, float))
                    and not isinstance(progress_age, bool)
                    and math.isfinite(float(progress_age))
                    and 0 <= float(progress_age) < stuck_after
                )
                if outcome == runtime_obs.OUTCOME_SUCCESS and progress_recent:
                    return _healthy(
                        "HEALTHY_WORKING",
                        "CLI turn completed and is finalizing its consume boundary",
                    )
                return _result(
                    NONE,
                    state="CLI_CHILD_UNKNOWN",
                    reason="terminal runtime tuple is stale or unclassified",
                )
            # A stale heartbeat is the wrapper recovery signal. Terminal state
            # describes the last turn; it must not suppress stale-wrapper recovery.
        elif runtime_phase == runtime_obs.PHASE_ACTIVE:
            child_state = liveness.get("child_state")
            if child_state == "unknown":
                return _result(
                    NONE,
                    state="CLI_CHILD_UNKNOWN",
                    reason=(
                        "active CLI brain is ambiguous "
                        f"({liveness.get('child_reason')}); refusing kill authority"
                    ),
                )
            if child_state == "dead":
                if child_in_grace:
                    return _result(
                        NONE,
                        state="CLI_CHILD_STARTING",
                        reason="CLI brain is absent inside spawn/handoff grace",
                    )
                prior_dead_polls = st.get("runtime_dead_polls")
                prior_dead_polls = (
                    prior_dead_polls
                    if isinstance(prior_dead_polls, int)
                    and not isinstance(prior_dead_polls, bool)
                    and prior_dead_polls >= 0
                    else 0
                )
                dead_polls = (prior_dead_polls + 1) if same_runtime_turn else 1
                nxt["runtime_dead_polls"] = dead_polls
                if dead_polls < _CLI_CHILD_CONFIRM_POLLS:
                    return _result(
                        NONE,
                        state="CLI_CHILD_MISSING",
                        reason="active CLI brain absent on first confirming poll",
                    )
                child_recovery_state = "CLI_CHILD_DEAD"
                child_recovery_reason = (
                    "active CLI brain absent on two confirming polls for the "
                    "same wrapper/turn generation"
                )
            elif child_state == "alive":
                progress_sequence = runtime_record.get("progress_sequence")
                progress_at = runtime_record.get("last_progress_at")
                if (
                    not isinstance(progress_sequence, int)
                    or isinstance(progress_sequence, bool)
                    or progress_sequence < 0
                ):
                    return _result(
                        NONE,
                        state="CLI_CHILD_UNKNOWN",
                        reason="live CLI brain has an invalid progress sequence",
                    )
                progress_observed = isinstance(progress_at, str)
                if not progress_observed and child_in_grace:
                    return _result(
                        NONE,
                        state="CLI_CHILD_STARTING",
                        reason="CLI brain is live but no real adapter progress arrived yet",
                    )
                progress_elapsed = max(0.0, now_epoch - float(progress_seen_epoch))
                if progress_elapsed < stuck_after:
                    if progress_observed:
                        return _healthy(
                            "HEALTHY_WORKING",
                            "live CLI brain with advancing adapter progress",
                        )
                    return _result(
                        NONE,
                        state="CLI_CHILD_NO_PROGRESS",
                        reason=(
                            "CLI brain is live but has not emitted a real adapter "
                            "progress event"
                        ),
                    )
                prior_stall_polls = st.get("runtime_stall_polls")
                prior_stall_polls = (
                    prior_stall_polls
                    if isinstance(prior_stall_polls, int)
                    and not isinstance(prior_stall_polls, bool)
                    and prior_stall_polls >= 0
                    else 0
                )
                same_sequence = (
                    same_runtime_turn
                    and isinstance(prior_sequence, int)
                    and not isinstance(prior_sequence, bool)
                    and progress_sequence == prior_sequence
                )
                stall_polls = (prior_stall_polls + 1) if same_sequence else 1
                nxt["runtime_stall_polls"] = stall_polls
                if stall_polls < _CLI_CHILD_CONFIRM_POLLS:
                    return _result(
                        NONE,
                        state="CLI_CHILD_STALL_SUSPECT",
                        reason="adapter progress is stale on first confirming poll",
                    )
                recovery_progress_cutoff = (
                    stuck_after
                    + runtime_obs.MAX_PROGRESS_WRITE_INTERVAL_SECONDS
                )
                if progress_elapsed < recovery_progress_cutoff:
                    return _result(
                        NONE,
                        state="CLI_CHILD_STALLED",
                        reason=(
                            "adapter progress is stale, but the durable "
                            "observation is still inside the bounded progress "
                            "coalescing allowance; refusing recovery"
                        ),
                    )
                heartbeat_authorizes = hb_stale and can_confirm_stuck
                watchdog_authorizes = False
                watchdog_reason: str | None = None
                if watchdog_live:
                    # Branch B owns the watchdog floor. Once F+C passes it is
                    # authoritative regardless of the low-threshold opt-in;
                    # that opt-in controls only the earlier heartbeat branch.
                    if progress_stall_floor is None:
                        watchdog_reason = (
                            progress_stall_floor_error
                            or "turn watchdog deadline is unresolved"
                        )
                    elif progress_elapsed >= (
                        max(stuck_after, progress_stall_floor)
                        + runtime_obs.MAX_PROGRESS_WRITE_INTERVAL_SECONDS
                    ):
                        watchdog_authorizes = True
                    elif stuck_after < progress_stall_floor:
                        watchdog_reason = (
                            "the opted-in low stale threshold has passed, but "
                            if allow_low_stuck_after
                            else f"stuck_after_seconds={stuck_after:.0f} is below "
                        ) + (
                            f"the hard watchdog floor {progress_stall_floor:.0f} "
                            "plus coalescing allowance"
                        )
                if not watchdog_authorizes and not heartbeat_authorizes:
                    if watchdog_reason is not None:
                        authority_reason = watchdog_reason
                    elif hb_stale:
                        authority_reason = (
                            "heartbeat is stale but its recovery guards are "
                            "not authoritative"
                        )
                    else:
                        authority_reason = (
                            "heartbeat is fresh and no per-turn watchdog is "
                            "effectively live"
                        )
                    return _result(
                        NONE,
                        state="CLI_CHILD_STALLED",
                        reason=(
                            f"adapter progress is stalled, but {authority_reason}; "
                            "refusing recovery"
                        ),
                    )
                child_recovery_state = "CLI_CHILD_STALLED"
                child_recovery_reason = (
                    "live CLI brain made no adapter progress past the hard "
                    "watchdog deadline plus margin and coalescing allowance"
                    if watchdog_authorizes
                    else (
                        "live CLI brain made no adapter progress past the "
                        "per-agent stale threshold plus coalescing allowance "
                        "and its heartbeat is stale"
                    )
                )
            else:
                return _result(
                    NONE,
                    state="CLI_CHILD_UNKNOWN",
                    reason="active runtime tuple did not resolve to a child state",
                )
        else:
            return _result(
                NONE,
                state="CLI_CHILD_UNKNOWN",
                reason="unmatched wrapped runtime tuple",
            )

    # 1) LAUNCHING: still in grace with readiness unresolved. Launcher death and
    # missing/incorrect brain discovery are irrelevant during startup.
    if in_grace and child_recovery_reason is None:
        return _result(NONE, state="LAUNCHING", discover_brain=not wrapped,
                       reason="in launch grace; awaiting first fresh heartbeat")

    # 2) STUCK_OR_DEAD: heartbeat stale past grace. With the activity hook on (or a
    # WRAPPED agent, instrumented by construction), stale means the agent is
    # neither waiting nor completing tools; restart. Without either signal, a long
    # working turn would not heartbeat, so keep the existing warn-only safety
    # behavior.
    if hb_stale or child_recovery_reason is not None:
        config_blocked_hold = (
            rpt.get("config_blocked_hold")
            if isinstance(rpt.get("config_blocked_hold"), dict) else None
        )
        if config_blocked_hold is not None:
            return _result(NONE, state="CONFIG_BLOCKED",
                           reason="durable config_blocked hold marker is present; "
                                  "HOLDING until operator repair or request-restart")
        # WP2: a managed lead-loop controller that exited DELIBERATELY leaves an EXIT
        # marker the planner honors instead of relaunching (the SYMMETRIC TWIN of the
        # manual-restart override above). A manual request-RESTART (section 0, above) is
        # checked first and OVERRIDES either HOLD; a CRASH writes NO marker, so a crashed
        # controller still relaunches (recovery).
        #   * `stood_down` (a VALID human release/end) -> HOLD UNCONDITIONALLY: relaunching
        #     would defeat the v0.39 stand-down under auto_restart (D-7). It sticks until an
        #     operator request-RESTART re-arms (which clears the marker on the confirmed
        #     relaunch).
        #   * `blocked` (acquire found another owner) -> HOLD ONLY WHILE THAT OWNER IS A
        #     LIVE GUARD (rpt['lead_loop'].armed). If the incumbent has since died / wedged
        #     past TTL / released (not armed), the block has CLEARED -> fall through to
        #     STUCK_RECOVER so this controller relaunches + takes over. (Without the
        #     liveness gate a stale `blocked` marker would PERMANENTLY HOLD - reachable
        #     under default config since wrapped stuck_after < lease TTL - defeating
        #     auto-recovery for a wedged/crashed lead-loop. lead verify P2.)
        ll_exit = rpt.get("lead_loop_exit")
        ll_state = ll_exit.get("state") if isinstance(ll_exit, dict) else None
        if ll_state == "stood_down":
            return _result(NONE, state="LEAD_LOOP_STOOD_DOWN",
                           reason="deliberate lead-loop stand-down (valid human release/"
                                  "end); NOT relaunching until an operator request-restart "
                                  "re-arms")
        if ll_state == "blocked":
            ll_view = rpt.get("lead_loop")
            if isinstance(ll_view, dict) and ll_view.get("armed"):
                return _result(NONE, state="LEAD_LOOP_BLOCKED",
                               reason="lead-loop acquire blocked: another LIVE owner holds "
                                      "the lease; HOLDING (no relaunch)")
            # incumbent owner is gone/dead/wedged -> block cleared -> fall through to recover
        if protected:
            nxt["last_warn_epoch"] = now_epoch
            return _result(
                WARN_ONLY,
                state=child_recovery_state or "STUCK_OR_DEAD",
                notify=True,
                reason=(
                    f"protected agent {child_recovery_reason} - recover manually"
                    if child_recovery_reason is not None
                    else "protected agent heartbeat stale - recover manually"
                ),
            )
        if child_recovery_reason is None and not can_confirm_stuck:
            if unsafe_low_codex:
                warn_reason = (
                    f"wrapped codex stuck_after_seconds={stuck_after:.0f} below the "
                    f"{_WRAPPED_CODEX_MIN_STUCK_AFTER:.0f}s floor - REFUSING "
                    "restart-on-stale (item-level stream would risk a false-kill "
                    "mid-reasoning); raise stuck_after_seconds or set "
                    "allow_low_stuck_after=true to opt in")
            elif watchdog_preempted:
                warn_reason = (
                    f"wrapped codex stuck_after_seconds={stuck_after:.0f} <= turn watchdog "
                    f"deadline {watchdog_turn_elapsed:.0f}s + {_WATCHDOG_STUCK_AFTER_MARGIN:.0f}s "
                    "margin - REFUSING restart-on-stale (it would relaunch into the same "
                    "wedge before the per-turn watchdog fires); raise stuck_after_seconds "
                    "above the deadline+margin or set allow_low_stuck_after=true to opt in")
            elif _work_hb_problem is not None:
                warn_reason = (
                    "heartbeat stale but wrapped Claude work-heartbeat ticker is not "
                    f"authoritative ({_work_hb_problem}); refusing stale recovery until "
                    "doctor/config repair")
            else:
                warn_reason = ("heartbeat stale but NO activity hook - cannot "
                               "confirm stuck; not killed")
            if now_epoch - last_warn >= suspect_interval:
                nxt["last_warn_epoch"] = now_epoch
                return _result(SUSPECT_WARN, state="ACTIVE_OR_BUSY",
                               notify=unsafe_low_codex, reason=warn_reason)
            return _result(NONE, state="ACTIVE_OR_BUSY",
                           reason="suspect (warn rate-limited)")
        # READINESS GIVE-UP CAP (0.31.2 / codex Fix A): a relaunch of an agent that
        # has NOT reached readiness since its last launch (launching + never a fresh
        # heartbeat) is a READINESS-failure relaunch - a resume that never re-enters
        # the listen loop just churns. Count them; after max_readiness_retries, STOP
        # relaunching and surface READINESS_GAVE_UP (no kill, manual intervention),
        # STICKY until a fresh heartbeat (resets the counter above) or an operator
        # restart/clear. A previously-READY agent that just went stale is a normal
        # stuck-recovery: its first relaunch starts the counter at 1; it resets the
        # moment readiness returns.
        never_ready = launching and not readiness_seen
        if now_epoch >= backoff_next:
            if never_ready and readiness_fails >= max_readiness_retries:
                give_up_reason = (
                    f"resume launch never reached first heartbeat after "
                    f"{readiness_fails} relaunch(es); STOPPING relaunch - manual "
                    f"intervention required (restart-request or operator clear). "
                    f"Consider a WRAPPED agent (the wrapper owns the heartbeat).")
                if now_epoch - last_warn >= suspect_interval:
                    nxt["last_warn_epoch"] = now_epoch
                    return _result(READINESS_GAVE_UP, state="READINESS_GAVE_UP",
                                   notify=True, reason=give_up_reason)
                return _result(NONE, state="READINESS_GAVE_UP",
                               reason="readiness gave up (warn rate-limited)")
            kt = _targets(include_launcher=True)
            barrier_state = _barrier_backoff_state()
            _relaunch_state()
            nxt["readiness_fails"] = (readiness_fails + 1) if never_ready else 1
            return _result(STUCK_RECOVER, state=child_recovery_state or "STUCK_OR_DEAD",
                           kill_first=bool(kt), kill_orphans=True,
                           kill_targets=kt,
                           reason=(
                               f"{child_recovery_reason}; best-effort kill + resume"
                               if child_recovery_reason is not None
                               else "heartbeat stale; best-effort kill + resume"
                           ),
                           barrier_state=barrier_state)
        return _result(
            BACKOFF_WAIT,
            state=child_recovery_state or "STUCK_OR_DEAD",
            reason=(
                f"{child_recovery_reason}; backing off until {backoff_next:.0f}"
                if child_recovery_reason is not None
                else f"heartbeat stale; backing off until {backoff_next:.0f}"
            ),
        )

    # 3) HEALTHY_IDLE: fresh heartbeat.
    return _healthy("HEALTHY_IDLE", "healthy")


def _store_cfg_from_report(report: dict) -> dict:
    roster = report.get("roster") if isinstance(report.get("roster"), list) else []
    agents = report.get("agents") if isinstance(report.get("agents"), dict) else {}
    roles = {
        a: entry.get("role")
        for a, entry in agents.items()
        if isinstance(entry, dict) and isinstance(entry.get("role"), str)
    }
    cfg = {"agents": [a for a in roster if isinstance(a, str)], "roles": roles}
    liaison = report.get("operator_facing")
    if isinstance(liaison, str):
        cfg["operator_facing"] = liaison
    return cfg


def _ephemeral_owned_process_view(
    snapshot: list[dict] | None,
    entry: dict,
    report_entry: dict,
    now_epoch: float,
    *,
    root_key: str | None,
) -> tuple[dict, dict, bool]:
    """Refresh one ephemeral wrapper through the strict wrapped authority path."""
    next_entry = copy.deepcopy(entry)
    try:
        agent = validate_agent_name(entry.get("agent"))
    except (TypeError, ValueError):
        next_entry["process_tree_hold_reason"] = "ephemeral_agent_identity_missing"
        return next_entry, {
            "kill_targets": [],
            "owned_process_tree": None,
            "owned_process_tree_refreshed": False,
            "child_reason": "ephemeral_agent_identity_missing",
        }, False
    cfg_agent = {
        "cli": (
            entry.get("cli")
            if isinstance(entry.get("cli"), str) and entry.get("cli")
            else "codex"
        ),
        "wrapped": True,
        # Carried WHOLESALE from the persisted entry (round 14, the
        # persistence half of the rebuild class) rather than re-listing
        # individual fields here - module_args_from is the immediate case,
        # but this way a future field of the profile's own launch config
        # survives this reconstruction too, without another site-by-site fix.
        "launch": entry.get("launch") if isinstance(entry.get("launch"), dict) else {},
    }
    liveness = _wrapped_liveness(
        snapshot,
        entry,
        cfg_agent,
        agent,
        now_epoch,
        (
            report_entry.get("wrapper_runtime")
            if isinstance(report_entry, dict)
            else None
        ),
        root_key=root_key,
    )
    next_entry["managed_pids"] = []
    runtime_record = liveness.get("runtime_record")
    if (
        liveness.get("runtime_status") == runtime_obs.STATUS_VALID
        and isinstance(runtime_record, dict)
        and isinstance(runtime_record.get("wrapper_generation"), str)
    ):
        next_entry["runtime_wrapper_generation"] = runtime_record[
            "wrapper_generation"
        ]
    tree = liveness.get("owned_process_tree")
    if isinstance(tree, dict):
        next_entry["owned_process_tree"] = copy.deepcopy(tree)
    legacy_process_evidence = liveness.get("legacy_process_evidence")
    if isinstance(legacy_process_evidence, dict):
        next_entry["legacy_process_evidence"] = copy.deepcopy(
            legacy_process_evidence
        )
    else:
        next_entry.pop("legacy_process_evidence", None)
    if liveness.get("owned_process_tree_pending") is True:
        next_entry["owned_process_tree_pending"] = True
    else:
        next_entry.pop("owned_process_tree_pending", None)
    complete = bool(
        isinstance(tree, dict)
        and tree.get("status") in {"complete", "absent"}
        and liveness.get("owned_process_tree_refreshed") is True
    )
    if complete:
        next_entry.pop("process_tree_hold_reason", None)
    else:
        next_entry["process_tree_hold_reason"] = (
            tree.get("reason_code")
            if isinstance(tree, dict)
            else liveness.get("child_reason")
        ) or "process_tree_authority_unavailable"
    return next_entry, liveness, complete


def _ephemeral_process_alive(snapshot: list[dict] | None, entry: dict) -> bool | None:
    if snapshot is None:
        return None
    return _pid_alive_guarded(_snap_index(snapshot), entry.get("launcher_pid"),
                              entry.get("launcher_start"))


def _ephemeral_next_without(state: dict, request_id: str) -> dict:
    copied = copy.deepcopy(state)
    eph.forget_active(copied, request_id)
    return copied.get("ephemeral_reviewers", {})


def _plan_launch_requests(report: dict, state: dict, config: dict,
                          *, now_epoch: float) -> dict[str, dict]:
    store_cfg = _store_cfg_from_report(report)
    out: dict[str, dict] = {}
    for marker in report.get("launch_requests") or []:
        if not isinstance(marker, dict):
            continue
        rid = marker.get("request_id")
        if not isinstance(rid, str):
            continue
        if marker.get("state", eph.STATE_QUEUED) != eph.STATE_QUEUED:
            out[rid] = {
                "request_id": rid,
                "action": eph.ACTION_NONE,
                "state": marker.get("state"),
                "reason": "request is already claimed or terminal",
            }
            continue
        errors, _profile = eph.validate_launch_request(marker, store_cfg, config)
        if not errors:
            errors = eph.capacity_errors(state, config, now_epoch)
        if errors:
            out[rid] = {
                "request_id": rid,
                "action": eph.ACTION_DENY,
                "state": eph.STATE_DENIED,
                "terminal_state": eph.STATE_DENIED,
                "reason": "; ".join(errors),
                "archive": True,
                "notify": True,
            }
            continue
        out[rid] = {
            "request_id": rid,
            "action": eph.ACTION_LAUNCH,
            "state": eph.STATE_QUEUED,
            "reason": "valid queued ephemeral review request",
            "profile": marker.get("profile"),
            "skill": marker.get("skill"),
            "requested_by": marker.get("requested_by"),
            "revision": (marker.get("scope") or {}).get("revision")
            if isinstance(marker.get("scope"), dict) else None,
        }
    return out


def _plan_ephemeral_active(report: dict, state: dict, config: dict,
                           *, now_epoch: float,
                           snapshot: list[dict] | None = None,
                           root_key: str | None = None) -> dict[str, dict]:
    del config  # reserved for future per-profile completion policy
    state_root = (state or {}).get("ephemeral_reviewers")
    state_active = state_root.get("active") if isinstance(state_root, dict) else {}
    state_active = state_active if isinstance(state_active, dict) else {}
    rpt_root = report.get("ephemeral_reviewers") if isinstance(report.get("ephemeral_reviewers"), dict) else {}
    rpt_active = rpt_root.get("active") if isinstance(rpt_root.get("active"), dict) else {}
    out: dict[str, dict] = {}
    for rid, entry in state_active.items():
        if not isinstance(entry, dict):
            continue
        rpt_entry = rpt_active.get(rid) if isinstance(rpt_active.get(rid), dict) else {}
        raw_completion = rpt_entry.get("completion")
        completion = (
            copy.deepcopy(raw_completion)
            if isinstance(raw_completion, dict) and raw_completion
            else {
                "status": eph.COMPLETION_NONE,
                "terminal": False,
                "hold": True,
                "reason": "no typed review-result",
            }
        )
        next_entry, liveness, teardown_ready = _ephemeral_owned_process_view(
            snapshot,
            entry,
            rpt_entry,
            now_epoch,
            root_key=root_key,
        )
        kill_targets = (
            copy.deepcopy(liveness.get("kill_targets") or [])
            if teardown_ready
            else []
        )
        terminal_action = None
        terminal_state = None
        terminal_reason = None
        if completion.get("terminal") is True:
            terminal_action = eph.ACTION_COMPLETE
            terminal_state = eph.STATE_COMPLETED
            terminal_reason = (
                f"typed review-result status={completion.get('status')}"
            )
        deadline = entry.get("deadline_epoch")
        if (
            terminal_action is None
            and isinstance(deadline, (int, float))
            and now_epoch >= float(deadline)
        ):
            terminal_action = eph.ACTION_TIMEOUT
            terminal_state = eph.STATE_TIMED_OUT
            terminal_reason = (
                "ephemeral reviewer timed out without a typed terminal "
                "review-result"
            )
        alive = _ephemeral_process_alive(snapshot, entry)
        if (
            terminal_action is None
            and entry.get("phase") == eph.STATE_LAUNCHED
            and alive is False
        ):
            terminal_action = eph.ACTION_FAILED
            terminal_state = eph.STATE_FAILED
            terminal_reason = (
                "ephemeral reviewer process exited without typed terminal "
                "review-result; no auto-restart"
            )
        persisted_terminal = eph.validate_held_terminal(
            entry.get("held_terminal")
        )
        if persisted_terminal is not None:
            # The first terminal observation is the attended disposition. A
            # later report cannot rewrite a timeout/failure after it has been
            # persisted and surfaced to the operator.
            terminal_state = persisted_terminal["terminal_state"]
            terminal_reason = persisted_terminal["reason"]
            completion = copy.deepcopy(persisted_terminal["completion"])
            terminal_action = {
                eph.STATE_COMPLETED: eph.ACTION_COMPLETE,
                eph.STATE_TIMED_OUT: eph.ACTION_TIMEOUT,
                eph.STATE_FAILED: eph.ACTION_FAILED,
                eph.STATE_DENIED: eph.ACTION_DENY,
            }[terminal_state]
        if terminal_action is not None:
            # Persist the terminal facts before either the initial HOLD or the
            # executor's post-kill launch barrier can make teardown sticky.
            # The attended request-bound archive must never reconstruct them
            # from a later, potentially different report.
            next_entry["held_terminal"] = eph.make_held_terminal(
                terminal_state,
                terminal_reason,
                completion,
            )
        if terminal_action is not None and not teardown_ready:
            hold_reason = next_entry.get("process_tree_hold_reason")
            out[rid] = {
                "request_id": rid,
                "agent": entry.get("agent"),
                "action": eph.ACTION_NONE,
                "state": "process_tree_hold",
                "reason": (
                    f"{terminal_reason}; HOLDING archive and teardown until "
                    "the owned process tree is freshly and completely "
                    f"revalidated ({hold_reason})"
                ),
                "completion": completion,
                "kill_first": False,
                "kill_targets": [],
                "retire": False,
                "archive": False,
                "auto_restart": False,
                "next_entry": next_entry,
            }
            continue
        if terminal_action is not None:
            out[rid] = {
                "request_id": rid,
                "agent": entry.get("agent"),
                "action": terminal_action,
                "state": terminal_state,
                "terminal_state": terminal_state,
                "reason": terminal_reason,
                "completion": completion,
                "kill_first": bool(kill_targets),
                "kill_targets": kill_targets,
                "retire": True,
                "archive": True,
                "next_state": _ephemeral_next_without(state, rid),
                "next_entry": next_entry,
            }
            continue
        out[rid] = {
            "request_id": rid,
            "agent": entry.get("agent"),
            "action": eph.ACTION_NONE,
            "state": entry.get("phase", eph.STATE_REQUESTED),
            "reason": completion.get("reason") or "awaiting typed review-result",
            "completion": completion,
            "auto_restart": False,
            "next_entry": next_entry,
        }
    for agent in rpt_root.get("orphan_agents") or []:
        if isinstance(agent, str):
            out[f"janitor:{agent}"] = {
                "request_id": None,
                "agent": agent,
                "action": eph.ACTION_JANITOR,
                "state": "orphan",
                "reason": "stale adversary identity has no active launch request",
                "retire": True,
                "archive": False,
            }
    return out


def plan_actions(report: dict, state: dict, config: dict,
                 *, now_epoch: float, snapshot: list[dict] | None = None) -> dict:
    """The SHARED decision table. Returns ``{"now_epoch", "agents": {name: plan}}``
    where each plan has ``action``/``state`` plus ``kill_first``/``kill_orphans``/
    ``kill_targets``/``discover_brain``/``resume_mode``/``next_state`` for the
    executor. Only agents present in BOTH the config and the report are planned
    (config drives what is supervised; the report supplies bus facts).

    ``snapshot`` is the executor's process snapshot (list of rows) interpreted
    per agent by :func:`_liveness`. Manual agents use it for best-effort restart
    targets. Wrapped agents use it to re-prove ownership and project a bounded,
    strict process tree into ``next_state`` for the next poll."""
    cfg_agents = config.get("agents") if isinstance(config.get("agents"), dict) else {}
    rpt_agents = report.get("agents") or {}
    state_agents = state.get("agents") if isinstance(state.get("agents"), dict) else {}
    root_key = report.get("root_key")
    if not isinstance(root_key, str):
        root_key = _root_key(config.get("root") or config.get("root_key") or "")
    out: dict[str, dict] = {}
    for name, cfg_agent in cfg_agents.items():
        if not isinstance(cfg_agent, dict) or not cfg_agent.get("auto_restart", False):
            continue
        rpt = rpt_agents.get(name)
        if not isinstance(rpt, dict):
            continue
        st = state_agents.get(name) if isinstance(state_agents.get(name), dict) else {}
        liveness = _liveness(snapshot, st, cfg_agent, name, now_epoch,
                             root_key=root_key, request_id=None,
                             runtime_view=rpt.get("wrapper_runtime"))
        out[name] = _plan_one(name, rpt, st, config, cfg_agent, liveness,
                              now_epoch=now_epoch)
    return {
        "now_epoch": now_epoch,
        "agents": out,
        "launch_requests": _plan_launch_requests(report, state, config,
                                                 now_epoch=now_epoch),
        "ephemeral_reviewers": _plan_ephemeral_active(
            report, state, config, now_epoch=now_epoch, snapshot=snapshot,
            root_key=root_key),
    }


def process_tree_ownership_reset_evidence(
    state: dict,
    agent: str,
    *,
    request_id: str | None = None,
    expected_root: str | Path,
    verified_launch_nonce: str,
    runtime_record: dict,
    now_epoch: float | None = None,
) -> dict:
    """Return the exact identities an attended ownership reset must verify.

    This is deliberately stricter than the ordinary HOLD projection.  Reset is
    available only when the persisted tree, supervisor state, and the wrapper's
    strict runtime record agree on one wrapper identity, generation, and launch
    nonce.  A damaged record remains visible for manual repair; it never becomes
    reset authority merely because a human supplied a plausible pid or name.
    """
    agent = validate_agent_name(agent)
    if request_id is None:
        agents = state.get("agents") if isinstance(state, dict) else None
        entry = agents.get(agent) if isinstance(agents, dict) else None
        if not isinstance(entry, dict):
            raise ValueError(
                f"no configured supervisor state exists for {agent!r}"
            )
    else:
        if not eph.is_safe_id(request_id):
            raise ValueError("ephemeral request id must be a safe path token")
        eph_root = (
            state.get("ephemeral_reviewers")
            if isinstance(state, dict)
            else None
        )
        active = eph_root.get("active") if isinstance(eph_root, dict) else None
        entry = active.get(request_id) if isinstance(active, dict) else None
        if (
            not isinstance(entry, dict)
            or entry.get("request_id") != request_id
            or entry.get("agent") != agent
        ):
            raise ValueError(
                "no exact active ephemeral process-tree state exists for "
                f"request {request_id!r} and agent {agent!r}"
            )

    raw_tree = entry.get("owned_process_tree")
    if not isinstance(raw_tree, dict) or raw_tree.get("status") not in {
        "invalid",
        "truncated",
    }:
        raise ValueError(f"{agent!r} has no strict process-tree HOLD to reset")
    launch_nonce = raw_tree.get("launch_nonce")
    wrapper_generation = raw_tree.get("wrapper_generation")
    expected_root_key = _root_key(str(Path(expected_root).resolve()))
    if (
        expected_root_key is None
        or not _valid_launch_nonce(verified_launch_nonce)
        or launch_nonce != verified_launch_nonce
        or entry.get("launcher_nonce") != verified_launch_nonce
        or not _valid_wrapper_generation(wrapper_generation)
        or entry.get("runtime_wrapper_generation") != wrapper_generation
    ):
        raise ValueError(
            "process-tree HOLD does not agree on a valid root, generation, "
            "and verified launch nonce"
        )
    tree = _valid_owned_process_tree(
        raw_tree,
        agent=agent,
        root_key=expected_root_key,
        wrapper_generation=wrapper_generation,
        launch_nonce=verified_launch_nonce,
    )
    if tree is None or tree.get("status") not in {"invalid", "truncated"}:
        raise ValueError("process-tree HOLD record is malformed or belongs to another root")

    try:
        runtime = runtime_obs.validate_record(
            runtime_record,
            expected_agent=agent,
            now_epoch=now_epoch,
        )
    except runtime_obs.RuntimeRecordError as exc:
        raise ValueError(f"strict wrapper runtime record is invalid: {exc}") from exc
    wrapper_pid = runtime.get("wrapper_pid")
    wrapper_start = runtime.get("wrapper_start")
    if (
        runtime.get("wrapper_generation") != wrapper_generation
        or not isinstance(wrapper_pid, int)
        or isinstance(wrapper_pid, bool)
        or wrapper_pid <= 0
        or not isinstance(wrapper_start, str)
        or not wrapper_start
        or entry.get("launcher_pid") != wrapper_pid
        or not _start_tokens_match(entry.get("launcher_start"), wrapper_start)
    ):
        raise ValueError(
            "supervisor state and strict wrapper runtime record do not agree "
            "on wrapper pid/start/generation"
        )

    identities: list[dict] = []
    for row in tree.get("entries", []):
        identities.append({
            "pid": row["pid"],
            "start": row["start"],
            "start_filetime": row.get("start_filetime"),
            "source": "owned_process_tree",
            "role": row["role"],
        })
    legacy = _valid_legacy_process_migration_evidence(
        entry.get("legacy_process_evidence")
    )
    if entry.get("legacy_process_evidence") is not None and legacy is None:
        raise ValueError("legacy process migration evidence is malformed")
    if legacy is not None:
        for row in legacy["entries"]:
            identities.append({
                "pid": row["pid"],
                "start": row["start"],
                "source": "legacy_process_evidence",
                "role": row["source"],
            })

    runtime_launcher_pid = runtime.get("cli_launcher_pid")
    runtime_launcher_start = runtime.get("cli_launcher_start")
    if (runtime_launcher_pid is None) != (runtime_launcher_start is None):
        raise ValueError("strict runtime launcher pid/start evidence is incomplete")
    if runtime_launcher_pid is not None:
        identities.append({
            "pid": runtime_launcher_pid,
            "start": runtime_launcher_start,
            "source": "wrapper_runtime",
            "role": "cli_launcher",
        })

    brain_pid = entry.get("brain_pid")
    brain_start = entry.get("brain_start")
    if (brain_pid is None) != (brain_start is None):
        raise ValueError("supervisor brain pid/start evidence is incomplete")
    if brain_pid is not None:
        if (
            not isinstance(brain_pid, int)
            or isinstance(brain_pid, bool)
            or brain_pid <= 0
            or not isinstance(brain_start, str)
            or not brain_start
            or len(brain_start) > 256
            or any(ord(char) < 32 for char in brain_start)
        ):
            raise ValueError("supervisor brain pid/start evidence is malformed")
        identities.append({
            "pid": brain_pid,
            "start": brain_start,
            "source": "supervisor_state",
            "role": "cli_brain",
        })

    managed = entry.get("managed_pids", [])
    if not isinstance(managed, list) or len(managed) > _OWNED_PROCESS_TREE_LIMIT:
        raise ValueError("supervisor managed pid evidence is malformed or unbounded")
    for row in managed:
        pid = row.get("pid") if isinstance(row, dict) else None
        start = row.get("start") if isinstance(row, dict) else None
        if (
            not isinstance(pid, int)
            or isinstance(pid, bool)
            or pid <= 0
            or not isinstance(start, str)
            or not start
            or len(start) > 256
            or any(ord(char) < 32 for char in start)
        ):
            raise ValueError("supervisor managed pid evidence contains a malformed row")
        identities.append({
            "pid": pid,
            "start": start,
            "source": "supervisor_state",
            "role": "managed_pid",
        })

    wrapper_rows = [
        row
        for row in identities
        if row["pid"] == wrapper_pid
        and _start_tokens_match(row["start"], wrapper_start)
        and row["role"] == "wrapper"
    ]
    if not wrapper_rows:
        raise ValueError(
            "process-tree evidence does not contain the strict runtime wrapper identity"
        )

    if any(_start_order_key(row.get("start")) is None for row in identities):
        raise ValueError(
            "process-tree reset evidence contains an unparseable pid/start identity"
        )

    deduped: list[dict] = []
    seen: set[tuple[int, str]] = set()
    for row in identities:
        key = (row["pid"], row["start"])
        if key in seen:
            continue
        seen.add(key)
        deduped.append(row)
    return {
        "agent": agent,
        "root_key": expected_root_key,
        "wrapper_generation": wrapper_generation,
        "launch_nonce": verified_launch_nonce,
        "wrapper_pid": wrapper_pid,
        "wrapper_start": wrapper_start,
        "runtime_record_digest": _wrapper_runtime_record_digest(runtime),
        "identities": deduped,
    }


def _validated_process_tree_reset_audit(state: dict) -> list[dict]:
    audit = state.get("process_tree_resets")
    if audit is None:
        return []
    if (
        not isinstance(audit, list)
        or len(audit) > 64
        or any(
            not isinstance(record, dict)
            or frozenset(record) != {
                "schema_version",
                "agent",
                "hold_source_hash",
                "acknowledged_by",
                "verified_launch_nonce",
                "verified_identity_count",
                "acknowledged_at",
                "reason",
                "previous",
            }
            or record.get("schema_version") != 1
            or not isinstance(record.get("agent"), str)
            or not isinstance(record.get("acknowledged_by"), str)
            or not isinstance(record.get("hold_source_hash"), str)
            or re.fullmatch(r"[0-9a-f]{64}", record["hold_source_hash"]) is None
            or not _valid_launch_nonce(record.get("verified_launch_nonce"))
            or not isinstance(record.get("verified_identity_count"), int)
            or isinstance(record.get("verified_identity_count"), bool)
            or record["verified_identity_count"] < 1
            or _utc_epoch(record.get("acknowledged_at")) is None
            or not isinstance(record.get("reason"), str)
            or not record["reason"]
            or not isinstance(record.get("previous"), dict)
            for record in audit
        )
    ):
        raise ValueError("process-tree reset audit history is malformed")
    return list(audit)


def reset_process_tree_ownership_after_attended_teardown(
    state: dict,
    agent: str,
    *,
    hold_source_hash: str,
    acknowledged_by: str,
    verified_launch_nonce: str,
    expected_root: str | Path,
    runtime_record: dict,
    recorded_identities_gone: bool,
    reason: str,
    now_epoch: float | None = None,
) -> dict:
    """Record an attended teardown boundary and revoke stale ownership state.

    This operation never kills or launches a process. The CLI authorizes it only
    while the supervisor kill switch is present, the singleton marker is absent,
    and ``hold_source_hash`` still names the visible process-tree Attention item.
    The next launch must create a new wrapper generation and earn a fresh tree.
    """
    agent = validate_agent_name(agent)
    acknowledged_by = validate_agent_name(acknowledged_by)
    if (
        not isinstance(hold_source_hash, str)
        or re.fullmatch(r"[0-9a-f]{64}", hold_source_hash) is None
    ):
        raise ValueError("hold source hash must be 64 lowercase hexadecimal characters")
    cleaned_reason = reason.strip() if isinstance(reason, str) else ""
    if (
        not cleaned_reason
        or len(cleaned_reason) > 500
        or any(ord(char) < 32 for char in cleaned_reason)
    ):
        raise ValueError("reason must be a non-empty single line of at most 500 characters")
    if recorded_identities_gone is not True:
        raise ValueError("every recorded pid/start identity must be gone or recycled")
    evidence = process_tree_ownership_reset_evidence(
        state,
        agent,
        expected_root=expected_root,
        verified_launch_nonce=verified_launch_nonce,
        runtime_record=runtime_record,
        now_epoch=now_epoch,
    )
    audit = _validated_process_tree_reset_audit(state)
    agents = state["agents"]
    entry = agents[agent]
    raw_tree = entry.get("owned_process_tree")
    tree_status = raw_tree.get("status") if isinstance(raw_tree, dict) else None
    legacy = _valid_legacy_process_migration_evidence(
        entry.get("legacy_process_evidence")
    )
    if tree_status not in {"invalid", "truncated"} and legacy is None:
        raise ValueError(f"{agent!r} has no process-tree HOLD to reset")

    previous = {
        "tree_status": tree_status,
        "tree_reason_code": (
            raw_tree.get("reason_code")
            if isinstance(raw_tree, dict)
            else None
        ),
        "wrapper_generation": (
            raw_tree.get("wrapper_generation")
            if isinstance(raw_tree, dict)
            else entry.get("runtime_wrapper_generation")
        ),
        "launch_nonce": (
            raw_tree.get("launch_nonce")
            if isinstance(raw_tree, dict)
            else entry.get("launcher_nonce")
        ),
        "legacy_source_hash": (
            legacy.get("source_hash")
            if isinstance(legacy, dict)
            else None
        ),
    }

    reset_epoch = (
        float(now_epoch)
        if now_epoch is not None
        else datetime.now(timezone.utc).timestamp()
    )
    revoked_at = _event_now(reset_epoch)

    for key in (
        "launcher_pid",
        "launcher_start",
        "launcher_nonce",
        "launcher_nonce_injected",
        "launcher_nonce_source",
        "launcher_nonce_missing_reason",
        "brain_pid",
        "brain_start",
        "owned_process_tree",
        "legacy_process_evidence",
        "process_tree_hold_reason",
        "runtime_wrapper_generation",
        "runtime_turn_generation",
        "runtime_phase",
        "runtime_progress_sequence",
        "runtime_progress_seen_epoch",
        "runtime_sequence_regressed",
        "runtime_dead_polls",
        "runtime_stall_polls",
        "pid",
        "pid_alive",
    ):
        entry.pop(key, None)
    entry.update({
        "managed_pids": [],
        "owned_process_tree_pending": True,
        "launching": False,
        "launch_grace_until": 0.0,
        "readiness_seen": False,
        "launched": False,
        "healthy_since": None,
        "revoked_wrapper_runtime": {
            "schema_version": _REVOKED_WRAPPER_RUNTIME_SCHEMA,
            "agent": agent,
            "root_key": evidence["root_key"],
            "wrapper_pid": evidence["wrapper_pid"],
            "wrapper_start": evidence["wrapper_start"],
            "wrapper_generation": evidence["wrapper_generation"],
            "launch_nonce": evidence["launch_nonce"],
            "runtime_record_digest": evidence["runtime_record_digest"],
            "hold_source_hash": hold_source_hash,
            "revoked_at": revoked_at,
        },
    })

    audit.append({
        "schema_version": 1,
        "agent": agent,
        "hold_source_hash": hold_source_hash,
        "acknowledged_by": acknowledged_by,
        "verified_launch_nonce": evidence["launch_nonce"],
        "verified_identity_count": len(evidence["identities"]),
        "acknowledged_at": revoked_at,
        "reason": cleaned_reason,
        "previous": previous,
    })
    state["process_tree_resets"] = audit[-64:]
    return state


def record_launch(state: dict, agent: str, *, cli: str, pid: int | None,
                  pid_start: str | None = None, now_epoch: float | None = None,
                  grace_seconds: float | None = None,
                  session_id: str | None = None,
                  pre_snapshot: list[dict] | None = None,
                  post_snapshot: list[dict] | None = None,
                  cfg_agent: dict | None = None,
                  root_key: str | None = None,
                  launcher_nonce: str | None = None,
                  launcher_nonce_injected: bool = False,
                  launcher_nonce_source: str | None = None,
                  launcher_nonce_missing_reason: str | None = None) -> dict:
    """Apply a launch-SUCCESS to ``state`` IN PLACE - the rule the generated
    script defers to Python (testable, not PS-internal). ``pid`` is the
    LAUNCHER pid from Start-Process (the short-lived bootstrap for a forking CLI;
    the long-lived ``brain_pid`` is DISCOVERED later by the planner from the
    snapshot). Records the launcher + start-time (anti-reuse), opens a fresh
    launch GRACE, resets readiness, and clears the stale brain so it is
    re-discovered. ``resume_available`` is sticky (a prior session still exists).
    Claude pins its minted ``session_id`` (codex resumes by ``--last``)."""
    agents = state.setdefault("agents", {})
    if not isinstance(agents, dict):
        agents = state["agents"] = {}
    entry = agents.get(agent)
    if not isinstance(entry, dict):
        entry = agents[agent] = {}
    entry["launcher_pid"] = pid
    entry["launcher_start"] = pid_start
    if launcher_nonce_injected and _valid_launch_nonce(launcher_nonce):
        entry["launcher_nonce"] = launcher_nonce
        entry["launcher_nonce_injected"] = True
        entry["launcher_nonce_source"] = launcher_nonce_source or "agenttalk_global_arg"
        entry.pop("launcher_nonce_missing_reason", None)
    else:
        entry.pop("launcher_nonce", None)
        entry.pop("launcher_nonce_source", None)
        entry["launcher_nonce_injected"] = False
        if launcher_nonce_missing_reason:
            entry["launcher_nonce_missing_reason"] = launcher_nonce_missing_reason
        else:
            entry.pop("launcher_nonce_missing_reason", None)
    entry["launching"] = True
    entry["readiness_seen"] = False
    entry["brain_pid"] = None
    entry["brain_start"] = None
    now = now_epoch if now_epoch is not None else datetime.now(timezone.utc).timestamp()
    lcfg = {"cli": cli}
    if isinstance(cfg_agent, dict):
        lcfg.update(cfg_agent)
    if bool(lcfg.get("wrapped", False)):
        # Wrapped ownership is derived only from the bounded strict poll tree.
        # Do not even build the legacy unbounded launch-delta channel.
        launch_children, diagnostics = [], _diag()
    else:
        launch_children, diagnostics = capture_launch_child_provenance(
            pre_snapshot,
            post_snapshot,
            launcher_pid=pid,
            launcher_start=pid_start,
            launcher_nonce=entry.get("launcher_nonce"),
            launcher_nonce_injected=entry.get("launcher_nonce_injected") is True,
            cfg_agent=lcfg,
            agent=agent,
            root_key=root_key,
            request_id=None,
            now_epoch=now,
        )
    entry["managed_pids"] = launch_children
    # A successful launch starts a new ownership generation. The next strict
    # runtime + snapshot poll must earn a fresh tree before any teardown.
    entry.pop("owned_process_tree", None)
    entry.pop("legacy_process_evidence", None)
    entry["owned_process_tree_pending"] = True
    entry["provenance_diagnostics"] = {k: v for k, v in diagnostics.items() if v}
    entry["last_launch_epoch"] = now
    if grace_seconds is not None:
        entry["launch_grace_until"] = now + float(grace_seconds)
    # legacy back-compat (non-forking pid_alive path + old tests)
    entry["pid"] = pid
    entry["pid_alive"] = True
    entry["launched"] = True
    if cli == "codex":
        entry["session_id"] = None        # never persist a fake id for codex
    elif session_id:
        entry["session_id"] = session_id  # claude: pin the minted/known id
    return state


def prepare_launch_request(store: Store, state: dict, config: dict, request_id: str,
                           *, now_epoch: float, claimed_by: str = "supervisor") -> dict:
    """Claim and prepare one queued ephemeral launch request.

    Side effects are deliberately before process launch and are request-id
    checked: claim marker, roster temporary identity, send the review-request,
    persist active supervisor state, and return a fully substituted launch spec.
    """
    marker0 = store.read_launch_request(request_id)
    if marker0 is None:
        raise eph.EphemeralError(f"launch request {request_id!r} is absent")
    errors, profile = eph.validate_launch_request(marker0, store.load_config(), config)
    if not errors:
        errors = eph.capacity_errors(state, config, now_epoch)
    if errors:
        raise eph.EphemeralError("; ".join(errors))
    marker = store.claim_launch_request(request_id, claimed_by=claimed_by,
                                        at_epoch=now_epoch)
    if marker is None:
        raise eph.EphemeralError(f"launch request {request_id!r} is already claimed")
    # Revalidate after the claim: the marker is untrusted writable state.
    errors, profile = eph.validate_launch_request(marker, store.load_config(), config)
    if errors or profile is None:
        store.archive_launch_request(
            request_id,
            eph.terminal_archive(marker, terminal_state=eph.STATE_DENIED,
                                 reason="; ".join(errors or ["profile is not allowed"]),
                                 at_epoch=now_epoch),
        )
        raise eph.EphemeralError("; ".join(errors or ["profile is not allowed"]))
    lane_id = marker.get("lane_id") or ((marker.get("scope") or {}).get("lane_id")
                                        if isinstance(marker.get("scope"), dict) else None)
    workspace_path = None
    if lane_id:
        try:
            lane_id = lane_mod.validate_lane_id(str(lane_id))
            lanes_data = lane_mod.load_lanes(store)
            lane = (lanes_data.get("lanes") or {}).get(lane_id)
            if not isinstance(lane, dict):
                raise lane_mod.LaneError(f"lane {lane_id!r} has no active provisioned worktree")
            if lane.get("status") != lane_mod.STATUS_ACTIVE:
                raise lane_mod.LaneError(f"lane {lane_id!r} is not active for launch")
            if not lane.get("worktree_path"):
                raise lane_mod.LaneError(f"lane {lane_id!r} has no provisioned worktree for launch")
            workspace_path = str(Path(lane["worktree_path"]))
            marker["lane_id"] = lane_id
            marker["workspace_path"] = workspace_path
            marker.setdefault("scope", {})["lane_id"] = lane_id
        except lane_mod.LaneError as e:
            store.archive_launch_request(
                request_id,
                eph.terminal_archive(marker, terminal_state=eph.STATE_DENIED,
                                     reason=f"invalid lane launch: {e}",
                                     at_epoch=now_epoch),
            )
            raise eph.EphemeralError(f"invalid lane launch: {e}") from e
    cfg = store.load_config()
    agent = eph.choose_agent_name(request_id, cfg.get("agents", []) or [],
                                  store.retired_agents())
    role = eph.effective_role(marker, profile)
    groups = eph.effective_groups(marker, profile)
    timeout = int(marker.get("timeout_seconds")
                  or eph.config_block(config)["default_timeout_seconds"])
    marker["timeout_seconds"] = timeout
    store.add_agent(agent, role=role, groups=groups)
    try:
        body = eph.review_request_body(marker, agent)
        msg = store.send(
            sender=marker["requested_by"],
            recipient=agent,
            kind="review-request",
            subject=f"ephemeral review {request_id}",
            body=body,
            meta={
                "request_id": request_id,
                "ephemeral_request_id": request_id,
                "evidence_only": "true",
                "counted_signoff": "false",
                "profile": str(marker.get("profile", "")),
                "skill": str(marker.get("skill", "")),
                "revision": str((marker.get("scope") or {}).get("revision", "")),
            },
        )
    except Exception as send_error:
        extra = {"agent": agent}
        try:
            store.retire_agent(agent, reason=f"ephemeral launch {request_id} failed before request send")
        except ValueError as cleanup_error:
            extra["cleanup_error"] = str(cleanup_error)
        store.archive_launch_request(
            request_id,
            eph.terminal_archive(
                marker,
                terminal_state=eph.STATE_FAILED,
                reason=f"failed before review request send: {send_error}",
                at_epoch=now_epoch,
                extra=extra,
            ),
        )
        raise
    store.update_launch_request(request_id, {
        "state": eph.STATE_REQUESTED,
        "agent": agent,
        "review_request_msg_id": msg.id,
        "requested_at": eph.utc_now(),
        "requested_at_epoch": now_epoch,
        "lane_id": lane_id,
        "workspace_path": workspace_path,
    })
    eph.record_prepared(
        state,
        request_id=request_id,
        agent=agent,
        requested_by=marker["requested_by"],
        profile=str(marker.get("profile", "")),
        timeout_seconds=timeout,
        now_epoch=now_epoch,
        review_request_id=msg.id,
        cli=(
            profile.get("cli")
            if isinstance(profile.get("cli"), str)
            else "codex"
        ),
        launch=(
            profile.get("launch")
            if isinstance(profile.get("launch"), dict)
            else None
        ),
    )
    spec = eph.launch_spec(marker, profile, agent)
    if workspace_path:
        spec["lane_id"] = lane_id
        spec["workspace_path"] = workspace_path
        spec["cwd"] = workspace_path
        if spec.get("cli") == "codex":
            launch = spec.setdefault("launch", {})
            args = list(launch.get("windows_args") or [])
            if not any(args[i] == "--add-dir" and i + 1 < len(args)
                       and str(args[i + 1]) == workspace_path for i in range(len(args))):
                args = ["--add-dir", workspace_path, *args]
            launch["windows_args"] = args
    window_style, warning = resolve_window_style(config, profile)
    spec["window_style"] = window_style
    spec["window_style_warning"] = warning
    spec["review_request_msg_id"] = msg.id
    return spec


def record_ephemeral_launch(state: dict, request_id: str, *, pid: int | None,
                            pid_start: str | None = None,
                            now_epoch: float | None = None,
                            timeout_seconds: int | None = None,
                            pre_snapshot: list[dict] | None = None,
                            post_snapshot: list[dict] | None = None,
                            cfg_agent: dict | None = None,
                            root_key: str | None = None,
                            launcher_nonce: str | None = None,
                            launcher_nonce_injected: bool = False,
                            launcher_nonce_source: str | None = None,
                            launcher_nonce_missing_reason: str | None = None) -> dict:
    """Apply an ephemeral wrapper launch success to supervisor state."""
    del pre_snapshot, post_snapshot, cfg_agent, root_key
    now = now_epoch if now_epoch is not None else datetime.now(timezone.utc).timestamp()
    result = eph.record_launched(
        state,
        request_id=request_id,
        pid=pid,
        pid_start=pid_start,
        now_epoch=now,
        timeout_seconds=timeout_seconds,
    )
    root = eph.ensure_state(result)
    entry = root["active"].get(request_id)
    if isinstance(entry, dict):
        if launcher_nonce_injected and _valid_launch_nonce(launcher_nonce):
            entry["launcher_nonce"] = launcher_nonce
            entry["launcher_nonce_injected"] = True
            entry["launcher_nonce_source"] = launcher_nonce_source or "agenttalk_global_arg"
            entry.pop("launcher_nonce_missing_reason", None)
        else:
            entry.pop("launcher_nonce", None)
            entry.pop("launcher_nonce_source", None)
            entry["launcher_nonce_injected"] = False
            if launcher_nonce_missing_reason:
                entry["launcher_nonce_missing_reason"] = launcher_nonce_missing_reason
            else:
                entry.pop("launcher_nonce_missing_reason", None)
        # Ephemeral wrappers use the same bounded, runtime-bound process tree as
        # configured wrappers. Launch deltas and command-line/name matches are
        # never teardown authority.
        entry["managed_pids"] = []
        entry.pop("owned_process_tree", None)
        entry.pop("legacy_process_evidence", None)
        entry["owned_process_tree_pending"] = True
        entry.pop("runtime_wrapper_generation", None)
        entry.pop("process_tree_hold_reason", None)
        entry["provenance_diagnostics"] = {}
        entry["last_launch_epoch"] = now
    return result


_ATTENDED_EPHEMERAL_ARCHIVE_MODES = frozenset({
    "strict_identity",
    "operator_attested",
})
_ATTENDED_EPHEMERAL_ARCHIVE_PENDING_FIELDS = frozenset({
    "schema_version",
    "request_id",
    "agent",
    "hold_source_hash",
    "acknowledged_by",
    "verification_mode",
    "verified_launch_nonce",
    "verified_identity_count",
    "acknowledged_at",
    "acknowledged_at_epoch",
    "reason",
    "terminal",
    "archive_payload",
})


def _validate_attended_ephemeral_archive_pending(
    value: object,
) -> dict:
    """Validate one durable attended-archive journal without trusting extras."""
    if (
        not isinstance(value, dict)
        or frozenset(value) != _ATTENDED_EPHEMERAL_ARCHIVE_PENDING_FIELDS
        or value.get("schema_version") != 1
    ):
        raise ValueError("attended ephemeral archive journal is malformed")
    request_id = value.get("request_id")
    if not eph.is_safe_id(request_id):
        raise ValueError("attended ephemeral archive request id is invalid")
    agent = validate_agent_name(value.get("agent"))
    actor = validate_agent_name(value.get("acknowledged_by"))
    hold_source_hash = value.get("hold_source_hash")
    if (
        not isinstance(hold_source_hash, str)
        or re.fullmatch(r"[0-9a-f]{64}", hold_source_hash) is None
    ):
        raise ValueError("attended ephemeral archive source hash is invalid")
    mode = value.get("verification_mode")
    nonce = value.get("verified_launch_nonce")
    identity_count = value.get("verified_identity_count")
    if (
        mode not in _ATTENDED_EPHEMERAL_ARCHIVE_MODES
        or not isinstance(identity_count, int)
        or isinstance(identity_count, bool)
        or identity_count < 0
        or (
            mode == "strict_identity"
            and (not _valid_launch_nonce(nonce) or identity_count < 1)
        )
        or (
            mode == "operator_attested"
            and (nonce is not None or identity_count != 0)
        )
    ):
        raise ValueError(
            "attended ephemeral archive verification evidence is invalid"
        )
    acknowledged_at = value.get("acknowledged_at")
    acknowledged_at_epoch = value.get("acknowledged_at_epoch")
    if (
        _utc_epoch(acknowledged_at) is None
        or isinstance(acknowledged_at_epoch, bool)
        or not isinstance(acknowledged_at_epoch, (int, float))
        or not math.isfinite(float(acknowledged_at_epoch))
        or float(acknowledged_at_epoch) < 0
    ):
        raise ValueError("attended ephemeral archive timestamp is invalid")
    reason = value.get("reason")
    if (
        not isinstance(reason, str)
        or not reason
        or len(reason) > 500
        or any(ord(char) < 32 for char in reason)
    ):
        raise ValueError("attended ephemeral archive reason is invalid")
    terminal = eph.validate_held_terminal(value.get("terminal"))
    if terminal is None:
        raise ValueError("attended ephemeral archive terminal facts are invalid")

    attended = {
        "schema_version": 1,
        "agent": agent,
        "request_id": request_id,
        "hold_source_hash": hold_source_hash,
        "acknowledged_by": actor,
        "verification_mode": mode,
        "verified_launch_nonce": nonce,
        "verified_identity_count": identity_count,
        "acknowledged_at": acknowledged_at,
        "reason": reason,
    }
    payload = value.get("archive_payload")
    expected_payload_fields = {
        "schema_version",
        "request_id",
        "terminal_state",
        "reason",
        "archived_at",
        "archived_at_epoch",
        "original",
        "completion",
        "agent",
        "attended_teardown",
    }
    marker = payload.get("original") if isinstance(payload, dict) else None
    if (
        not isinstance(payload, dict)
        or frozenset(payload) != expected_payload_fields
        or payload.get("schema_version") != eph.SCHEMA_VERSION
        or payload.get("request_id") != request_id
        or payload.get("terminal_state") != terminal["terminal_state"]
        or payload.get("reason") != terminal["reason"]
        or _utc_epoch(payload.get("archived_at")) is None
        or payload.get("archived_at_epoch") != acknowledged_at_epoch
        or payload.get("completion") != terminal["completion"]
        or payload.get("agent") != agent
        or payload.get("attended_teardown") != attended
        or not isinstance(marker, dict)
        or marker.get("request_id") != request_id
        or marker.get("agent") != agent
        or marker.get("state") not in eph.ACTIVE_STATES
        or eph.validate_marker(marker)
    ):
        raise ValueError("attended ephemeral archive payload is malformed")
    return copy.deepcopy(value)


def attended_ephemeral_archive_pending(
    state: dict,
    request_id: str,
) -> dict | None:
    """Return one validated pending attended archive, if present."""
    if not eph.is_safe_id(request_id):
        raise ValueError("ephemeral request id must be a safe path token")
    root = state.get("ephemeral_reviewers") if isinstance(state, dict) else None
    pending = (
        root.get("attended_archive_pending")
        if isinstance(root, dict)
        else None
    )
    if pending is None:
        return None
    if not isinstance(pending, dict) or len(pending) > 64:
        raise ValueError("attended ephemeral archive journals are malformed")
    raw = pending.get(request_id)
    if raw is None:
        return None
    record = _validate_attended_ephemeral_archive_pending(raw)
    if record["request_id"] != request_id:
        raise ValueError("attended ephemeral archive journal key is stale")
    return record


def stage_attended_ephemeral_archive(
    state: dict,
    request_id: str,
    *,
    agent: str,
    launch_marker: dict,
    held_terminal: dict,
    hold_source_hash: str,
    acknowledged_by: str,
    verification_mode: str,
    verified_launch_nonce: str | None,
    verified_identity_count: int,
    reason: str,
    now_epoch: float,
) -> dict:
    """Persist all authority and payload needed for an idempotent retry."""
    terminal = eph.validate_held_terminal(held_terminal)
    if terminal is None:
        raise ValueError("ephemeral HOLD has no valid terminal disposition")
    acknowledged_at = _event_now(now_epoch)
    attended = {
        "schema_version": 1,
        "agent": agent,
        "request_id": request_id,
        "hold_source_hash": hold_source_hash,
        "acknowledged_by": acknowledged_by,
        "verification_mode": verification_mode,
        "verified_launch_nonce": verified_launch_nonce,
        "verified_identity_count": verified_identity_count,
        "acknowledged_at": acknowledged_at,
        "reason": reason,
    }
    payload = eph.terminal_archive(
        launch_marker,
        terminal_state=terminal["terminal_state"],
        reason=terminal["reason"],
        at_epoch=now_epoch,
        extra={
            "completion": terminal["completion"],
            "agent": agent,
            "attended_teardown": attended,
        },
    )
    record = _validate_attended_ephemeral_archive_pending({
        "schema_version": 1,
        "request_id": request_id,
        "agent": agent,
        "hold_source_hash": hold_source_hash,
        "acknowledged_by": acknowledged_by,
        "verification_mode": verification_mode,
        "verified_launch_nonce": verified_launch_nonce,
        "verified_identity_count": verified_identity_count,
        "acknowledged_at": acknowledged_at,
        "acknowledged_at_epoch": now_epoch,
        "reason": reason,
        "terminal": terminal,
        "archive_payload": payload,
    })
    root = eph.ensure_state(state)
    pending = root.setdefault("attended_archive_pending", {})
    if not isinstance(pending, dict) or len(pending) > 64:
        raise ValueError("attended ephemeral archive journals are malformed")
    existing = pending.get(request_id)
    if existing is not None:
        if _validate_attended_ephemeral_archive_pending(existing) != record:
            raise ValueError(
                "a different attended archive is already pending for this request"
            )
        return record
    if len(pending) >= 64:
        raise ValueError("attended ephemeral archive journal cap is 64")
    pending[request_id] = copy.deepcopy(record)
    return record


def finish_attended_ephemeral_archive(
    store: Store,
    state: dict,
    request_id: str,
) -> dict:
    """Apply external effects for a staged archive, then finalize memory state."""
    record = attended_ephemeral_archive_pending(state, request_id)
    if record is None:
        raise ValueError(
            f"no attended ephemeral archive is pending for {request_id!r}"
        )
    root = eph.ensure_state(state)
    active = root["active"]
    entry = active.get(request_id)
    if (
        not isinstance(entry, dict)
        or entry.get("request_id") != request_id
        or entry.get("agent") != record["agent"]
        or eph.validate_held_terminal(entry.get("held_terminal"))
        != record["terminal"]
    ):
        raise ValueError(
            "active ephemeral HOLD changed after its attended archive was staged"
        )
    if not store.complete_launch_request_archive(
        request_id,
        record["archive_payload"],
    ):
        raise eph.EphemeralError(
            f"launch request {request_id!r} was not archived; journal retained"
        )
    agent = record["agent"]
    config = store.load_config()
    active_agents = config.get("agents") or []
    retired_agents = store.retired_agents()
    if agent in active_agents:
        store.retire_agent(
            agent,
            reason=(
                f"ephemeral review {request_id}: "
                f"{record['terminal']['terminal_state']}"
            ),
        )
    elif agent not in retired_agents:
        raise ValueError(
            f"temporary identity {agent!r} is neither active nor retired"
        )

    history = root.get("attended_archive_history")
    if not isinstance(history, list):
        history = []
    history.append({
        **record["archive_payload"]["attended_teardown"],
        "terminal_state": record["terminal"]["terminal_state"],
    })
    root["attended_archive_history"] = history[-64:]
    active.pop(request_id, None)
    pending = root.get("attended_archive_pending")
    if isinstance(pending, dict):
        pending.pop(request_id, None)
        if not pending:
            root.pop("attended_archive_pending", None)
    return copy.deepcopy(record["archive_payload"]["attended_teardown"])


def archive_ephemeral_request(store: Store, state: dict, request_id: str, *,
                              terminal_state: str, reason: str,
                              now_epoch: float | None = None,
                              completion: dict | None = None,
                              retire: bool = True,
                              extra: dict | None = None) -> dict:
    """Archive a terminal launch request and tombstone its temporary identity."""
    marker = store.read_launch_request(request_id)
    root = eph.ensure_state(state)
    entry = root["active"].get(request_id)
    entry = entry if isinstance(entry, dict) else {}
    agent = entry.get("agent") or (marker or {}).get("agent")
    retire_error = None
    if retire and isinstance(agent, str):
        try:
            cfg = store.load_config()
            if agent in (cfg.get("agents") or []):
                store.retire_agent(agent, reason=f"ephemeral review {request_id}: {terminal_state}")
        except ValueError as e:
            retire_error = str(e)
    archive_extra = {
        "completion": completion or {},
        "agent": agent,
        **(extra if isinstance(extra, dict) else {}),
    }
    if retire_error:
        archive_extra["retire_error"] = retire_error
    payload = eph.terminal_archive(
        marker,
        terminal_state=terminal_state,
        reason=reason,
        at_epoch=now_epoch,
        extra=archive_extra,
    )
    if not store.archive_launch_request(request_id, payload):
        raise eph.EphemeralError(
            f"launch request {request_id!r} was not archived; active state retained"
        )
    eph.forget_active(state, request_id)
    return state


def janitor_retire_ephemeral_orphan(store: Store, agent: str) -> bool:
    """Retire a stale active adversary-* identity left without supervisor state."""
    if not isinstance(agent, str) or not agent.startswith("adversary-"):
        return False
    try:
        cfg = store.load_config()
        if agent not in (cfg.get("agents") or []):
            return False
        store.retire_agent(agent, reason="ephemeral reviewer startup janitor")
        return True
    except ValueError:
        return False


